import type { CultureArticle } from "../types";

const items: CultureArticle[] = [{"id":"eur-032","version":2,"slug":"co-determination-german-workers-sit-on-the-board","contentType":"note","category":"work-and-education","title":{"ar":"الشراكة في القرار: عمّال ألمانيا في مجالس الإدارة","de":"Mitbestimmung: Beschäftigte sitzen im Aufsichtsrat","en":"Co-determination: German workers sit on the board"},"deck":{"ar":"في ألمانيا يجلس ممثلو العاملين إلى طاولة القرار العليا، في نظام يُعدّ الأوسع من نوعه في أوروبا.","de":"In Deutschland verhandeln Beschäftigte nicht nur am Werktor mit, sondern auch in den obersten Gremien großer Unternehmen.","en":"In Germany employees do not only negotiate at the factory gate; they also take seats in the top committees of large companies."},"teaser":{"ar":"نظام «ميتبستيمونغ» يمنح العاملين مقاعد في مجالس الإشراف بالشركات الكبرى، ويقترن بمجالس عمال تتفاوض داخل المصنع.","de":"Die Mitbestimmung gibt Beschäftigten Sitze in Aufsichtsräten und einen Betriebsrat, der auf Werksebene verhandelt – ein System mit eigenen Grenzen.","en":"Co-determination gives employees supervisory-board seats and a works council that negotiates at plant level, with limits that vary by company size."},"readingMinutes":1,"sections":{"ar":[{"heading":"مقاعد للعاملين في القمة","paragraphs":["يمنح نظام الشراكة في القرار في ألمانيا العاملين حقوق تمثيل في العمل، بينها مقاعد في مجالس الإشراف بالشركات الكبرى.","في الشركات الكبيرة يمكن لممثلي العاملين أن يشغلوا نحو نصف مقاعد مجلس الإشراف، إلى جانب مجلس عمال يتفاوض على مستوى المصنع.","ويختلف تطبيق النظام بحسب حجم الشركة والقطاع، كما تتباين عادات المشاركة بين الأجيال والمناطق، فتكون أكثر رسمية في الشركات الكبرى وأقلّها في غيرها."]},{"heading":"ميزة الهدوء الصناعي","paragraphs":["يُنسب إلى هذا النظام غالبًا انخفاض مستوى النزاعات الصناعية في ألمانيا وقرارات تنظر إلى المدى الطويل، وإن رأى منتقدون أنه قد يبطئ إعادة الهيكلة.","وتمثيل العاملين على مستوى الإدارة موجود بشكل ما في أغلبية دول الاتحاد الأوروبي ومنظمة التعاون الاقتصادي، لكن النظام الألماني هو الأوسع.","وتُوصف الشركات الصغيرة والمتوسطة، وكثير منها عائلي، بأنها عمود الاقتصاد الألماني، ولها تقاليدها الأقل رسمية في إشراك العاملين."]}],"de":[{"heading":"Vertretung bis in die Chefetage","paragraphs":["Die Mitbestimmung gibt Beschäftigten Rechte auf Vertretung im Betrieb, darunter Sitze in den Aufsichtsräten großer Unternehmen.","In großen Firmen können Beschäftigtenvertreter nahezu die Hälfte der Aufsichtsratssitze halten, ergänzt durch einen Betriebsrat, der auf Werksebene verhandelt.","Wie das System wirkt, hängt von Größe und Branche ab; auch regional und zwischen Generationen gibt es Unterschiede, etwa in der Selbstverständlichkeit, mit der Beschäftigte kandidieren."]},{"heading":"Weniger Konflikte, längere Sicht","paragraphs":["Dem System werden oft die vergleichsweise wenigen industriellen Konflikte und langfristige Entscheidungen zugeschrieben, Kritiker sehen darin aber eine Bremse für Umstrukturierungen.","Betriebliche Vertretung in Aufsichtsräten gibt es in irgendeiner Form in der Mehrheit der EU- und OECD-Länder, am weitesten reicht das deutsche Modell.","Der Mittelstand, oft familiengeführt, gilt als Rückgrat der Wirtschaft und pflegt eigene, weniger formale Traditionen der Beteiligung."]}],"en":[{"heading":"Representation up to the top table","paragraphs":["Germany's co-determination gives employees rights to representation at work, including seats on the supervisory boards of large companies.","In large firms employee representatives can hold nearly half of supervisory-board seats, alongside a works council that negotiates at plant level.","How it works depends on company size and sector, and habits of participation vary by region and generation, for instance in how readily people stand for election."]},{"heading":"Quieter conflict, longer horizons","paragraphs":["The system is often credited with Germany's relatively low levels of industrial conflict and with long-term decision-making, though critics say it can slow restructuring.","Board-level employee representation exists in some form in a majority of EU and OECD countries, but Germany's system is the most extensive.","The Mittelstand, small and medium-sized firms often family-owned, is described as the backbone of the German economy and has its own, less formal traditions of worker involvement."]}]},"context":{"countries":["DE"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["work-and-education","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Worker representation on corporate boards of directors","de":"Worker representation on corporate boards of directors","en":"Worker representation on corporate boards of directors"},"url":"https://en.wikipedia.org/wiki/Worker_representation_on_corporate_boards_of_directors","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mittelstand","de":"Mittelstand","en":"Mittelstand"},"url":"https://en.wikipedia.org/wiki/Mittelstand","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عامل تشغيل في مصنع سيارات ألماني يترشح لمجلس العمال؛ وبعد ذلك يسائل ممثل للعاملين في مجلس الإشراف خطة لإغلاق مصنع.","de":"Ein Maschinenbediener in einem deutschen Autowerk kandidiert für den Betriebsrat; später hinterfragt ein Beschäftigtenvertreter im Aufsichtsrat einen Werksschließungsplan.","en":"A machine operator at a German car plant stands for election to the works council; later, an employee representative on the supervisory board questions a factory closure plan."},"misunderstanding":{"ar":"يُفهم النظام أحيانًا كأنه يمنح العاملين سلطة إدارة يومية، لكنه في الواقع تمثيل واستشارة وتفاوض، وي coexiste مع ضغوط خفض التكاليف.","de":"Manchmal wird Mitbestimmung als Mitsprache im Tagesgeschäft verstanden; tatsächlich geht es um Vertretung, Beratung und Verhandlung, die mit hartem Kostendruck zusammen bestehen.","en":"Co-determination is sometimes mistaken for day-to-day management power; in practice it is representation, consultation and negotiation, and it coexists with tough cost-cutting."},"comparison":{"ar":"يختلف عن نماذج أوروبية أخرى أقل اتساعًا، ويقترن في الشركات العائلية الصغيرة بتقاليد غير رسمية للمشاركة.","de":"Andere europäische Modelle sind meist schmaler; im familiennahen Mittelstand herrschen informellere Formen der Beteiligung.","en":"Other European models are usually narrower, while family-run Mittelstand firms rely on informal involvement rather than board seats."}},{"id":"eur-033","version":2,"slug":"ostalgie-remembering-east-germany-one-product-at-a-time","contentType":"note","category":"cultural-change","title":{"ar":"الحنين إلى الشرق الألماني عبر المنتجات","de":"Ostalgie: Erinnerung an den Osten in Produkten","en":"Ostalgie: remembering East Germany through its products"},"deck":{"ar":"ظاهرة أوستالجي تعيد إلى الأذهان طفولة ألمانيا الشرقية، لا نظامها السياسي، وتكشف تفاوتات الوحدة.","de":"Ostalgie meint Kindheit und Vertrautheit, nicht die Rückkehr der DDR, und erzählt von den Ungleichheiten der Wiedervereinigung.","en":"Ostalgie is about childhood and familiarity, not restoring the GDR, and it reveals the uneven terms of reunification."},"teaser":{"ar":"من مخلل شبرفالد إلى فيتا كولا، يحكي شرقيون ألمان عن ماضيهم عبر نكهات وأنماط حياة مألوفة.","de":"Von Spreewaldgurken bis Vita Cola: Ostdeutsche erzählen ihre Geschichte über vertraute Geschmäcker und Alltagsgewohnheiten.","en":"From Spreewald gherkins to Vita Cola, eastern Germans tell their story through familiar tastes and everyday habits."},"readingMinutes":1,"sections":{"ar":[{"heading":"من أين جاء المصطلح؟","paragraphs":["صاغ الكوميدي الألماني الشرقي أوفه شتايمله مصطلح «أوستالجي» عام 1992، وهو دمج بين «أوست» أي الشرق و«نوستالجي» أي الحنين. صار المصطلح ظاهرة ثقافية مرئية في التسعينيات والألفينيات، حين عادت منتجات شرقية مثل مخلل شبرفالد وفيتا كولا إلى الرفوف، وحوّل فيلم «وداعاً لينين!» (2003) التجربة إلى كوميديا.","يميّز الباحثون بين الحنين إلى الأشياء والعادات والحنين إلى النظام السياسي، فمعظم أوستالجي يتعلق بالطفولة والألفة لا بالرغبة في استعادة جمهورية ألمانيا الديمقراطية. وتختلف حدّة هذا الشعور بين الأجيال والمناطق، إذ يخفّ لدى الشرقيين الأصغر سناً."]},{"heading":"ذاكرة تفصح عن تفاوتات الوحدة","paragraphs":["تعكس الظاهرة أيضاً شروط الوحدة غير المتكافئة، فسير الشرقيين وشهاداتهم ومنتجاتهم كثيراً ما جرى التقليل من قيمتها بعد عام 1990. يقرأ ألمان غربيون أحياناً هذا الحنين كمراجعة سياسية، بينما يستخدمه آخرون لتبخيس شكاوى مشروعة.","في سوق بلايبزيغ تُباع ماركة خردل اختفت بعد 1990 ثم أُعيد إطلاقها؛ يشتريها جد ويسأل حفيده عن سبب الضجة."]}],"de":[{"heading":"Woher der Begriff kommt","paragraphs":["Der ostdeutsche Komiker Uwe Steimle prägte 1992 den Begriff Ostalgie, ein Kofferwort aus Ost und Nostalgie. In den 1990er- und 2000er-Jahren wurde das Phänomen sichtbar: Spreewaldgurken und Vita Cola kehrten in die Regale zurück, und Filme wie Good Bye Lenin! (2003) machten die Erfahrung zur Komödie.","Forschende unterscheiden Nostalgie für Dinge und Gewohnheiten von Nostalgie für das politische System. Meist geht es um Kindheit und Vertrautheit, nicht um den Wunsch, die DDR wiederherzustellen. Je nach Region und Generation ist das Gefühl unterschiedlich stark, bei jüngeren Ostdeutschen schwächer."]},{"heading":"Erinnerung an ungleiche Einheit","paragraphs":["Das Phänomen spiegelt auch die ungleichen Bedingungen der Wiedervereinigung: Biografien, Abschlüsse und Produkte Ostdeutscher wurden nach 1990 oft abgewertet. Westdeutsche deuten Ostalgie mitunter als politische Verklärung, andere nutzen den Begriff, um berechtigte Klagen zu entwerten.","In einem Leipziger Supermarkt gibt es eine Senfmarke, die nach 1990 verschwand und neu aufgelegt wurde; ein Großelternteil kauft sie, ein Enkel fragt nach dem Aufhebens."]}],"en":[{"heading":"Where the word came from","paragraphs":["The East German comedian Uwe Steimle coined the term Ostalgie in 1992, a portmanteau of Ost (east) and Nostalgie. It became a visible cultural phenomenon in the 1990s and 2000s: Spreewald gherkins and Vita Cola returned to shelves, and films such as Good Bye Lenin! (2003) turned the experience into comedy.","Researchers distinguish nostalgia for things and habits from nostalgia for the political system; most Ostalgie is about childhood and familiarity rather than a wish to restore the GDR. The feeling varies by region and generation, and is weaker among younger eastern Germans."]},{"heading":"Memory that exposes unequal unity","paragraphs":["The phenomenon also reflects the unequal terms of reunification: East Germans' biographies, qualifications and products were often devalued after 1990. Western Germans sometimes misread Ostalgie as political revisionism, while others use the term to dismiss legitimate complaints.","A Leipzig supermarket sells a brand of mustard that disappeared after 1990 but was relaunched; a grandparent buys it and a grandchild asks what the fuss is about."]}]},"context":{"countries":["DE"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["cultural-change","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Ostalgie","de":"Ostalgie","en":"Ostalgie"},"url":"https://en.wikipedia.org/wiki/Ostalgie","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"East Germany","de":"East Germany","en":"East Germany"},"url":"https://en.wikipedia.org/wiki/East_Germany","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في سوق بلايبزيغ تُباع ماركة خردل اختفت بعد 1990 ثم أُعيد إطلاقها؛ يشتريها جد ويسأل حفيده عن سبب الضجة.","de":"In einem Leipziger Supermarkt gibt es eine Senfmarke, die nach 1990 verschwand und neu aufgelegt wurde; ein Großelternteil kauft sie, ein Enkel fragt nach dem Aufhebens.","en":"A Leipzig supermarket sells a brand of mustard that disappeared after 1990 but was relaunched; a grandparent buys it and a grandchild asks what the fuss is about."},"misunderstanding":{"ar":"يقرأ بعض ألمان الغرب هذا الحنين كمراجعة سياسية أو رغبة في إعادة النظام، بينما هو غالباً تعلّق بالطفولة والألفة.","de":"Viele Westdeutsche lesen Ostalgie als politische Verklärung oder Wunsch nach Rückkehr des Systems, obwohl sie meist Kindheit und Vertrautheit meint.","en":"Western Germans often read Ostalgie as political revisionism or a wish to restore the system, when it is mostly about childhood and familiarity."},"comparison":{"ar":"يشبه أوستالجي حنيناً مماثلاً في بلدان أخرى إلى منتجات زالت بعد تغيّر الأنظمة، لكنه في ألمانيا مرتبط تحديداً بتفاوتات إعادة التوحيد.","de":"Ähnliche Nostalgie für verschwundene Produkte gibt es auch anderswo nach Systemwechseln, doch in Deutschland ist sie eng mit den Ungleichheiten der Wiedervereinigung verbunden.","en":"Similar nostalgia for vanished products appears elsewhere after system changes, but in Germany it is tied specifically to the inequalities of reunification."}},{"id":"eur-034","version":2,"slug":"the-doner-kebab-and-the-making-of-turkish-germany","contentType":"note","category":"migration-and-identity","title":{"ar":"الدونر كباب يصنع ألمانيا التركية","de":"Döner Kebab und die Entstehung der türkischen Deutschen","en":"The Döner Kebab and the Making of Turkish Germany"},"deck":{"ar":"كيف أصبح شطيرة اللحم المشوي رمزًا لهجرة استمرت أجيالًا.","de":"Wie ein Fleischspieß im Brot zum Symbol einer Einwanderungsgeschichte wurde.","en":"How a rotisserie meat sandwich became a symbol of a migration story spanning generations."},"teaser":{"ar":"من اتفاقية العمل 1961 إلى مطاعم الأحياء، يحكي الدونر كباب قصة العمال الأتراك الذين صاروا جزءًا من نسيج ألمانيا.","de":"Vom Anwerbeabkommen 1961 bis zum Imbiss um die Ecke erzählt der Döner von türkischen Gastarbeitern, die Teil Deutschlands wurden.","en":"From the 1961 labour agreement to the neighbourhood shop, the döner tells the story of Turkish guest workers who became part of Germany."},"readingMinutes":1,"sections":{"ar":[{"heading":"من السيخ إلى الشارع","paragraphs":["الدونر كباب هو لحم يُشوى على سيخ دوار، وهي تقنية تعود إلى الدولة العثمانية في القرن التاسع عشر. أما النسخة الحديثة كشطيرة فقد شاعت في برلين الغربية في السبعينيات بفضل مهاجرين أتراك.","في عام 1961 وقعت ألمانيا وتركيا اتفاقية استقدام عمال، فجاء «العمال الضيوف» إلى الصناعة الألمانية. كثيرون بقوا وأحضروا عائلاتهم وبنوا مجتمعًا دائمًا."]},{"heading":"حياة الحي","paragraphs":["أصبح محل الدونر مؤسسة في الحي، وعلامة بارزة على الهجرة في المدن الألمانية، إلى جانب البقالة التركية والمخبز ووكالة السفر. ويُعدّ الطعام ألمانيًا إلى حد أنه وجبة منتصف الليل المعتادة وموضوع جدل حول الأسعار ومنافسات إقليمية. ويختلف الأمر بين الأجيال والمناطق: فالشباب في برلين قد يطلبونه «مع كل شيء»، بينما تفضّل عائلات في المدن الصغيرة وصفات بيتية."]}],"de":[{"heading":"Vom Spieß auf die Straße","paragraphs":["Döner Kebab ist Fleisch am vertikalen Drehspieß, eine Technik aus dem Osmanischen Reich des 19. Jahrhunderts. Die moderne Sandwich-Version wurde in den 1970er-Jahren in West-Berlin von türkischen Einwanderern populär gemacht.","1961 unterzeichneten Deutschland und die Türkei ein Anwerbeabkommen, das „Gastarbeiter“ in die Industrie brachte. Viele blieben, holten ihre Familien nach und bauten eine dauerhafte Gemeinschaft auf."]},{"heading":"Leben im Viertel","paragraphs":["Der Dönerladen wurde zur Institution im Viertel und zu einem der sichtbarsten Zeichen der Migration in deutschen Städten, neben türkischem Lebensmittelgeschäft, Bäckerei und Reisebüro. Das Essen ist so deutsch geworden, dass der Döner ein Standard-Spätimbiss und Gegenstand von Preisdebatten und regionalen Rivalitäten ist. Je nach Region und Generation unterscheidet sich das: Jugendliche in Berlin bestellen „mit alles“, während Familien in Kleinstädten oft Hausmannskost vorziehen."]}],"en":[{"heading":"From the Spit to the Street","paragraphs":["The döner kebab is meat cooked on a vertical rotisserie, a technique from the 19th-century Ottoman Empire. The modern sandwich version was popularised in 1970s West Berlin by Turkish immigrants.","In 1961 Germany and Turkey signed a labour recruitment agreement, bringing 'guest workers' to German industry. Many stayed, brought families and built a permanent community."]},{"heading":"Life in the Neighbourhood","paragraphs":["The döner shop became a neighbourhood institution and one of the most visible signs of migration in German cities, alongside the Turkish grocery, bakery and travel agency. The food is now so thoroughly German that the döner is a standard late-night meal and a subject of price debates and regional rivalries. It varies by region and generation: teenagers in Berlin order it 'mit alles', while families in small towns often prefer home cooking."]}]},"context":{"countries":["DE"],"region":"Central Europe","community":"Turkish Germans","continent":"europe","languages":["de","tr"],"period":"contemporary"},"tags":["migration-and-identity","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Doner kebab","de":"Doner kebab","en":"Doner kebab"},"url":"https://en.wikipedia.org/wiki/Doner_kebab","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Turks in Germany","de":"Turks in Germany","en":"Turks in Germany"},"url":"https://en.wikipedia.org/wiki/Turks_in_Germany","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في برلين-كرويتسبرغ يُطلب الدونر «مع كل شيء» ويُؤكل واقفًا في منتصف الليل؛ المحل تديره عائلة من الأناضول والزبائن شرائح من المدينة.","de":"In Berlin-Kreuzberg bestellt man einen Döner „mit alles“ und isst ihn um Mitternacht im Stehen; der Laden wird von einer Familie aus Anatolien geführt, und die Kundschaft ist ein Querschnitt der Stadt.","en":"In Berlin-Kreuzberg a döner is ordered 'mit alles' and eaten standing up at midnight; the shop is run by a family from Anatolia and the customers are a cross-section of the city."},"misunderstanding":{"ar":"«ألمانيا التركية» ليست مجتمعًا واحدًا: تضم أكرادًا وعلويين وآشوريين وغيرهم، والأجيال تختلف بحدة في اللغة والدين والسياسة؛ كما أن قصة أصل الدونر متنازع عليها بين بائعي برلين.","de":"„Türkisches Deutschland“ ist keine einzige Gemeinschaft: Sie umfasst Kurden, Aleviten, Assyrer und andere, und die Generationen unterscheiden sich stark in Sprache, Religion und Politik; auch die Ursprungsgeschichte des Döners ist unter Berliner Verkäufern umstritten.","en":"'Turkish Germany' is not one community: it includes Kurds, Alevis, Assyrians and others, and generations differ sharply in language, religion and politics; the döner's origin story is also contested among Berlin vendors."},"comparison":{"ar":"في تركيا يُقدّم الدونر غالبًا في طبق مع الأرز، بينما في ألمانيا صار شطيرة سريعة تُؤكل أثناء التنقل.","de":"In der Türkei wird Döner oft als Teller mit Reis serviert, in Deutschland ist er ein schnelles Sandwich für unterwegs.","en":"In Turkey the döner is often served on a plate with rice, while in Germany it became a quick sandwich eaten on the go."}},{"id":"eur-035","version":2,"slug":"german-humour-and-the-stereotype-of-seriousness","contentType":"note","category":"regional-humour","title":{"ar":"الفكاهة الألمانية وما وراء الجديّة","de":"Deutscher Humor und das Klischee vom Ernst","en":"German humour and the seriousness stereotype"},"deck":{"ar":"كيف يتعامل الألمان مع النكات، ولماذا يبدو الجدّ وجهًا كوميديًا في أحيان كثيرة.","de":"Warum ein ernstes Gesicht oft Teil der Pointe ist und wie regional unterschiedlich gelacht wird.","en":"Why a straight face is often part of the punchline, and how laughter shifts by region."},"teaser":{"ar":"صورة الألماني بلا حسّ فكاهي قديمة جدًا، لكن الكوميديا الألمانية تعرف كيف تلعب بها وتقلبها على الجمهور.","de":"Das Klischee vom humorlosen Deutschen ist alt, doch die deutsche Komik spielt selbst gern damit und dreht es um.","en":"The idea that Germans have no sense of humour is a durable stereotype, and German comedy often plays with it directly."},"readingMinutes":1,"sections":{"ar":[{"heading":"الجدّ كأداة كوميدية","paragraphs":["تُعدّ فكرة أن الألمان لا يملكون حسًّا فكاهيًا من أكثر الصور النمطية رسوخًا، والكوميديا الألمانية غالبًا ما تلعب بها مباشرة. ومن أبرز أشكالها اسكتشات الممثل لوريوت الذي يعتمد على وجه جامد، فتكشف شخصياته عبث البيروقراطية الألمانية وأخلاقيات التعامل اليومي.","هذا الأسلوب الجامد ليس فشلًا في إيصال النكتة، بل جزء منها. وتختلف النكات من جيل إلى جيل ومن منطقة إلى أخرى، فما يضحك جمهور برلين قد لا يضحك له جمهور شوابيا."]},{"heading":"من الكاباريه إلى الإنترنت","paragraphs":["عرفت ألمانيا تقليدًا قويًا للكاباريه، أي السخرية السياسية التي تُقدَّم على المسرح، وقد ازدهر في عهد جمهورية فايمار ثم قُمع في عهد النازيين.","تشمل الفكاهة الشائعة التلاعب بالألفاظ والكوميديا الإقليمية وخطب الكرنفال. ودخلت كلمة شادنفرويده الإنجليزية من الألمانية، وكثيرًا ما تُذكر دليلًا على نبرة كوميدية ألمانية خاصة، وإن كانت الصورة النمطية تقول عن الألمان أكثر مما تقول عنهم فعلًا."]}],"de":[{"heading":"Ernst als komisches Werkzeug","paragraphs":["Die Vorstellung, Deutsche hätten keinen Sinn für Humor, ist ein zäher Stereotyp, und die deutsche Komödie spielt oft direkt damit. Zu den bekanntesten Formen gehören die todernste Sketche von Loriot, dessen Figuren die Absurdität deutscher Bürokratie und Umgangsformen entlarven.","Diese todernste Art ist kein Scheitern der Pointe, sondern Teil davon. Und der Humor unterscheidet sich je nach Generation und Region: Was ein Berliner Publikum lustig findet, muss ein schwäbisches Publikum noch lange nicht lustig finden."]},{"heading":"Vom Kabarett bis ins Netz","paragraphs":["Deutschland hat eine starke Tradition des Kabaretts, also der politischen Satire auf der Bühne, die in der Weimarer Republik blühte und unter den Nazis unterdrückt wurde.","Zum verbreiteten Humor gehören Wortspiele, regionale Komik und Karnevalsreden. Das Wort Schadenfreude kam aus dem Deutschen ins Englische und wird oft als Beleg für ein eigenes deutsches Komikregister angeführt, doch das Klischee sagt mehr über Großbritannien und die USA aus als über Deutschland."]}],"en":[{"heading":"Deadpan as a comic tool","paragraphs":["The idea that Germans have no sense of humour is a durable stereotype, and German comedy often plays with it directly. Among its best-known forms are the deadpan sketches of Loriot, whose characters expose the absurdity of German bureaucracy and manners.","That deadpan delivery is not a failed joke but part of it. And humour varies by generation and region: what a Berlin audience finds funny a Swabian audience may not."]},{"heading":"From cabaret to the internet","paragraphs":["Germany has a strong tradition of Kabarett, political satire performed in cabarets, which flourished in the Weimar Republic and was suppressed under the Nazis.","Popular humour includes wordplay, regional comedy and carnival speeches. The word Schadenfreude entered English from German and is often cited as evidence of a distinctively German comic register, though the stereotype says more about British and American self-images than about Germany."]}]},"context":{"countries":["DE"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["regional-humour","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"German humour","de":"German humour","en":"German humour"},"url":"https://en.wikipedia.org/wiki/German_humour","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kabarett","de":"Kabarett","en":"Kabarett"},"url":"https://en.wikipedia.org/wiki/Kabarett","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زميل ألماني يردّ على نكتة بوجه جامد تمامًا، ثم يُطلق مفاجأة النكتة؛ فالأداء الجامد جزء من النكتة لا دليل على فشلها.","de":"Ein deutscher Kollege antwortet auf einen Witz mit völlig ernstem Gesicht und liefert dann die Pointe; die todernste Art gehört zum Witz und ist kein Zeichen dafür, dass er misslungen ist.","en":"A German colleague replies to a joke with a perfectly straight face, then delivers the punchline; the deadpan delivery is part of the joke, not a sign that it failed."},"misunderstanding":{"ar":"كثيرون يظنون أن الوجه الجامد علامة على عدم الفهم، بينما هو في كثير من الأحيان أسلوب مقصود لإيصال النكتة.","de":"Viele halten das ernste Gesicht für Unverständnis, dabei ist es oft eine bewusste Form der Pointe.","en":"Many take the straight face as a sign of not getting the joke, when it is often a deliberate way of landing it."},"comparison":{"ar":"الصورة النمطية تكشف عن نظرة البريطانيين والأمريكيين إلى أنفسهم أكثر مما تكشف عن ألمانيا، والكوميديا الألمانية اليوم متنوعة: كوميديا ألمانية-تركية ونسوية وإنترنت غيّرت ما يضحك له الجمهور.","de":"Heute ist die deutsche Komödie vielfältig: deutsch-türkische, feministische und Internet-Komik haben verändert, worüber das Publikum lacht.","en":"German comedy is now diverse: Turkish-German, feminist and internet comedy have changed what audiences laugh at."}},{"id":"eur-036","version":2,"slug":"why-german-sundays-stay-quiet","contentType":"note","category":"everyday-life","title":{"ar":"لماذا يبقى الأحد الألماني هادئًا","de":"Warum der deutsche Sonntag ruhig bleibt","en":"Why German Sundays stay quiet"},"deck":{"ar":"قانون إغلاق المتاجر وحماية الدستور ليوم الراحة يشكلان أحدًا مختلفًا في ألمانيا.","de":"Ladenschlussgesetz und Verfassungsschutz machen den Sonntag zu einem besonderen Ruhetag.","en":"Shop-closing law and constitutional protection make Sunday a different kind of day in Germany."},"teaser":{"ar":"في ألمانيا، معظم المتاجر مغلقة يوم الأحد، وهو تقليد متجذر في القانون والدستور، ويؤثر على حياة الأسرة والترفيه.","de":"In Deutschland sind die meisten Geschäfte am Sonntag geschlossen – eine Regel, die im Gesetz und im Grundgesetz verankert ist und das Familienleben prägt.","en":"In Germany, most shops are closed on Sundays—a rule rooted in law and the constitution that shapes family life and leisure."},"readingMinutes":1,"sections":{"ar":[{"heading":"قانون الأحد الهادئ","paragraphs":["في ألمانيا، تُغلق معظم المتاجر أبوابها يوم الأحد. هذا ليس مجرد عرف، بل هو منصوص عليه في قانون إغلاق المتاجر وفي حماية الدستور ليوم الأحد والعطلات الرسمية كأيام راحة.","الراحة ليست اختيارية: الأعمال المزعجة مثل الحفر أو جز العشب محظورة، وقد يتصل الجيران بالشرطة في الحالات الخطيرة. لكن هناك استثناءات للمخابز ومحطات الوقود ومحطات القطار والمناطق السياحية، بالإضافة إلى بضعة أيام أحد مفتوحة للتسوق سنويًا."]},{"heading":"حياة عائلية وترفيه","paragraphs":["يشكل الأحد المحمي حياة العائلة والترفيه: الزيارات والنزهات والكنيسة وأنشطة النوادي تحدث يوم الأحد، وكثير من الألمان يدافعون عن الإغلاق ضد الضغوط التجارية.","النقاش مستمر: تجار التجزئة وبعض العمال يريدون مزيدًا من المرونة، بينما الكنائس والنقابات والعديد من المواطنين يدافعون عن يوم الراحة. تختلف الإغلاقات حسب الولاية والبلدية، والتسوق عبر الإنترنت غيّر التأثير العملي؛ في المدن السياحية والمحطات قد يبدو الأحد كأي يوم آخر."]}],"de":[{"heading":"Das Gesetz der Ruhe","paragraphs":["In Deutschland sind die meisten Geschäfte am Sonntag geschlossen. Das ist nicht nur Brauch, sondern im Ladenschlussgesetz und im verfassungsrechtlichen Schutz des Sonntags und der Feiertage als Ruhetage verankert.","Die Ruhe wird durchgesetzt: Laute Heimwerkerarbeiten, Rasenmähen und manche Sportarten sind eingeschränkt, Nachbarn können in ernsten Fällen die Polizei rufen. Es gibt Ausnahmen: Bäckereien, Tankstellen, Bahnhöfe und Touristenorte dürfen öffnen, und einige verkaufsoffene Sonntage pro Jahr sind erlaubt."]},{"heading":"Familienleben und Freizeit","paragraphs":["Der geschützte Sonntag prägt Familienleben und Freizeit: Besuche, Spaziergänge, Kirche und Vereinsaktivitäten finden am Sonntag statt, und viele Deutsche verteidigen die Schließung gegen kommerziellen Druck.","Die Debatte dauert an: Einzelhandelsverbände und einige Arbeitnehmer wollen mehr Flexibilität, während Kirchen, Gewerkschaften und viele Bürger den freien Tag verteidigen. Die Schließungen variieren je nach Bundesland und Gemeinde, und Online-Shopping hat die praktische Wirkung verändert; in Touristenstädten und an Bahnhöfen kann der Sonntag wie jeder andere Tag aussehen."]}],"en":[{"heading":"The law of rest","paragraphs":["In Germany, most shops are closed on Sundays. This is not just custom but is anchored in the shop-closing law and in the constitutional protection of Sunday and public holidays as days of rest.","Rest is enforced: noisy DIY work, lawn-mowing and some sports are restricted, and neighbours may call the police in serious cases. There are exceptions: bakeries, petrol stations, railway stations and tourist areas can open, and a few 'verkaufsoffene Sonntage' a year are allowed for shopping."]},{"heading":"Family life and leisure","paragraphs":["The protected Sunday shapes family life and leisure: visits, walks, church and club activities happen on Sundays, and many Germans defend the closure against commercial pressure.","The debate is ongoing: retail lobbies and some workers want more flexibility, while churches, unions and many citizens defend the day off. Sunday closures vary by state and municipality, and online shopping has changed the practical effect; in tourist cities and at stations Sunday can look much like any other day."]}]},"context":{"countries":["DE"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["everyday-life","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sunday shopping","de":"Sunday shopping","en":"Sunday shopping"},"url":"https://en.wikipedia.org/wiki/Sunday_shopping","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Germany","de":"Culture of Germany","en":"Culture of Germany"},"url":"https://en.wikipedia.org/wiki/Culture_of_Germany","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة ألمانية تقوم بالأعمال المنزلية والتسوق يوم السبت، ثم تقضي الأحد في المشي وزيارة الأقارب وتناول الكعك بعد الظهر، دون أي متاجر مفتوحة.","de":"Eine deutsche Familie erledigt Hausarbeit und Einkäufe am Samstag und verbringt den Sonntag mit Spaziergängen, Verwandtenbesuchen und Kaffee und Kuchen am Nachmittag – ohne geöffnete Geschäfte.","en":"A German family does housework and shopping on Saturday, then spends Sunday walking, visiting relatives and eating cake in the afternoon, with no shops open."},"misunderstanding":{"ar":"يعتقد البعض أن إغلاق الأحد مجرد عادة قديمة، لكنه في الواقع محمي دستوريًا وله استثناءات محددة.","de":"Manche halten die Sonntagsschließung für eine veraltete Gewohnheit, doch sie ist verfassungsrechtlich geschützt und hat klare Ausnahmen.","en":"Some think Sunday closure is just an old habit, but it is constitutionally protected and has specific exceptions."},"comparison":{"ar":"في دول أخرى، قد تكون المتاجر مفتوحة طوال الأسبوع، لكن ألمانيا تحافظ على يوم راحة أسبوعي.","de":"In anderen Ländern sind Geschäfte oft die ganze Woche geöffnet, doch Deutschland hält an einem wöchentlichen Ruhetag fest.","en":"In other countries, shops may open all week, but Germany maintains a weekly day of rest."}},{"id":"eur-037","version":2,"slug":"du-or-sie-the-grammar-of-german-distance","contentType":"language","category":"communication","title":{"ar":"du و Sie: قواعد المسافة الألمانية","de":"Du oder Sie: Die Grammatik der Distanz","en":"Du or Sie: The Grammar of German Distance"},"deck":{"ar":"كيف يحدد اختيار الضمير العلاقات الاجتماعية في ألمانيا والنمسا وسويسرا","de":"Wie die Wahl des Pronomens Beziehungen in Deutschland, Österreich und der Schweiz prägt","en":"How pronoun choice shapes relationships in Germany, Austria, and Switzerland"},"teaser":{"ar":"في الألمانية، اختيار بين du و Sie ليس مجرد مسألة لغوية، بل هو قرار اجتماعي دقيق يعكس المسافة أو القرب بين الناس.","de":"Im Deutschen ist die Wahl zwischen du und Sie nicht nur eine sprachliche Frage, sondern eine soziale Entscheidung, die Nähe oder Distanz signalisiert.","en":"In German, choosing between du and Sie is not just a linguistic matter but a social decision that signals closeness or distance."},"readingMinutes":1,"sections":{"ar":[{"heading":"اختيار الضمير كحدث اجتماعي","paragraphs":["تحتوي اللغة الألمانية على ضميرين لـ 'أنت': du للعلاقات الوثيقة وغير الرسمية، و Sie للمسافة الرسمية. اختيار الضمير الخاطئ قد يسبب موقفًا اجتماعيًا محرجًا.","تختلف صيغ الفعل تبعًا للضمير، والانتقال من Sie إلى du يتطلب عادة عرضًا، غالبًا من الشخص الأكبر أو الأعلى مرتبة: 'Wir können uns duzen' (يمكننا أن نكون غير رسميين).","تتباين المعايير حسب السياق: في فريق عمل صغير قد يستخدم الزملاء du من اليوم الأول، بينما يظل Sie في بنك أو مكتب حكومي قائمًا لعقود."]},{"heading":"اختلافات إقليمية وأجيال","paragraphs":["تختلف قواعد du/Sie بين ألمانيا والنمسا وسويسرا، وكذلك بين المناطق والأجيال. العديد من الناس يستخدمون du في مواقف أكثر الآن، والضمير الخاطئ عادة ما يُغتفر بدل أن يكون قاتلًا.","توجد أشكال هجينة مثل 'Hamburger Sie' (الاسم الأول مع Sie)، والشباب الألمان يستخدمون du بشكل متزايد، بما في ذلك في العمل. نفس التمييز بين tu/vous موجود في الفرنسية ولغات أوروبية أخرى، لكن الألمانية غير عادية في وضوحها بشأن التفاوض على التبديل."]}],"de":[{"heading":"Die Pronomenwahl als soziales Ereignis","paragraphs":["Das Deutsche hat zwei Pronomen für 'you': du für enge, informelle Beziehungen und Sie für formale Distanz. Die falsche Wahl ist ein kleines soziales Ereignis.","Die Verbformen unterscheiden sich, und der Wechsel von Sie zu du erfordert normalerweise ein Angebot, oft von der älteren oder ranghöheren Person ('Wir können uns duzen').","Die Normen variieren je nach Kontext: Kollegen in einem kleinen Team können vom ersten Tag an du verwenden, während eine Bank oder ein Regierungsbüro Sie behält, manchmal jahrzehntelang."]},{"heading":"Regionale und generationelle Unterschiede","paragraphs":["Die Du/Sie-Regeln unterscheiden sich zwischen Deutschland, Österreich und der Schweiz sowie zwischen Regionen und Generationen. Viele Menschen verwenden du heute in mehr Situationen, und ein falsches Pronomen wird normalerweise verziehen statt fatal.","Es gibt Hybridformen wie das 'Hamburger Sie' (Vorname plus Sie), und jüngere Deutsche verwenden zunehmend du, auch bei der Arbeit. Dieselbe tu/vous-Unterscheidung gibt es im Französischen und anderen europäischen Sprachen, aber Deutsch ist ungewöhnlich explizit in der Aushandlung des Wechsels."]}],"en":[{"heading":"Pronoun choice as a social event","paragraphs":["German has two pronouns for 'you': du for close, informal relationships and Sie for formal distance. Choosing wrong is a small social event.","The verb forms differ, and the switch from Sie to du usually requires an offer, often from the older or more senior person ('Wir können uns duzen').","Norms vary by context: colleagues in a small team may use du from day one, while a bank or government office keeps Sie, sometimes for decades."]},{"heading":"Regional and generational variation","paragraphs":["Du/Sie rules differ between Germany, Austria, and Switzerland and between regions and generations. Many people now use du in more situations, and a wrong pronoun is usually forgiven rather than fatal.","Hybrid forms exist, such as the 'Hamburger Sie' (first name plus Sie), and younger Germans increasingly use du, including at work. The same tu/vous distinction exists in French and other European languages, but German is unusually explicit about negotiating the switch."]}]},"context":{"countries":["DE","AT","CH"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["communication","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"T–V distinction","de":"T–V distinction","en":"T–V distinction"},"url":"https://en.wikipedia.org/wiki/T%E2%80%93V_distinction","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific","de":"Honorific","en":"Honorific"},"url":"https://en.wikipedia.org/wiki/Honorific","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظف جديد ينادي زميلًا أكبر منه بـ 'Herr Schmidt' لشهور؛ بعد عشاء مشروع يقول الزميل 'Wir können uns duzen'، وفي الصباح التالي يصبح du طبيعيًا.","de":"Ein neuer Mitarbeiter nennt einen älteren Kollegen monatelang 'Herr Schmidt'; nach einem Projektessen sagt der Kollege 'Wir können uns duzen', und am nächsten Morgen fühlt sich das 'du' natürlich an.","en":"A new employee calls a senior colleague 'Herr Schmidt' for months; after a project dinner the colleague says 'Wir können uns duzen', and the next morning the 'du' feels natural."},"misunderstanding":{"ar":"الاعتقاد بأن du أكثر ودية دائمًا قد يكون خطأً؛ في بعض السياقات الرسمية، قد يُنظر إلى du على أنه قلة احترام.","de":"Die Annahme, dass du immer freundlicher ist, kann falsch sein; in manchen formellen Kontexten kann du als respektlos empfunden werden.","en":"Assuming du is always friendlier can be wrong; in some formal contexts, du may be seen as disrespectful."},"comparison":{"ar":"مثل التمييز بين tu و vous في الفرنسية، لكن الألمانية أكثر صراحة في التفاوض على الانتقال بين الضميرين.","de":"Ähnlich der tu/vous-Unterscheidung im Französischen, aber Deutsch ist expliziter in der Aushandlung des Wechsels.","en":"Similar to the tu/vous distinction in French, but German is more explicit about negotiating the switch."},"expression":{"original":"Du / Sie","language":"Deutsch","gloss":{"ar":"أنت غير رسمي / أنت رسمي","de":"informelles du / formelles Sie","en":"informal you / formal you"},"usage":{"ar":"يستخدم du مع الأصدقاء والعائلة والزملاء المقربين، و Sie مع الغرباء والرسميين.","de":"du mit Freunden, Familie und engen Kollegen; Sie mit Fremden und in formellen Situationen.","en":"Use du with friends, family, and close colleagues; Sie with strangers and in formal settings."},"transliteration":"du / Sie"}},{"id":"eur-038","version":2,"slug":"the-viennese-coffee-house-rents-you-a-table-for-hours","contentType":"scene","category":"food-and-hospitality","title":{"ar":"المقهى الفييني: طاولة تُستأجر لساعات","de":"Das Wiener Kaffeehaus vermietet Tische für Stunden","en":"The Viennese coffee house rents you a table for hours"},"deck":{"ar":"في فيينا، المقهى ليس مجرد مكان للقهوة، بل مؤسسة ثقافية تمنح الزائر حق الجلوس لساعات دون ضغط.","de":"In Wien ist das Kaffeehaus keine bloße Kaffeebar, sondern eine kulturelle Institution, die das Recht auf langes Sitzen ohne Druck gewährt.","en":"In Vienna, the coffee house is not just a café but a cultural institution that grants the right to sit for hours without pressure."},"teaser":{"ar":"المقهى الفييني يجمع بين القهوة والصحف والجلوس الطويل، حيث تدفع ثمن القهوة فقط بينما يستهلك الوقت والمكان مجانًا.","de":"Das Wiener Kaffeehaus verbindet Kaffee, Zeitungen und langes Verweilen: Man zahlt nur den Kaffee, während Zeit und Raum verbraucht werden.","en":"The Viennese coffee house combines coffee, newspapers and long stays: you pay only for the coffee while time and space are consumed."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس يومي ومساحة للعمل","paragraphs":["في فيينا، المقهى (Kaffeehaus) مؤسسة ثقافية بطاولات رخامية وكراسي منحنية وأرفف صحف ونُدُل يرتدون الأسود. منذ 2011، أُدرجت 'ثقافة المقهى الفييني' في الجرد الوطني النمساوي للتراث الثقافي غير المادي.","العرف الأساسي هو حق الجلوس لساعات على فنجان قهوة واحد، للقراءة أو الحديث. يصفون المقهى بأنه مكان يُستهلك فيه الوقت والمكان ولكن الفاتورة تشمل القهوة فقط."]},{"heading":"أسماء القهوة وحياة المثقفين","paragraphs":["لكل قهوة اسم ووصفة: الميلانج إسبريسو مع حليب ورغوة، والآينشبانر يُقدم في كوب مع كريمة مخفوقة، والـ'كلاينر براونر' قهوة مع لمسة حليب. في أواخر القرن التاسع عشر وأوائل العشرين، كان المقهى مكان عمل للكتّاب والفنانين والمنفيين السياسيين.","يختلف الأمر حسب المنطقة والجيل: بعض البيوت التقليدية أصبحت وجهات سياحية، بينما يفضل شباب فيينا القهوة السريعة."]}],"de":[{"heading":"Alltagsritual und Arbeitsplatz","paragraphs":["Das Wiener Kaffeehaus ist eine Institution mit Marmortischen, Bugholzstühlen, Zeitungsständern und Kellnern in Schwarz. Seit 2011 ist die 'Wiener Kaffeehauskultur' im nationalen Verzeichnis des immateriellen Kulturerbes Österreichs eingetragen.","Kern der Kultur ist das Recht, stundenlang bei einem einzigen Kaffee zu sitzen, zu lesen oder zu reden. Man beschreibt das Kaffeehaus als Ort, an dem Zeit und Raum konsumiert werden, aber nur der Kaffee auf der Rechnung steht."]},{"heading":"Kaffeenamen und das Leben der Intellektuellen","paragraphs":["Jeder Kaffee hat einen Namen und eine Spezifikation: Eine Melange ist Espresso mit Milch und Schaum, ein Einspänner wird im Glas mit Schlagobers serviert, und ein 'kleiner Brauner' ist Kaffee mit einem Schuss Milch. Im späten 19. und frühen 20. Jahrhundert war das Kaffeehaus Arbeitsplatz für Schriftsteller, Künstler und politische Exilanten.","Regionale und generationelle Unterschiede bestehen: Manche traditionelle Häuser sind heute Touristenziele, und jüngere Wiener trinken häufiger To-go-Kaffee als der Mythos suggeriert."]}],"en":[{"heading":"Everyday ritual and workplace","paragraphs":["The Viennese coffee house (Kaffeehaus) is an institution with marble tables, bentwood chairs, newspaper racks and waiters in black. Since 2011, 'Viennese coffee house culture' has been listed in Austria's national inventory of intangible cultural heritage.","The core custom is the right to sit for hours over a single coffee, reading or talking. The coffee house is described as a place where time and space are consumed but only the coffee is on the bill."]},{"heading":"Coffee names and intellectual life","paragraphs":["Each coffee has a name and a specification: a Melange is espresso with milk and foam, an Einspänner is served in a glass with whipped cream, and a 'kleiner Brauner' is coffee with a dash of milk. In the late 19th and early 20th centuries, the coffee house was a workplace for writers, artists and political exiles.","Regional and generational variation exists: some traditional houses are now tourist destinations, and younger Viennese drink more to-go coffee than the myth suggests."]}]},"context":{"countries":["AT"],"region":"Central Europe","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["food-and-hospitality","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Viennese coffee house culture","de":"Viennese coffee house culture","en":"Viennese coffee house culture"},"url":"https://en.wikipedia.org/wiki/Viennese_coffee_house_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Austria","de":"Culture of Austria","en":"Culture of Austria"},"url":"https://en.wikipedia.org/wiki/Culture_of_Austria","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب يطلب ميلانج، ينشر ملاحظات المحاضرة ويبقى ثلاث ساعات؛ النادل يعيد ملء كوب الماء دون سؤال ولا يحضر الفاتورة إلا بطلب.","de":"Eine Studentin bestellt eine Melange, breitet ihre Vorlesungsnotizen aus und bleibt drei Stunden; der Kellner füllt das Wasserglas nach, ohne zu fragen, und bringt die Rechnung nie unaufgefordert.","en":"A student orders a Melange, spreads out lecture notes and stays for three hours; the waiter refills the water glass without asking and never brings the bill unrequested."},"misunderstanding":{"ar":"يظن البعض أن الجلوس الطويل يتطلب طلبات متكررة، لكن العرف يسمح بفنجان واحد.","de":"Manche glauben, langes Sitzen erfordere ständige Bestellungen, doch die Etikette erlaubt einen einzigen Kaffee.","en":"Some think long sitting requires constant orders, but the etiquette allows a single coffee."},"comparison":{"ar":"في مقاهي كثيرة، الضغط لاستهلاك أسرع، بينما هنا الوقت جزء من الخدمة.","de":"In vielen Cafés drängt man zu schnellem Konsum, hier ist die Zeit Teil der Leistung.","en":"In many cafés, staff push for quick consumption; here, time is part of the service."}},{"id":"eur-039","version":2,"slug":"rostigraben-the-swiss-divide-that-is-not-a-border","contentType":"note","category":"social-behaviour","title":{"ar":"صدع Rösti: حدود ثقافية بلا جدار","de":"Der Röstigraben: eine Grenze ohne Zaun","en":"The Röstigraben: a divide without a fence"},"deck":{"ar":"خط فاصل غير رسمي بين سويسرا الناطقة بالألمانية والروماندية الناطقة بالفرنسية، يظهر في نشرات الأخبار وفي صناديق الاقتراع.","de":"Eine informelle kulturelle Trennlinie zwischen der Deutschschweiz und der französischsprachigen Romandie, sichtbar in Nachrichten und an der Urne.","en":"An informal cultural boundary between German-speaking Switzerland and French-speaking Romandy, visible in the news and at the ballot box."},"teaser":{"ar":"في سويسرا حيث أربع لغات، يبدو أن الحدود الثقافية تُرسم حيث تتغير قائمة الطعام، لا حيث تنتهي الطرق.","de":"In einem Land mit vier Sprachen verläuft die kulturelle Grenze offenbar dort, wo sich die Speisekarte ändert, nicht wo die Straße endet.","en":"In a country with four languages, the cultural line seems to run where the menu changes, not where the road ends."},"readingMinutes":1,"sections":{"ar":[{"heading":"أين يبدأ الصدع وأين ينتهي","paragraphs":["صدع Rösti هو الحدود الثقافية غير الرسمية بين سويسرا الناطقة بالألمانية والروماندية الناطقة بالفرنسية. الطبق نفسه، وهو كعكة بطاطس مقلية، مرتبط بالجزء الناطق بالألمانية، والنكتة المتداولة أن الحدود تمتد حيث تتغير قائمة الطعام.","ظهر المصطلح أول مرة خلال الحرب العالمية الأولى، حين كانت سويسرا المحايدة بين الإمبراطورية الألمانية والجمهورية الفرنسية، فقرأت كل جماعة لغوية أخبارًا مختلفة.","غير أن هذا الصدع ميل إحصائي لا جدار: ففي الجانبين أقليات داخلية، والمدن تصوّت بشكل مختلف عن الريف، وكثير من الاقتراعات تشق الخط اللغوي نفسه. كما يختلف وقع المصطلح بين الأجيال وفي المناطق الحدودية."]},{"heading":"سياسة وأصداء لغوية","paragraphs":["يظهر الانقسام في الاستفتاءات: فقد صوّتت كانتونات ناطقة بالفرنسية غالبًا بشكل مختلف عن الكانتونات الناطقة بالألمانية حول الاندماج الأوروبي والهجرة والجيش.","ويوجد أيضًا صدع Polenta بين سويسرا الناطقة بالألمانية وكانتون تيتشينو الناطق بالإيطالية، وهو تذكير بأن البلاد تضم أربع جماعات لغوية لا اثنتين.","في أحد أيام الاستفتاء تنقسم خريطة التلفزيون السويسري بين غرب فرنكوفوني وشرق ألماني، ويبدأ المعلّقون فورًا في الحديث عن صدع Rösti."]}],"de":[{"heading":"Wo der Graben beginnt und endet","paragraphs":["Der Röstigraben ist die informelle kulturelle Grenze zwischen der Deutschschweiz und der französischsprachigen Romandie. Das Gericht selbst, ein gebratener Kartoffelkuchen, gilt als deutschschweizerisch, und der Scherz lautet, die Grenze verlaufe dort, wo sich die Speisekarte ändert.","Der Begriff tauchte erstmals während des Ersten Weltkriegs auf, als die neutrale Schweiz zwischen dem Deutschen Kaiserreich und der Französischen Republik lag und beide Sprachgemeinschaften unterschiedliche Nachrichten lasen.","Doch der Graben ist eine statistische Tendenz, keine Mauer: Beide Seiten haben interne Minderheiten, Städte stimmen anders ab als ländliche Gebiete, und viele Abstimmungen durchschneiden die Sprachgrenze. Auch zwischen Generationen und in Grenzregionen wird der Begriff unterschiedlich gebraucht."]},{"heading":"Politik und sprachliche Echos","paragraphs":["Der Graben zeigt sich in Abstimmungen: Französischsprachige Kantone haben bei europäischer Integration, Einwanderung und Armee oft anders gestimmt als deutschsprachige.","Es gibt auch einen Polentagraben zwischen der Deutschschweiz und dem italienischsprachigen Kanton Tessin, ein Hinweis darauf, dass das Land vier Sprachgemeinschaften hat, nicht zwei.","Am Abstimmungssonntag teilt sich die Karte im Schweizer Fernsehen zwischen einem französischsprachigen Westen und einem deutschsprachigen Osten, und die Kommentatoren sprechen sofort vom Röstigraben."]}],"en":[{"heading":"Where the ditch begins and ends","paragraphs":["The Röstigraben is the informal cultural boundary between German-speaking Switzerland and French-speaking Romandy. The dish itself, a fried potato cake, is associated with German-speaking Switzerland, and the joke is that the border runs where the menu changes.","The term first appeared during the First World War, when neutral Switzerland sat between the German Empire and the French Republic and the two language communities read different news.","Yet the divide is a statistical tendency, not a wall: both sides contain internal minorities, cities vote differently from rural areas, and many votes cut across the language line. The term also lands differently between generations and in border regions."]},{"heading":"Politics and linguistic echoes","paragraphs":["The divide shows up in referendums: French-speaking cantons have often voted differently from German-speaking ones on European integration, immigration and the army.","There is also a Polentagraben between German-speaking Switzerland and the Italian-speaking canton of Ticino, a reminder that the country has four language communities, not two.","On referendum Sunday the map on Swiss television splits between a French-speaking west and a German-speaking east, and commentators immediately discuss the Röstigraben."]}]},"context":{"countries":["CH"],"region":"Alpine region","continent":"europe","languages":["de","fr"],"period":"contemporary"},"tags":["social-behaviour","Alpine region"],"sources":[{"organization":"Wikipedia","title":{"ar":"Röstigraben","de":"Röstigraben","en":"Röstigraben"},"url":"https://en.wikipedia.org/wiki/R%C3%B6stigraben","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Swiss French","de":"Swiss French","en":"Swiss French"},"url":"https://en.wikipedia.org/wiki/Swiss_French","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أحد أيام الاستفتاء تنقسم خريطة التلفزيون السويسري بين غرب فرنكوفوني وشرق ألماني، ويبدأ المعلّقون فورًا في الحديث عن صدع Rösti.","de":"Am Abstimmungssonntag teilt sich die Karte im Schweizer Fernsehen zwischen einem französischsprachigen Westen und einem deutschsprachigen Osten, und die Kommentatoren sprechen sofort vom Röstigraben.","en":"On referendum Sunday the map on Swiss television splits between a French-speaking west and a German-speaking east, and commentators immediately discuss the Röstigraben."},"misunderstanding":{"ar":"يُفهم الصدع أحيانًا كعداء بين المجموعتين اللغويتين، لكنه في الواقع تعبير عن اختلاف في المزاج السياسي والإعلامي داخل بلد واحد.","de":"Der Graben wird manchmal als Feindschaft zwischen den Sprachgemeinschaften verstanden, ist aber ein Ausdruck unterschiedlicher politischer und medialer Stimmungen in einem Land.","en":"The divide is sometimes read as hostility between the two language groups, but it is really a difference of political and media mood inside one country."},"comparison":{"ar":"يشبه الأمر عائلة واحدة تجلس إلى طاولتين: القائمة تتغير، لكن البيت واحد والحديث يتقاطع دائمًا.","de":"Es ist wie eine Familie an zwei Tischen: Die Speisekarte wechselt, doch das Haus bleibt dasselbe und die Gespräche kreuzen sich ständig.","en":"It is like one family at two tables: the menu changes, but the house stays the same and the conversation keeps crossing over."}},{"id":"eur-040","version":2,"slug":"romansh-switzerland-s-fourth-language-in-a-fight-for-speakers","contentType":"note","category":"languages","title":{"ar":"الرومانش: لغة سويسرا الرابعة تصارع على المتحدثين","de":"Rätoromanisch: Die vierte Sprache der Schweiz","en":"Romansh: Switzerland's fourth language fights for speakers"},"deck":{"ar":"في وديان غراوبوندن، يحافظ نحو 40 ألف شخص على لغة رومانسية تعيش بين اللهجات المحلية ولغة موحدة مثيرة للجدل.","de":"In den Tälern Graubündens halten rund 40.000 Menschen eine romanische Sprache lebendig, zwischen lokalen Idiomen und einer umstrittenen Einheitssprache.","en":"In the valleys of Graubünden, some 40,000 people keep a Romance language alive, caught between local idioms and a contested standard."},"teaser":{"ar":"لغة رومانسية صغيرة في جبال الألب تحمل هوية سويسرية رابعة، لكن التحضر والازدواجية اللغوية يضغطان على حياتها اليومية.","de":"Eine kleine Alpensprache trägt eine vierte Schweizer Identität, doch Urbanisierung und Zweisprachigkeit setzen ihrem Alltag zu.","en":"A small Alpine language carries a fourth Swiss identity, but urbanisation and bilingualism are squeezing its everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة صغيرة بمكانة وطنية","paragraphs":["الرومانش لغة رومانسية يتحدثها أساسًا نحو 40 ألف شخص في كانتون غراوبوندن السويسري. صارت لغة وطنية منذ عام 1938، ولغة رسمية في التعامل مع متحدثيها منذ 1996.","هي في الحقيقة حزمة من اللهجات، منها سورسيلفان وسوتسيلفان وسورميران وبوتير وفالادر. وقد أثارت اللغة الموحدة «رومانش غريشون» التي صيغت عام 1982 جدلًا في المدارس.","تستخدم اللغة في المدارس المحلية والإذاعة والتلفزيون وإدارة الكانتون، لكن معظم المتحدثين ثنائيو اللغة، وقد قلّص التحضر قاعدتها اليومية. ويختلف الاستخدام بين الأجيال والأودية اختلافًا واضحًا."]},{"heading":"حماية قانونية ونقاش ثقافي","paragraphs":["تحمي سياسة الأقليات السويسرية الرومانش، ويدعمها الكانتون بقانون لغوي وتمويل لمشاريع ثقافية.","اللغة مهددة لا ميتة: الأعداد صغيرة لكنها مستقرة في بعض الوديان، والاختيار بين اللهجة المحلية واللغة الموحدة يبقى جدلًا ثقافيًا حيًا."]}],"de":[{"heading":"Kleine Sprache mit nationalem Rang","paragraphs":["Rätoromanisch ist eine romanische Sprache, die vor allem im Schweizer Kanton Graubünden von schätzungsweise 40.000 Menschen gesprochen wird. Seit 1938 ist sie Landessprache, seit 1996 Amtssprache im Verkehr mit romanischsprachigen Personen.","Sie ist ein Bündel von Idiomen, darunter Sursilvan, Sutsilvan, Surmiran, Putèr und Vallader. Das 1982 geschaffene Rumantsch Grischun sorgte in den Schulen für Kontroversen.","Die Sprache wird in lokalen Schulen, Radio und Fernsehen sowie in der Kantonsverwaltung verwendet. Die meisten Sprecher sind zweisprachig, und die Urbanisierung hat ihre Alltagsbasis verkleinert. Regional und generationell wird sie sehr unterschiedlich genutzt."]},{"heading":"Schutz per Gesetz und ein Kulturkampf","paragraphs":["Die Schweizer Minderheitenpolitik und der Kanton schützen das Rätoromanische mit einem Sprachgesetz und Geld für Kulturprojekte.","Die Sprache ist bedroht, nicht tot: Die Zahlen sind klein, in manchen Tälern aber stabil, und die Wahl zwischen Idiom und Einheitssprache bleibt ein lebendiger Streit."]}],"en":[{"heading":"A small language with national standing","paragraphs":["Romansh is a Romance language spoken mainly in the Swiss canton of the Grisons by an estimated 40,000 people. It has been a national language since 1938 and an official language in dealings with Romansh speakers since 1996.","It is itself a bundle of idioms, including Sursilvan, Sutsilvan, Surmiran, Putèr and Vallader. The standardised Rumantsch Grischun, created in 1982, has been controversial in schools.","The language is used in local schools, radio and television and cantonal administration, but most speakers are bilingual and urbanisation has reduced its everyday base. Use varies noticeably between valleys and generations."]},{"heading":"Legal protection and a live cultural argument","paragraphs":["Romansh is protected by Swiss minority-language policy and by the canton, which has a language law and funding for cultural projects.","It is threatened rather than dead: numbers are small but stable in some valleys, and the choice between local idioms and a standard language remains a live cultural argument."]}]},"context":{"countries":["CH"],"region":"Alpine region","continent":"europe","languages":["rm","de"],"period":"contemporary"},"tags":["languages","Alpine region"],"sources":[{"organization":"Wikipedia","title":{"ar":"Romansh language","de":"Romansh language","en":"Romansh language"},"url":"https://en.wikipedia.org/wiki/Romansh_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Switzerland","de":"Languages of Switzerland","en":"Languages of Switzerland"},"url":"https://en.wikipedia.org/wiki/Languages_of_Switzerland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"لافتة طريق في غراوبوندن تحمل «Chur» و«Cuira»، وجدة تتحدث السورسيلفان في البيت بينما يتعلم حفيدها رومانش غريشون في المدرسة.","de":"Ein Straßenschild in Graubünden zeigt „Chur“ und „Cuira“, und eine Großmutter spricht zu Hause Sursilvan, während ihr Enkel in der Schule Rumantsch Grischun lernt.","en":"A road sign in Graubünden reads both 'Chur' and 'Cuira', and a grandmother speaks Sursilvan at home while her grandson learns Rumantsch Grischun at school."},"misunderstanding":{"ar":"كثيرون يظنون أن الرومانش لهجة ألمانية أو لغة ميتة، لكنها لغة رومانسية مستقلة ما زالت تُستخدم يوميًا.","de":"Viele halten Rätoromanisch für einen deutschen Dialekt oder eine tote Sprache; es ist aber eine eigenständige romanische Sprache im Alltag.","en":"Many assume Romansh is a German dialect or a dead language, but it is a distinct Romance language still used in daily life."},"comparison":{"ar":"مثل لغات الأقليات الجبلية الأخرى، تعيش الرومانش بين حماية رسمية وضغط لغات أكبر حولها.","de":"Wie andere alpine Minderheitensprachen lebt es zwischen staatlichem Schutz und dem Druck größerer Nachbarsprachen.","en":"Like other Alpine minority languages, it lives between official protection and pressure from larger neighbouring languages."},"expression":{"original":"Allegra","language":"Rumantsch","gloss":{"ar":"مرحبًا / أهلًا","de":"Hallo / willkommen","en":"Hello / welcome"},"usage":{"ar":"تحية شائعة عند اللقاء في وادي غراوبوندن.","de":"Geläufige Begrüßung bei Begegnungen in Graubünden.","en":"A common greeting on meeting someone in Graubünden."},"transliteration":"allegra"}},{"id":"eur-041","version":2,"slug":"schwingen-and-hornussen-the-swiss-sports-under-the-ski-season","contentType":"note","category":"games-and-leisure","title":{"ar":"رياضات شعبية تحت ثلوج سويسرا","de":"Schwingen und Hornussen im Schweizer Alltag","en":"Schwingen and Hornussen in Swiss village life"},"deck":{"ar":"في القرى الألمانية الناطقة جنوب سويسرا، يتصارع الرجال على نشارة الخشب ويضربون أقراصًا خشبية، فتبقى الرياضة جزءًا من الحياة اليومية.","de":"In den deutschsprachigen Voralpen entscheidet nicht nur der Schnee über den Kalender, sondern auch Sägemehl, Zwilchhosen und der Klang einer Brass Band.","en":"In the German-speaking pre-alpine regions, the calendar is marked not only by snow but by sawdust rings, canvas breeches and the sound of a brass band."},"teaser":{"ar":"قبل أن يذوب الثلج، تخرج القرى إلى حلبات نشارة الخشب وميادين الضرب، حيث تُقاس المكانة الاجتماعية بالقوة والتحمّل.","de":"Bevor der Schnee schmilzt, treten Dörfer auf Sägemehlkreise und Wurfplätze, wo Kraft, Ruhe und lokale Ehre zählen.","en":"Before the snow melts, villages gather at sawdust circles and hitting fields, where strength, calm and local honour still shape everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"صراع السراويل على نشارة الخشب","paragraphs":["في المناطق الألمانية الناطقة قرب جبال الألب، يمارس الناس «شفينغن»، وهو صراع شعبي يُعرف أيضًا بـ«هوزنلوبف»، أي رفع السروال. يرتدي المتصارعون سراويل قماشية خاصة بأحزمة، ويفوز من يثبّت كتفَي خصمه على الأرض.","تُقام المباريات في دوائر من نشارة الخشب، ويقف الجمهور على منصات خشبية بينما تعزف فرقة نحاسية. الهدف ليس الإيذاء بل إظهار الرباطة والهدوء تحت الضغط.","تختلف شعبية هذه الرياضة بين الأجيال والمناطق؛ فالشبان في القرى الجبلية ما زالوا يتدربون في الأندية المحلية، بينما يكتفي كثيرون في المدن بمتابعة المباريات الكبرى."]},{"heading":"مهرجان كل ثلاث سنوات","paragraphs":["الحدث الأكبر هو «آيدغينوسيشس شفينغفست»، الذي يُقام كل ثلاث سنوات، حيث يحصل الفائز على ثور كجائزة ويُحتفى به كبطل وطني.","إلى جانب الصراع تُمارس رياضات أخرى كـ«هورنوسن»، حيث يضرب اللاعبون قرصًا خشبيًا بسوط طويل، و«شتاينشتوسن»، أي رمي الحجر.","تُدرج «شفينغن» و«شتاينشتوسن» في جرد التراث الثقافي غير المادي السويسري، ما يعكس مكانتهما في الحياة المحلية."]}],"de":[{"heading":"Ringen in der Sägemehlgrube","paragraphs":["In den voralpinen, deutschsprachigen Teilen der Schweiz wird Schwingen praktiziert, auch Hosenlupf genannt. Die Schwinger tragen spezielle Zwilchhosen mit Gürteln, und wer die Schultern des Gegners auf den Boden drückt, gewinnt.","Die Kämpfe finden in Sägemehlkreisen statt, das Publikum steht auf Holztribünen, eine Brass Band spielt. Es geht nicht um Verletzung, sondern um Standhaftigkeit und Ruhe unter Druck.","Die Beliebtheit variiert nach Region und Generation: Junge Leute in Bergdörfern trainieren weiter in lokalen Vereinen, während viele in den Städten nur die großen Feste verfolgen."]},{"heading":"Das Fest alle drei Jahre","paragraphs":["Der Höhepunkt ist das Eidgenössische Schwingfest, das alle drei Jahre stattfindet; der Sieger erhält einen Stier als Preis und wird wie ein Nationalheld gefeiert.","Neben dem Schwingen werden Hornussen gespielt, bei dem ein puckähnliches Objekt mit einer Peitsche geschlagen wird, sowie Steinstossen.","Schwingen und Steinstossen stehen im Inventar des immateriellen Kulturerbes der Schweiz, was ihre Bedeutung im lokalen Leben zeigt."]}],"en":[{"heading":"Wrestling in the sawdust circle","paragraphs":["In the pre-alpine, German-speaking parts of Switzerland, people practise Schwingen, a folk wrestling also called Hosenlupf, or breeches-lifting. Wrestlers wear special canvas breeches with belts, and win by pinning the opponent's shoulders to the ground.","Bouts take place in sawdust-filled circles, with crowds on wooden stands and a brass band playing. The aim is not injury but steadiness and calm under pressure.","Popularity varies by region and generation: young people in mountain villages still train in local clubs, while many in cities only follow the big festivals."]},{"heading":"The festival every three years","paragraphs":["The big event is the Eidgenössisches Schwingfest, held every three years, where the winner receives a bull as a prize and is celebrated like a national champion.","Alongside Schwingen, people play Hornussen, in which players hit a puck-like object with a whip, and Steinstossen, stone putting.","Schwingen and Steinstossen are listed in Switzerland's inventory of intangible cultural heritage, reflecting their place in local life."]}]},"context":{"countries":["CH"],"region":"Alpine region","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["games-and-leisure","Alpine region"],"sources":[{"organization":"Wikipedia","title":{"ar":"Schwingen","de":"Schwingen","en":"Schwingen"},"url":"https://en.wikipedia.org/wiki/Schwingen","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hornussen","de":"Hornussen","en":"Hornussen"},"url":"https://en.wikipedia.org/wiki/Hornussen","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مهرجان كانتوني، يتصارع مزارعان داخل دائرة من نشارة الخشب يمسك كل منهما بسروال الآخر، بينما تعزف فرقة نحاسية ويتابع الجمهور من منصات خشبية.","de":"Bei einem kantonalen Schwingfest ringen zwei Bauern in einem Sägemehlkreis, jeder greift die Hose des anderen, während eine Brass Band spielt und das Publikum von Holztribünen zusieht.","en":"At a cantonal Schwingfest, two farmers in a sawdust-filled circle grip each other's breeches while a brass band plays and the crowd watches from wooden stands."},"misunderstanding":{"ar":"كثيرون يظنون أن هذه الرياضة منتشرة في كل سويسرا بالتساوي، لكنها في الواقع أقوى في المناطق الألمانية الناطقة، بينما للمناطق الفرنسية والإيطالية رياضاتها وتقاليدها المختلفة.","de":"Viele glauben, diese Sportart sei in der ganzen Schweiz gleich verbreitet; tatsächlich ist sie im Berner Oberland, in der Zentralschweiz und im Osten am stärksten, während die französisch- und italienischsprachigen Regionen andere Sportarten und selten Champions haben.","en":"Many assume the sport is equally widespread across Switzerland, but it is strongest in the Bernese Oberland, central and eastern Switzerland, while French- and Italian-speaking regions have other sports and rarely produce champions."},"comparison":{"ar":"يمكن مقارنتها برياضات المصارعة الشعبية في جبال أخرى، حيث تُقام المنافسات في الهواء الطلق وتُمنح الجوائز العينية كالثور بدل الكؤوس.","de":"Man kann sie mit anderen ländlichen Ringtraditionen im Gebirge vergleichen, bei denen im Freien gekämpft und statt Pokalen ein Stier als Preis vergeben wird.","en":"It can be compared with other rural wrestling traditions in mountain regions, where contests are held outdoors and prizes are given in kind, such as a bull instead of a trophy."}},{"id":"eur-042","version":2,"slug":"sobremesa-the-hour-after-lunch-that-spain-keeps","contentType":"note","category":"food-and-hospitality","title":{"ar":"السوبريميسا: ساعةٌ بعد الغداء تحتفظ بها إسبانيا","de":"Sobremesa: Spaniens Stunde nach dem Mittagessen","en":"Sobremesa: the hour Spain keeps after lunch"},"deck":{"ar":"جلوسٌ على الطاولة بعد انتهاء الطعام، لا لتناول المزيد بل للحديث والقهوة وترك الطعام يستقر.","de":"Nach dem Essen bleibt man sitzen – nicht für mehr Essen, sondern für Gespräche, Kaffee und das Verdauen.","en":"Staying at the table once the food is finished – not for more courses, but for talk, coffee and letting things settle."},"teaser":{"ar":"عادة إسبانية تُبقي الطاولة بعد الغداء، حيث ينتهي الطعام ولا ينتهي الكلام، ويجلس الجميع بلا عجلة.","de":"In Spanien endet das Mittagessen, aber nicht das Beisammensein: Die Tafel bleibt gedeckt, niemand muss aufbrechen.","en":"In Spain the meal ends but the table stays. Nobody is expected to rush off, and the talking carries on."},"readingMinutes":1,"sections":{"ar":[{"heading":"طاولةٌ لا تُرفع بسرعة","paragraphs":["السوبريميسا، ومعناها الحرفي «فوق الطاولة»، عادة إسبانية تقضي بالبقاء على الطاولة بعد الغداء للحديث وشرب القهوة أو كأس صغيرة من المشروب، وترك الطعام يستقر. وهي طقس اجتماعي لا طبق آخر: الطعام انتهى، لكن الطاولة تبقى، ولا يُتوقع من أحد أن يستعجل الرحيل.","تنسجم هذه العادة مع جدول يومي يكون فيه الغداء الوجبة الرئيسية، والعشاء متأخرًا بعد الحادية والعشرين غالبًا. وساعة السوبريميسا ركن ثابت في برامج التلفزيون الإسباني، وقد يمتد غداء الأحد العائلي إلى المساء.","تختلف العادة بحسب المنطقة والجيل: ففي المدن وأماكن العمل تقلّصت سوبريميسا أيام الأسبوع، ويقول كثير من الشباب إن وقتهم لها أقل مما كان لأجدادهم."]},{"heading":"بين البيت والعمل","paragraphs":["في المناسبات العائلية تبقى الطاولة ساعتين أو أكثر، بينما يكتفي كثيرون في أيام العمل بفنجان قهوة سريع. ومع ذلك يبقى الجلوس بعد الطعام علامةً على أن الوقت ملكٌ للجماعة لا للساعة.","إسبانيا الشمالية تختلف إيقاعها عن الجنوب، غير أن الفكرة نفسها تتكرر: لا أحد يُطرد من الطاولة."]}],"de":[{"heading":"Ein Tisch, der nicht geräumt wird","paragraphs":["Sobremesa, wörtlich „auf dem Tisch“, ist die spanische Gewohnheit, nach dem Essen sitzen zu bleiben, um zu reden, Kaffee oder einen kleinen Likör zu trinken und das Essen sacken zu lassen. Es ist ein soziales Ritual, kein weiterer Gang: Das Essen ist vorbei, der Tisch bleibt, und niemand muss sich beeilen.","Die Gewohnheit passt zu einem Tagesablauf, in dem das Mittagessen die Hauptmahlzeit ist und das Abendessen oft erst nach 21 Uhr kommt. Die Sobremesa-Stunde prägt das spanische Fernsehprogramm, und lange Sonntagsessen mit der Familie können bis in den Abend dauern.","Regional und generationell unterscheidet sich die Praxis: In Städten und am Arbeitsplatz ist die Sobremesa unter der Woche geschrumpft, und jüngere Spanier berichten oft von weniger Zeit dafür als ihre Großeltern."]},{"heading":"Zwischen Familie und Alltag","paragraphs":["Bei Familientreffen bleibt man zwei Stunden und länger sitzen, an Werktagen reicht vielen ein schneller Kaffee. Der Kern bleibt: Die Zeit nach dem Essen gehört den Menschen, nicht der Uhr.","Nordspanien tickt anders als der Süden, doch die Idee ist dieselbe – niemand wird vom Tisch gewiesen."]}],"en":[{"heading":"A table nobody clears in a hurry","paragraphs":["Sobremesa, literally 'upon the table', is the Spanish habit of staying at the table after a meal to talk, drink coffee or a small liqueur, and let the food settle. It is a social ritual rather than a course: the meal is over, but the table is kept, and nobody is expected to rush off.","The habit fits a wider timetable in which lunch is the main meal and dinner is late, often after 21:00. The sobremesa hour is a mainstay of Spanish television scheduling, and long Sunday lunches with family can run into the evening.","Practice varies by region and generation: in cities and workplaces the weekday sobremesa has shrunk, and younger Spaniards often report having less time for it than their grandparents did."]},{"heading":"Between family and the working week","paragraphs":["At family gatherings the table stays occupied for two hours or more, while on working days many settle for a quick coffee. The point survives either way: the time after eating belongs to the people, not the clock.","Northern Spain keeps a different rhythm from the south, but the idea repeats – nobody is sent away from the table."]}]},"context":{"countries":["ES"],"region":"Southern Europe","continent":"europe","languages":["es"],"period":"contemporary"},"tags":["food-and-hospitality","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sobremesa","de":"Sobremesa","en":"Sobremesa"},"url":"https://en.wikipedia.org/wiki/Sobremesa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Spain","de":"Culture of Spain","en":"Culture of Spain"},"url":"https://en.wikipedia.org/wiki/Culture_of_Spain","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد بايلا يوم أحد، تبقى عائلة من فالنسيا ساعتين على الطاولة بين القهوة وزجاجة أوروخو، يتجادلون في كرة القدم وامتحانات الأحفاد.","de":"Nach einer Sonntagspaella bleibt eine Familie aus Valencia zwei Stunden bei Kaffee und einer Flasche Orujo sitzen und streitet über Fußball und die Prüfungen der Enkel.","en":"After a Sunday paella a Valencian family stays at the table for two hours over coffee and a bottle of orujo, arguing about football and the grandchildren's exams."},"misunderstanding":{"ar":"يظنّ بعض الزوار أن السوبريميسا دعوة لتناول المزيد من الطعام، لكنها في الحقيقة وقتٌ للكلام فقط بعد أن ينتهي الأكل.","de":"Manche Besucher halten die Sobremesa für eine Einladung zu mehr Essen; tatsächlich ist sie reine Gesprächszeit, nachdem gegessen wurde.","en":"Visitors sometimes think sobremesa means more food is coming; in fact it is talking time, after the eating is done."},"comparison":{"ar":"تشبه السوبريميسا عادات الجلوس بعد الطعام في بلدان متوسطية أخرى، لكنها في إسبانيا ترتبط بجدولٍ يكون فيه الغداء هو الوجبة الكبرى.","de":"Ähnliche Nach-Essen-Rituale gibt es rund ums Mittelmeer, doch in Spanien hängt die Sobremesa am späten Tagesrhythmus mit großem Mittagessen.","en":"Similar after-meal sitting exists around the Mediterranean, but in Spain sobremesa is tied to a late timetable with lunch as the big meal."}},{"id":"eur-043","version":2,"slug":"basque-the-european-language-that-has-no-relatives","contentType":"note","category":"languages","title":{"ar":"الباسكية: لغة أوروبا بلا أقارب","de":"Baskisch: Europas Sprache ohne Verwandte","en":"Basque: Europe's language without relatives"},"deck":{"ar":"لغة يعيشها نحو 750 ألف شخص في الباسك ونافارا، لا تشبه أي لغة حية أخرى، وتتشابك هويتها مع حياة الناس اليومية.","de":"Rund 750.000 Menschen sprechen eine Sprache, die keiner anderen lebenden gleicht – und deren Zukunft in Schulen und Familien entschieden wird.","en":"About 750,000 people speak a language unrelated to any other living one, and its future is decided in classrooms and kitchens."},"teaser":{"ar":"كيف نجت لغة لا تشبه أي لغة أخرى من قرون من الهيمنة، وكيف يعيشها الناس اليوم في المدارس والبيوت؟","de":"Wie überlebte eine Sprache ohne Sprachfamilie jahrhundertelange Fremdherrschaft, und wie lebt sie heute im Alltag weiter?","en":"How did a language with no known relatives survive centuries of domination, and how do people keep it alive today?"},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة بلا عائلة لغوية","paragraphs":["الباسكية (إيوسكارا) لغة معزولة، لا تربطها قرابة بأي لغة حية، ويتحدثها نحو 750 ألف شخص في إقليم الباسك ونافارا.","نجت من الهيمنة الرومانية والقوطية والمورية والقشتالية، وأقدم نصوصها المكتوبة الباقية تعود إلى العصور الوسطى، بينما وردت أسماء أماكن أقدم في مصادر لاتينية ويونانية.","تختلف حظوظ اللغة بحسب المنطقة والجيل، إذ تتغير قوة حضورها بين المدينة والريف وبين الأجيال."]},{"heading":"النهضة عبر المدارس","paragraphs":["تحت حكم فرانكو مُنعت الباسكية من الحياة العامة، وبعد دستور 1978 أصبحت شريكة رسمية في إقليم الباسك وأجزاء من نافارا.","وُضعت اللغة الموحدة (إيوسكارا باتوا) عام 1968 لتوحيد اللهجات، وكانت مدارس إيكاستولاس الناطقة بالباسكية محوراً في إحيائها.","اليوم يدرس عدد أكبر من الشباب الباسكيين بالباسكية مقارنة بآبائهم، ما يعكس تحولاً في الحياة اليومية لا في القانون وحده."]}],"de":[{"heading":"Eine Sprache ohne Familie","paragraphs":["Baskisch (Euskara) ist eine isolierte Sprache, mit keiner anderen lebenden Sprache verwandt, und wird von etwa 750.000 Menschen im Baskenland und in Navarra gesprochen.","Sie überstand römische, westgotische, maurische und kastilische Herrschaft; die ältesten erhaltenen Texte stammen aus dem Mittelalter, ältere Ortsnamen finden sich in lateinischen und griechischen Quellen.","Je nach Region und Generation ist die Sprache unterschiedlich präsent, besonders zwischen Stadt und Land."]},{"heading":"Wiederbelebung durch die Schule","paragraphs":["Unter Franco war Baskisch im öffentlichen Leben verboten; seit der Verfassung von 1978 ist es im Baskenland und in Teilen Navarras Mitamtssprache.","Die standardisierte Sprache Euskara Batua entstand 1968 zur Vereinheitlichung der Dialekte, und die ikastolas, baskischsprachige Schulen, wurden zum Kern der Wiederbelebung.","Heute lernen mehr junge Baskinnen und Basken auf Baskisch als ihre Eltern, was den Alltag spürbar verändert."]}],"en":[{"heading":"A language without a family","paragraphs":["Basque (euskara) is a language isolate, unrelated to any other living language, spoken by about 750,000 people in the Basque Country and Navarre.","It survived Roman, Visigothic, Moorish and Castilian domination; the first surviving written texts are medieval, while earlier place names appear in Latin and Greek sources.","Its presence varies by region and generation, especially between urban and rural areas."]},{"heading":"Revival through the classroom","paragraphs":["Under Franco, Basque was banned in public life; since the 1978 constitution it has been co-official in the Basque Country and parts of Navarre.","The standardised language, euskara batua, was created in 1968 to unify dialects, and ikastolas, Basque-language schools, have been central to its revival.","A higher proportion of young Basques now study in Basque than their parents did, a shift felt in daily life."]}]},"context":{"countries":["ES"],"region":"Basque Country","continent":"europe","languages":["eu","es"],"period":"contemporary"},"tags":["languages","Basque Country"],"sources":[{"organization":"Wikipedia","title":{"ar":"Basque language","de":"Basque language","en":"Basque language"},"url":"https://en.wikipedia.org/wiki/Basque_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Basque nationalism","de":"Basque nationalism","en":"Basque nationalism"},"url":"https://en.wikipedia.org/wiki/Basque_nationalism","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طفل في بلباو يحل مسائل الرياضيات بالباسكية، ويتحدث الإسبانية مع جدّيه، وينتقل إلى الباسكية حين ينضم أصدقاؤه إلى الطاولة.","de":"Ein Kind in Bilbao rechnet in Euskara, spricht mit den Großeltern Spanisch und wechselt ins Baskische, sobald Freunde am Tisch sitzen.","en":"A child in Bilbao does maths in Basque, speaks Spanish with grandparents and switches to Basque when friends join the table."},"misunderstanding":{"ar":"يظن كثيرون أن الباسكية لهجة إسبانية أو فرنسية، لكنها لغة مستقلة تماماً ولا تنتمي إلى أي عائلة لغوية معروفة.","de":"Viele halten Baskisch für einen spanischen oder französischen Dialekt, dabei ist es eine eigenständige Sprache ohne bekannte Verwandtschaft.","en":"Many assume Basque is a dialect of Spanish or French, but it is a separate language with no known relatives at all."},"comparison":{"ar":"حيث تُوحَّد لغات كثيرة عبر الإعلام المركزي، وُحّدت الباسكية عبر المدرسة والاختيار المجتمعي، فصار الفصل الدراسي مكان بناء اللغة.","de":"Während viele Sprachen über zentrale Medien vereinheitlicht wurden, geschah dies beim Baskischen über Schule und Gemeinschaft – das Klassenzimmer wurde zum Sprachraum.","en":"Where many languages were standardised through central media, Basque was unified through schooling and community choice, making the classroom a language space."},"expression":{"original":"Kaixo","language":"Euskara","gloss":{"ar":"مرحباً","de":"Hallo","en":"Hello"},"usage":{"ar":"تحية شائعة تُقال عند اللقاء في الشارع أو المدرسة أو البيت.","de":"Geläufige Begrüßung auf der Straße, in der Schule oder zu Hause.","en":"A common greeting in the street, at school or at home."},"transliteration":"kaixo"}},{"id":"eur-044","version":2,"slug":"saudade-why-portuguese-longing-is-not-just-sadness","contentType":"language","category":"communication","title":{"ar":"سودادي: شوق لا يُختصر في الحزن","de":"Saudade: Sehnsucht ist mehr als Trauer","en":"Saudade: why Portuguese longing is not just sadness"},"deck":{"ar":"كلمة برتغالية تصف شوقًا إلى غائب، وفيها اعتراف بأن الألم قد يحمل لذة خفية.","de":"Ein portugiesisches Wort für die Sehnsucht nach Abwesendem, in dem auch das Warten einen eigenen Genuss trägt.","en":"A Portuguese word for missing someone or something absent, in which the waiting itself carries a quiet pleasure."},"teaser":{"ar":"قد يبدو الشوق حزنًا خالصًا، لكن البرتغاليين يصفون به غياب من نحب مع إقرار بأن في الانتظار متعة غامضة.","de":"Sehnsucht wirkt oft nur schmerzhaft. Im Portugiesischen beschreibt saudade das Vermissen mit dem stillen Eingeständnis, dass im Schmerz auch Freude liegt.","en":"Longing can look like pure sadness. In Portuguese, saudade names the ache of absence while admitting that the pain holds a small, accepted pleasure."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه الكلمة","paragraphs":["سودادي كلمة برتغالية وجاليسية تعبّر عن شوق حزين إلى شخص أو شيء غائب، مع إحساس بأنه قد لا يعود. أصلها من الكلمة اللاتينية الدالة على العزلة، وقد وصفها كتّاب برتغاليون بأنها ذكرى شيء مصحوبة برغبة فيه.","ترتبط الكلمة ارتباطًا وثيقًا بفادو، تقليد الغناء البرتغالي، وبصورة شعب بحري يترك أهله خلفه على الشاطئ. وتحتفل البرازيل رسميًا بيوم السودادي في الثلاثين من يناير، وقد دخلت الكلمة الكلام اليومي لتصف الحنين إلى الوطن والحب والفقد.","يُقال إنها غير قابلة للترجمة، مع أن لغات أخرى تعرف كلمات للشوق. المميز فيها هو قبول اللذة داخل الألم. ويختلف حضورها بين الأجيال والمناطق، فبعضهم يعيشها بعمق وبعضهم يتحدث عنها بسخرية لطيفة."]},{"heading":"الشوق في الحياة اليومية","paragraphs":["يستخدم الناس الكلمة في مواقف صغيرة: مهاجر يسمع أغنية في مقهى بعيد، أو جدة تتذكر بيتًا هُدم. هي ليست مجرد افتقاد، بل حالة يحمل فيها الإنسان غيابه معه.","هذا المعنى يجعل الكلمة قريبة من التجربة اليومية للفراق، لا من الحزن الرسمي. وتظل الكلمة حيّة في الغناء والحديث العابر بين الناس."]}],"de":[{"heading":"Was das Wort trägt","paragraphs":["Saudade ist ein portugiesisches und galicisches Wort für eine melancholische, nostalgische Sehnsucht nach einem abwesenden Menschen oder Ding, oft mit dem Gefühl, dass es nie zurückkehrt. Es stammt vom lateinischen Wort für Einsamkeit ab, und portugiesische Schriftsteller nannten es „Erinnerung an etwas mit dem Verlangen danach“.","Der Begriff ist eng mit dem Fado verbunden, der portugiesischen Gesangstradition, und mit dem Selbstbild eines Seefahrervolkes, das zu Hause zurückbleibt. Brasilien begeht offiziell am 30. Januar einen Tag der Saudade, und das Wort ist in die Alltagssprache eingegangen, um Heimweh, Liebe und Verlust zu beschreiben.","Man nennt es oft unübersetzbar, obwohl andere Sprachen Wörter für Sehnsucht haben. Besonders ist die Akzeptanz von Lust innerhalb des Schmerzes. Je nach Region und Generation wird sie unterschiedlich stark betont, und viele Portugiesen begegnen dem Begriff mit Ironie."]},{"heading":"Sehnsucht im Alltag","paragraphs":["Menschen benutzen das Wort in kleinen Momenten: Ein Auswanderer hört in einem fernen Café einen Fado, eine Großmutter denkt an ein abgerissenes Haus. Es ist nicht bloßes Vermissen, sondern ein Zustand, in dem man die Abwesenheit mit sich trägt.","Dadurch bleibt die Kategorie nah an der alltäglichen Erfahrung des Abschieds und nicht an offizieller Trauer. Lebendig bleibt sie im Gesang und im beiläufigen Gespräch zwischen Menschen."]}],"en":[{"heading":"What the word carries","paragraphs":["Saudade is a Portuguese and Galician word for a melancholic, nostalgic longing for someone or something absent, often with the sense that it may never return. It derives from the Latin word for solitude, and Portuguese writers have described it as “memory of something with a desire for it”.","The word is closely associated with fado, the Portuguese song tradition, and with the national self-image of a seafaring people left behind at home. Brazil officially celebrates a Day of Saudade on 30 January, and the word has entered everyday speech as a way of describing homesickness, love and loss.","It is often called untranslatable, though other languages have words for longing; what is distinctive is the acceptance of pleasure inside the pain. The emphasis on sentiment varies by region and generation, and many Portuguese treat the concept with irony."]},{"heading":"Longing in everyday life","paragraphs":["People use the word in small moments: an emigrant hears a fado in a distant café, a grandmother remembers a demolished house. It is not simply missing, but a state of carrying the missing with you.","That keeps it close to the everyday experience of parting rather than to formal grief. The word stays alive in song and in passing conversation between people."]}]},"context":{"countries":["PT"],"region":"Southern Europe","continent":"europe","languages":["pt"],"period":"contemporary"},"tags":["communication","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Saudade","de":"Saudade","en":"Saudade"},"url":"https://en.wikipedia.org/wiki/Saudade","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Portugal","de":"Culture of Portugal","en":"Culture of Portugal"},"url":"https://en.wikipedia.org/wiki/Culture_of_Portugal","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مهاجر برتغالي في باريس يسمع فادو في مقهى فيقول «تنو سودادي دي كازا»، أي إنه يحمل افتقاده للبيت معه لا أنه يفتقده فقط.","de":"Ein portugiesischer Auswanderer in Paris hört in einem Café einen Fado und sagt „tenho saudade de casa“ – nicht einfach „ich vermisse mein Zuhause“, sondern ein Zustand, in dem er das Vermissen mit sich trägt.","en":"A Portuguese emigrant in Paris hears a fado in a café and says “tenho saudade de casa”, not simply “I miss home” but a state of carrying the missing with them."},"misunderstanding":{"ar":"يظن كثيرون أن سودادي مجرد كلمة للحزن، لكنها تفترض حضور الغائب في القلب مع قبول ضمني للانتظار.","de":"Viele halten saudade für ein reines Wort der Trauer, doch es setzt die Anwesenheit des Abwesenden im Herzen voraus und schließt das Warten ein.","en":"Many assume saudade is just a word for sadness, but it presumes the absent one is present in the heart and quietly accepts the waiting."},"comparison":{"ar":"تشبه كلمات الشوق في لغات أخرى، لكن ما يميزها هو الاعتراف بأن في الألم نفسه لذة صغيرة.","de":"Es ähnelt Sehnsuchtswörtern anderer Sprachen, doch besonders ist das Eingeständnis, dass im Schmerz selbst ein kleiner Genuss liegt.","en":"It resembles longing words in other languages, but its distinctive note is the admission that the pain itself holds a small pleasure."},"expression":{"original":"saudade","language":"Português","gloss":{"ar":"شوق إلى شيء غائب ومحبوب","de":"Sehnsucht nach etwas Abwesendem und Geliebtem","en":"a longing for something absent and loved"},"usage":{"ar":"تُقال عند افتقاد شخص أو مكان أو زمن مضى، وغالبًا في الأغاني والحديث العاطفي.","de":"Wird beim Vermissen eines Menschen, Ortes oder vergangenen Moments gesagt, oft in Liedern und gefühlvollen Gesprächen.","en":"Said when missing a person, place or past moment, often in songs and emotional conversation."},"transliteration":"saudade"}},{"id":"eur-045","version":2,"slug":"italian-hand-gestures-are-a-second-grammar","contentType":"note","category":"communication","title":{"ar":"الإيماءات الإيطالية: قواعد لغة ثانية","de":"Italienische Gesten als zweite Grammatik","en":"Italian hand gestures as a second grammar"},"deck":{"ar":"في إيطاليا، اليدان تتحدثان مع الكلمات، لا بدلاً منها، وفق نظام تواصل موازٍ له قواعده ومعانيه.","de":"In Italien sprechen die Hände mit den Worten, nicht an ihrer Stelle – ein paralleles Kommunikationssystem mit eigenen Regeln.","en":"In Italy, hands speak alongside words, not instead of them, forming a parallel communication system with its own rules."},"teaser":{"ar":"الإيماءات الإيطالية ليست مجرد عرض مسرحي، بل نظام تواصل موازٍ للكلام، له مفردات ومعانٍ إقليمية وأجيالية.","de":"Italienische Gesten sind kein bloßes Schauspiel, sondern ein paralleles Kommunikationssystem mit regionalen und generationellen Varianten.","en":"Italian gestures are not mere performance but a parallel communication system with regional and generational variants, carrying meanings beyond words."},"readingMinutes":1,"sections":{"ar":[{"heading":"نظام موازٍ للكلام","paragraphs":["في إيطاليا، تعمل الإيماءات اليدوية كنظام تواصل موازٍ يُستخدم جنباً إلى جنب مع الكلام، وليس بديلاً عنه. تشكل هذه الإيماءات ذخيرة ذات معانٍ اصطلاحية ومتغيرات إقليمية، وقد فهرس الباحثون مئات منها.","الإيماءة الشهيرة بأصابع مقبوضة واليد مرفوعة تُفهم عادة على أنها «ماذا تريد؟!» أو «عن ماذا تتحدث؟»، وغالباً ما تُبالغ في التصوير الأجنبي للإيطاليين."]},{"heading":"معانٍ تتجاوز الكلمات","paragraphs":["كثير من الإيماءات ليس لها مقابل لفظي بسيط، فهي تحمل نبرة أو سخرية أو توكيداً أو رفضاً أو إعجاباً، أو تحل محل الكلمات تماماً في الأماكن الصاخبة. تختلف النظريات حول أصولها: بعضها يعزو الذخيرة إلى اللغات واللهجات المحلية العديدة، وبعضها الآخر إلى تقاليد الأداء المتوسطية والنابولية.","ليس كل الإيطاليين يلوحون بأيديهم بالقدر نفسه أو بالطريقة ذاتها: تتنوع الذخيرة حسب المنطقة والجيل والسياق، والصورة الدولية للإيطالي الملوح بيديه هي صورة كاريكاتورية تبالغ في ممارسة حقيقية."]}],"de":[{"heading":"Ein paralleles System","paragraphs":["In Italien fungieren Handgesten als ein paralleles Kommunikationssystem, das zusammen mit der Sprache und nicht als Ersatz für sie verwendet wird. Die Gesten bilden ein Repertoire mit konventionellen Bedeutungen und regionalen Varianten; Wissenschaftler haben Hunderte davon katalogisiert.","Die berühmte Geste mit zusammengekniffenen Fingern und erhobener Hand wird gewöhnlich als „Was willst du?!“ oder „Wovon redest du?“ gedeutet und in ausländischen Darstellungen von Italienern oft übertrieben."]},{"heading":"Bedeutungen jenseits der Worte","paragraphs":["Viele Gesten haben kein einfaches verbales Äquivalent und tragen Ton, Ironie, Betonung, Ablehnung oder Bewunderung, oder sie ersetzen Wörter ganz in lauten Umgebungen. Die Theorien über ihren Ursprung gehen auseinander: Manche führen das Repertoire auf die vielen lokalen Sprachen und Dialekte der Halbinsel zurück, andere auf mediterrane und neapolitanische Aufführungstraditionen.","Nicht alle Italiener gestikulieren gleich oder identisch: Das Repertoire variiert je nach Region, Generation und Kontext, und das internationale Bild des gestikulierenden Italieners ist eine Karikatur, die eine reale Praxis übertreibt."]}],"en":[{"heading":"A parallel system","paragraphs":["In Italy, hand gestures function as a parallel system of communication, used alongside speech rather than as a substitute for it. The gestures form a repertoire with conventional meanings and regional variants, and scholars have catalogued hundreds of them.","The famous pinched-fingers gesture, with the hand raised and the fingers together, is usually glossed as 'What do you want?!' or 'What are you talking about?' and is often exaggerated in foreign portrayals of Italians."]},{"heading":"Meanings beyond words","paragraphs":["Many gestures have no simple verbal equivalent and carry tone, irony, emphasis, dismissal or admiration, or replace words entirely in noisy settings. Theories about the origins vary: some trace the repertoire to the many local languages and dialects of the peninsula, others to Mediterranean and Neapolitan performance traditions.","Not all Italians gesture equally or identically: the repertoire varies by region, generation and context, and the international image of the gesticulating Italian is a caricature that exaggerates a real practice."]}]},"context":{"countries":["IT"],"region":"Southern Europe","continent":"europe","languages":["it"],"period":"contemporary"},"tags":["communication","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gesticulation in Italian","de":"Gesticulation in Italian","en":"Gesticulation in Italian"},"url":"https://en.wikipedia.org/wiki/Gesticulation_in_Italian","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Italy","de":"Culture of Italy","en":"Culture of Italy"},"url":"https://en.wikipedia.org/wiki/Culture_of_Italy","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صديقان عبر ساحة صاخبة يتبادلان حديثاً قصيراً كاملاً بأيديهما، ينتهي بهز الكتفين وحركة سريعة للمعصم تعني «انسَ الأمر».","de":"Zwei Freunde auf einer lauten Piazza führen ein kurzes Gespräch ausschließlich mit den Händen, das mit einem Schulterzucken und einem Handgelenkschnippen endet, das „vergiss es“ bedeutet.","en":"Two friends across a noisy piazza conduct a short conversation entirely with their hands, ending with a shrug and a flick of the wrist that means 'forget it'."},"misunderstanding":{"ar":"الاعتقاد بأن الإيماءات الإيطالية مجرد عادة مسرحية أو غريبة، بينما هي نظام تواصل منظم له معانٍ محددة.","de":"Die Annahme, italienische Gesten seien nur eine theatralische Angewohnheit, während sie ein strukturiertes Kommunikationssystem mit festen Bedeutungen sind.","en":"The belief that Italian gestures are just a theatrical habit, when they are actually a structured communication system with specific meanings."},"comparison":{"ar":"في ثقافات أخرى، قد تُستخدم الإيماءات بشكل أقل أو بمعانٍ مختلفة، لكنها نادراً ما تشكل نظاماً موازياً بهذا الثراء.","de":"In anderen Kulturen werden Gesten oft sparsamer oder mit anderen Bedeutungen eingesetzt, bilden aber selten ein so reiches paralleles System.","en":"In other cultures, gestures may be used more sparingly or with different meanings, but they rarely form such a rich parallel system."},"expression":{"original":"Ma che vuoi?","language":"Italiano","gloss":{"ar":"ماذا تريد؟! (تُقال مع إيماءة الأصابع المقبوضة)","de":"Was willst du?! (mit der zusammengekniffenen Fingergeste gesagt)","en":"What do you want?! (said with the pinched-fingers gesture)"},"usage":{"ar":"تُستخدم للتعبير عن الاستنكار أو عدم الفهم، وغالباً ما تُرافقها الإيماءة الشهيرة.","de":"Wird verwendet, um Ablehnung oder Unverständnis auszudrücken, oft begleitet von der berühmten Geste.","en":"Used to express dismissal or incomprehension, often accompanied by the famous gesture."},"transliteration":"ma che vuoi"}},{"id":"eur-046","version":2,"slug":"xenia-greek-hospitality-as-a-debt-to-the-gods","contentType":"note","category":"social-behaviour","title":{"ar":"الضيافة اليونانية: دين للآلهة","de":"Xenia: Griechische Gastfreundschaft als Pflicht","en":"Xenia: Greek hospitality as a debt to the gods"},"deck":{"ar":"كيف تحولت كرم الضيافة إلى التزام أخلاقي وديني في اليونان، من هوميروس إلى القرى المعاصرة.","de":"Wie aus einem antiken Ritual eine moralische und religiöse Verpflichtung wurde, die bis heute nachwirkt.","en":"How an ancient ritual of guest-friendship became a moral and religious obligation that still shapes everyday life."},"teaser":{"ar":"في اليونان، الضيافة ليست مجرد أدب، بل واجب مقدس. تعرف على مفهوم 'كسينيا' وكيف يظهر في الحياة اليومية.","de":"In Griechenland ist Gastfreundschaft mehr als Höflichkeit. Xenia verpflichtet – gegenüber Fremden und den Göttern.","en":"In Greece, hospitality is more than politeness. Xenia binds host and guest – and honours the gods."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور مقدسة","paragraphs":["في اليونان القديمة، كانت 'كسينيا' علاقة مؤسسية بين المضيف والضيف، تقوم على الكرم وتبادل الهدايا. كان زيوس 'كسينيوس' راعي الغرباء، ورفض الضيف جريمة تستوجب عقابًا إلهيًا.","كانت الطقوس رسمية: الترحيب، الطعام، الحمام، الهدايا، وقد تورث العلاقة للأجيال. ملحمة هوميروس 'أوديسة' قامت على هذا المبدأ: المضيفون الطيبون كألكينوس، والسيئون كالسيكلوب والخطابين، يرسمون الخريطة الأخلاقية."]},{"heading":"من الأسطورة إلى الواقع","paragraphs":["اليوم، تستخدم اليونانية الحديثة كلمة 'فيلوكسينيا' (حب الغرباء) للضيافة، وما زال تقديم الطعام والشراب للزائر عرفًا قويًا، خاصة خارج المدن الكبرى.","لكن المثالية القديمة ليست وصفًا دقيقًا للحياة الحديثة: سكان المدن مشغولون، والالتزام قد يُشعر المضيف بالضغط، وصورة 'الضيافة المقدسة' جزء من الصورة النمطية الوطنية."]}],"de":[{"heading":"Heilige Wurzeln","paragraphs":["Im antiken Griechenland war Xenia eine institutionalisierte Beziehung zwischen Gastgeber und Gast, geprägt von Großzügigkeit und Gegenseitigkeit. Zeus Xenios war der Schutzpatron der Fremden; die Ablehnung eines Gastes konnte göttliche Strafe nach sich ziehen.","Die Rituale waren formal: Begrüßung, Bewirtung, Bad, Geschenke – und die Beziehung konnte vererbt werden. Homers Odyssee baut darauf auf: Gute Gastgeber wie Alkinoos und schlechte wie der Zyklop oder die Freier zeichnen die moralische Landkarte."]},{"heading":"Vom Mythos zur Moderne","paragraphs":["Heute verwendet das Neugriechische Philoxenia (Liebe zu Fremden) für Gastfreundschaft. Besonders außerhalb der Großstädte ist es noch immer Norm, Besuchern Essen und Trinken anzubieten.","Doch das antike Ideal beschreibt nicht das moderne Leben: Städter sind oft zu beschäftigt, die Verpflichtung kann für Gastgeber Druck bedeuten, und das Bild der 'heiligen Gastfreundschaft' ist teils nationales Stereotyp."]}],"en":[{"heading":"Sacred roots","paragraphs":["In ancient Greece, xenia was an institutionalised relationship of generosity, gift exchange and reciprocity between host and guest. Hospitality was a moral and religious obligation: Zeus Xenios was the patron of strangers, and refusing a guest could bring divine punishment.","The rituals were formal: the guest was welcomed, fed, bathed and given gifts, and the relationship could be inherited by the next generation. Homer's Odyssey is built on xenia: the good host Alcinous and the bad hosts, the Cyclops and the suitors, define the moral map of the poem."]},{"heading":"From epic to everyday","paragraphs":["Modern Greek uses philoxenia ('love of strangers') for hospitality, and offering food and drink to a visitor remains a strong norm, especially outside big cities.","But the ancient ideal is not a description of modern Greek life: urban Greeks are often too busy to host, the obligation can be felt as pressure by hosts as well as guests, and the 'sacred hospitality' image is partly a national stereotype."]}]},"context":{"countries":["GR"],"region":"Southern Europe","continent":"europe","languages":["el"],"period":"contemporary"},"tags":["social-behaviour","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Xenia (Greek)","de":"Xenia (Greek)","en":"Xenia (Greek)"},"url":"https://en.wikipedia.org/wiki/Xenia_(Greek)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Odyssey","de":"Odyssey","en":"Odyssey"},"url":"https://en.wikipedia.org/wiki/Odyssey","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل غريب إلى منزل في قرية يونانية وقت الغداء، فيُجلس ويُطعم قبل أن يُسأل من هو ولماذا جاء.","de":"Ein Fremder kommt zur Essenszeit zu einem Dorfhaus in Griechenland und wird zum Sitzen und Essen gedrängt, bevor jemand fragt, wer er ist.","en":"A stranger arrives at a Greek village house at mealtime and is pressed to sit and eat before anyone asks who they are or why they came."},"misunderstanding":{"ar":"يعتقد البعض أن الضيافة اليونانية مجرد كرم عفوي، لكنها في الواقع نظام متبادل له جذور دينية، وقد يشعر المضيفون بالعبء.","de":"Viele halten griechische Gastfreundschaft für spontane Herzlichkeit, doch sie ist ein reziprokes System mit religiösen Wurzeln – und kann für Gastgeber belastend sein.","en":"Many assume Greek hospitality is simply spontaneous warmth, but it is a reciprocal system with religious roots – and hosts may feel it as a burden."},"comparison":{"ar":"في كثير من الثقافات، الضيافة اختيارية، لكن في اليونان تُعتبر التزامًا أخلاقيًا، وإن خففها الإيقاع الحضري.","de":"In vielen Kulturen ist Gastfreundschaft freiwillig; in Griechenland gilt sie als moralische Pflicht, auch wenn der städtische Alltag sie abschwächt.","en":"In many cultures hospitality is optional; in Greece it is treated as a moral duty, though urban pace softens it."}},{"id":"eur-047","version":2,"slug":"in-greece-the-name-day-outranks-the-birthday","contentType":"note","category":"family-and-friendship","title":{"ar":"عيد الاسم في اليونان يتقدم على عيد الميلاد","de":"In Griechenland hat der Namenstag Vorrang vor dem Geburtstag","en":"In Greece the name day outranks the birthday"},"deck":{"ar":"في اليونان، يحتفل الناس بعيد القديس الذي يحملون اسمه أكثر من عيد ميلادهم، وهو تقليد متجذر في التقويم الأرثوذكسي.","de":"In Griechenland feiern Menschen den Gedenktag ihres Namensheiligen oft intensiver als ihren Geburtstag – eine Tradition aus dem orthodoxen Kalender.","en":"In Greece, people often celebrate the feast day of their name saint more than their birthday, a custom rooted in the Orthodox calendar."},"teaser":{"ar":"عيد الاسم مناسبة اجتماعية كبرى في اليونان، حيث يتصل الأصدقاء والأقارب لتهنئة الشخص ويقدم الحلويات، بينما يتراجع عيد الميلاد أحيانًا.","de":"Der Namenstag ist in Griechenland ein gesellschaftliches Ereignis: Freunde und Verwandte gratulieren mit „Chronia Polla!“, und der Beschenkte gibt Süßigkeiten aus.","en":"A name day is a major social occasion in Greece: friends and relatives call or message 'Chronia Polla!', and the person offers sweets or drinks."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور العيد في التقويم المسيحي","paragraphs":["يأتي تقليد عيد الاسم من التقويم المسيحي للقديسين، حيث يحتفل الطفل الذي يحمل اسم قديس بيوم عيد ذلك القديس. وفي اليونان، يُعتبر هذا اليوم مناسبة واسعة الانتشار، وغالبًا ما يحتفل به الناس أكثر من عيد ميلادهم.","تقليديًا، يُسمى الأطفال اليونانيون على اسم أجدادهم، لذا يحمل الاسم تاريخًا عائليًا وحماية قديس في آن واحد."]},{"heading":"احتفالات تجمع الزملاء والأصدقاء","paragraphs":["في يوم الاسم، يزور الأصدقاء والأقارب الشخص أو يتصلون به أو يرسلون رسائل تهنئة مثل «كرونيا بولا!» (Chronia Polla)، وقد يقدم الشخص الحلويات أو المشروبات.","بسبب التقويم الأرثوذكسي، تتجمع العديد من أعياد الأسماء حول أعياد القديسين الكبرى، وأسماء شائعة مثل يانيس (القديس يوحنا) أو ماريا (العذراء مريم) تخلق أيامًا يحتفل فيها نصف المكتب.","تختلف درجة الاحتفال حسب المنطقة والجيل: فكبار السن وسكان الريف يحيون عيد الاسم بقوة أكبر، بينما يميل العديد من الشباب في المدن إلى اعتبار عيد الميلاد هو الاحتفال الرئيسي."]}],"de":[{"heading":"Wurzeln im christlichen Heiligenkalender","paragraphs":["Der Namenstag geht auf den christlichen Heiligenkalender zurück: Kinder, die nach einem Heiligen benannt sind, feiern dessen Gedenktag. In Griechenland wird dieser Tag weit verbreitet gefeiert, oft mehr als der Geburtstag.","Traditionell werden griechische Kinder nach den Großeltern benannt, sodass ein Name gleichzeitig Familiengeschichte und den Schutz eines Heiligen trägt."]},{"heading":"Feiern mit Kollegen und Freunden","paragraphs":["Am Namenstag besuchen Freunde und Verwandte die Person, rufen an oder schicken Nachrichten wie „Chronia Polla!“, und der Gefeierte bietet Süßigkeiten oder Getränke an.","Durch den orthodoxen Kalender häufen sich viele Namenstage um große Heiligenfeste, und häufige Namen wie Yannis (Johannes) oder Maria (Jungfrau Maria) führen zu Tagen, an denen die halbe Belegschaft feiert.","Die Intensität des Feierns variiert regional und generationell: Ältere und ländliche Griechen sowie praktizierende orthodoxe Familien begehen den Namenstag stärker, während viele jüngere Städter den Geburtstag als Hauptfeier betrachten."]}],"en":[{"heading":"Rooted in the Christian calendar of saints","paragraphs":["The name day custom comes from the Christian calendar of saints: children named after a saint celebrate that saint's day. In Greece it is widely celebrated, often more than a birthday.","Greek children are traditionally named after grandparents, so a name often carries a family history and a saint's protection at once."]},{"heading":"Celebrations that fill the office","paragraphs":["On the name day, friends and relatives visit, call or send messages ('Chronia Polla!'), and the person may offer sweets or drinks.","The Orthodox calendar means many name days cluster around major saints' feasts, and common names such as Yannis (St John) or Maria (the Virgin Mary) produce days when half the office is celebrating.","Observance varies by region and generation: older and rural Greeks and practising Orthodox families mark name days more strongly, while many younger Greeks in cities now treat birthdays as the main celebration."]}]},"context":{"countries":["GR"],"region":"Southern Europe","continent":"europe","languages":["el"],"period":"contemporary"},"tags":["family-and-friendship","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Name day","de":"Name day","en":"Name day"},"url":"https://en.wikipedia.org/wiki/Name_day","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Greece","de":"Culture of Greece","en":"Culture of Greece"},"url":"https://en.wikipedia.org/wiki/Culture_of_Greece","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زميل يوناني يدعى يانيس يتلقى مكالمات طوال صباح السابع من يناير، ويحضر صينية حلويات إلى المكتب، ويهنئه الفريق بـ«كرونيا بولا» بدلًا من «عيد ميلاد سعيد».","de":"Ein griechischer Kollege namens Yannis erhält am 7. Januar den ganzen Morgen Anrufe, bringt eine Platte Süßigkeiten ins Büro, und das Team wünscht ihm „Chronia Polla“ statt „Alles Gute zum Geburtstag“.","en":"A Greek colleague called Yannis receives calls all morning on 7 January, brings a tray of sweets to the office, and the team wishes him 'Chronia Polla' rather than 'happy birthday'."},"misunderstanding":{"ar":"قد يعتقد البعض أن عيد الاسم مجرد مناسبة دينية ثانوية، لكنه في اليونان مناسبة اجتماعية رئيسية تتجاوز عيد الميلاد في الأهمية.","de":"Manche halten den Namenstag für eine nebensächliche religiöse Angelegenheit, doch in Griechenland ist er ein zentrales soziales Ereignis, das den Geburtstag an Bedeutung übertreffen kann.","en":"Some assume a name day is a minor religious occasion, but in Greece it is a major social event that can outweigh the birthday."},"comparison":{"ar":"بينما يحتفل معظم الناس في أوروبا بعيد الميلاد، فإن عيد الاسم في اليونان يحمل ثقلًا اجتماعيًا مماثلًا أو أكبر، خاصة بين الأجيال الأكبر.","de":"Während in weiten Teilen Europas der Geburtstag im Mittelpunkt steht, hat der Namenstag in Griechenland ein ähnliches oder größeres soziales Gewicht, besonders bei älteren Generationen.","en":"While most Europeans focus on birthdays, name days in Greece carry similar or greater social weight, especially among older generations."}},{"id":"eur-048","version":2,"slug":"bread-and-salt-arriving-at-a-russian-home","contentType":"note","category":"everyday-life","title":{"ar":"الخبز والملح: الوصول إلى بيت روسي","de":"Brot und Salz: Ankunft in einem russischen Zuhause","en":"Bread and salt: arriving at a Russian home"},"deck":{"ar":"تقاليد الضيافة الروسية: من الخبز والملح إلى المائدة العامرة.","de":"Russische Gastfreundschaft: vom Brot-und-Salz-Ritual bis zum gedeckten Tisch.","en":"Russian hospitality: from the bread-and-salt welcome to the laden table."},"teaser":{"ar":"في روسيا، يُستقبل الضيوف تقليديًا بالخبز والملح، وهو ترحيب يعبر عن حسن الضيافة والاحترام.","de":"In Russland werden Gäste traditionell mit Brot und Salz empfangen, ein Zeichen von Gastfreundschaft und Respekt.","en":"In Russia, guests are traditionally welcomed with bread and salt, a greeting that signals hospitality and respect."},"readingMinutes":1,"sections":{"ar":[{"heading":"ترحيب بالخبز والملح","paragraphs":["في روسيا، يُستقبل الضيوف تقليديًا بالخبز والملح، وهو ترحيب يعبر عن حسن الضيافة والاحترام. يقدم المضيف الخبز، ويأخذ الضيف قطعة ويغمسها في الملح.","الزيارات مخطط لها ولكنها كريمة: يعد المضيفون طاولة بالشاي والمربى والمخللات وشيء أقوى، ورفض الطعام مباشرة صعب.","غالبًا ما يجلب الضيوف الحلويات أو الزهور، بأعداد فردية للاحتفالات وأعداد زوجية للجنازات، ويخلعون أحذيتهم عند الباب."]},{"heading":"كرم الضيافة كفخر","paragraphs":["كرم المضيف مسألة فخر، وعبارة 'chem bogaty, tem i rady' ('نحن سعداء بما لدينا') تؤطر المائدة كتقدمة وليس أداء.","أصبحت زيارات المنازل أقل شيوعًا في المدن خلال الفترة السوفيتية، عندما كان الناس يلتقون في المطابخ وفي الداشا، وهي أقل تكرارًا بين الشباب الروس الحضريين.","تختلف هذه العادات حسب العائلة والمنطقة والجيل، وقد تكون أبسط بكثير في الحياة اليومية."]}],"de":[{"heading":"Empfang mit Brot und Salz","paragraphs":["In Russland werden Gäste traditionell mit Brot und Salz empfangen, ein Zeichen von Gastfreundschaft und Respekt. Der Gastgeber bietet das Brot an, der Gast nimmt ein Stück und taucht es in Salz.","Besuche sind geplant, aber großzügig: Gastgeber decken den Tisch mit Tee, Marmelade, Essiggurken und etwas Stärkerem, und Essen rundheraus abzulehnen ist schwierig.","Gäste bringen oft Süßigkeiten oder Blumen mit, in ungerader Zahl für Feiern und gerader Zahl für Beerdigungen, und ziehen die Schuhe an der Tür aus."]},{"heading":"Gastfreundschaft als Stolz","paragraphs":["Die Großzügigkeit des Gastgebers ist eine Frage des Stolzes, und der Ausdruck 'chem bogaty, tem i rady' ('wir freuen uns über das, was wir haben') rahmt den Tisch als Angebot, nicht als Aufführung.","Hausbesuche wurden in Städten während der Sowjetzeit seltener, als man sich in Küchen und auf Datschen traf, und sind bei jüngeren urbanen Russen weniger häufig.","Diese Bräuche variieren je nach Familie, Region und Generation und können im Alltag viel schlichter sein."]}],"en":[{"heading":"A welcome of bread and salt","paragraphs":["In Russia, guests are traditionally welcomed with bread and salt, a greeting that signals hospitality and respect. The host offers the bread and the guest takes a piece and dips it in salt.","Visits are planned but generous: hosts lay out a table with tea, jam, pickles and something stronger, and refusing food outright is difficult.","Guests often bring sweets or flowers, in odd numbers for celebrations and even numbers for funerals, and take off their shoes at the door."]},{"heading":"Generosity as a matter of pride","paragraphs":["The host's generosity is a matter of pride, and the phrase 'chem bogaty, tem i rady' ('we are glad for what we have') frames the table as an offering rather than a performance.","Home visiting became less common in cities during the Soviet period, when people met in kitchens and at dachas, and it is less frequent among younger urban Russians.","These customs vary by family, region and generation, and can be much simpler in everyday life."]}]},"context":{"countries":["RU"],"region":"Eastern Europe","continent":"europe","languages":["ru"],"period":"contemporary"},"tags":["everyday-life","Eastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bread and salt","de":"Bread and salt","en":"Bread and salt"},"url":"https://en.wikipedia.org/wiki/Bread_and_salt","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Russia","de":"Culture of Russia","en":"Culture of Russia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Russia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل الضيف بصندوق شوكولاتة، ويخلع حذاءه، ويجلس إلى طاولة مليئة بالشاي والمربى والنقانق المقطعة قبل أن يُسأل عما يريد.","de":"Ein Gast kommt mit einer Schachtel Pralinen, zieht die Schuhe aus und sitzt an einem Tisch, der bereits mit Tee, Marmelade und Wurstscheiben gefüllt ist, bevor er gefragt wird, was er möchte.","en":"A guest arrives with a box of chocolates, takes off their shoes, and is seated at a table already filled with tea, jam and sliced sausage before being asked what they would like."},"misunderstanding":{"ar":"قد يعتقد الزائر أن رفض الطعام مقبول، لكنه قد يُفسر كإهانة لكرم المضيف.","de":"Ein Besucher könnte denken, dass es in Ordnung ist, Essen abzulehnen, aber das könnte als Beleidigung der Gastfreundschaft des Gastgebers aufgefasst werden.","en":"A visitor might think it's fine to refuse food, but it could be taken as an insult to the host's generosity."},"comparison":{"ar":"في ثقافات أخرى، قد يكون تقديم الطعام أقل إلحاحًا، بينما في روسيا يُصر المضيف على تناول الطعام.","de":"In anderen Kulturen mag das Anbieten von Essen weniger nachdrücklich sein, während in Russland der Gastgeber darauf besteht, dass man isst.","en":"In other cultures, offering food may be less insistent, while in Russia the host insists that you eat."}},{"id":"eur-049","version":2,"slug":"maltese-europe-s-only-semitic-official-language","contentType":"note","category":"languages","title":{"ar":"المالطية: لغة سامية في قلب أوروبا","de":"Maltesisch: Europas einzige semitische Amtssprache","en":"Maltese: Europe's Only Semitic Official Language"},"deck":{"ar":"لغة جزر مالطا تجمع بين جذور سامية ومفردات صقلية وإيطالية وإنجليزية، وتعيش يومياً بين لغتين.","de":"Die Sprache Maltas verbindet semitische Wurzeln mit sizilianischen, italienischen und englischen Einflüssen und lebt täglich zwischen zwei Sprachen.","en":"Malta's language pairs Semitic roots with Sicilian, Italian and English borrowings, living daily between two tongues."},"teaser":{"ar":"كيف تعيش لغة سامية وحيدة في الاتحاد الأوروبي بين طاولة العائلة ومكالمات العمل؟","de":"Wie lebt eine semitische Sprache im Alltag der EU, zwischen Familientisch, Arbeitsanruf und Ladenschild?","en":"How does a Semitic language survive inside the EU, moving between family tables, work calls and shop signs?"},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة سامية بحروف لاتينية","paragraphs":["المالطية لغة سامية وسطى انحدرت من العربية الصقلية في أواخر العصور الوسطى، وهي اللغة السامية الوحيدة المكتوبة بالحروف اللاتينية. هي اللغة الوطنية لمالطا واللغة الرسمية السامية والأفروآسيوية الوحيدة في الاتحاد الأوروبي.","أصبحت لغة رسمية عام 1934 إلى جانب الإنجليزية، بعد مسألة لغوية طويلة تنافست فيها الإيطالية والإنجليزية والمالطية.","يختلف استعمالها بين الأجيال والمناطق؛ فبعض لهجات الجزر تحتفظ بتفاصيل صوتية خاصة، بينما يميل الشباب في المدن إلى الإنجليزية أكثر."]},{"heading":"حياة بين لغتين","paragraphs":["اقترضت المالطية كثيراً من الصقلية والإيطالية والإنجليزية، والكلام اليومي يخلط المالطية بالإنجليزية فيما يُعرف بـ«مالتينغليش».","معظم المالطيين ثنائيو اللغة، ويبقى الإنجليزية لغة كثير من المدارس والأعمال والنصوص القانونية."]}],"de":[{"heading":"Semitisch mit lateinischen Buchstaben","paragraphs":["Maltesisch ist eine zentralsemitische Sprache, die aus dem spätmittelalterlichen sizilianischen Arabisch hervorging, und die einzige semitische Sprache im lateinischen Alphabet. Sie ist die Nationalsprache Maltas und die einzige offizielle semitische und afroasiatische Sprache der Europäischen Union.","1934 wurde sie neben Englisch Amtssprache, nach einer langen Sprachfrage, in der Italienisch, Englisch und Maltesisch konkurrierten.","Der Gebrauch variiert regional und generationell: Manche Inseldialekte bewahren eigene Lautnuancen, während Jüngere in Städten häufiger zum Englischen wechseln."]},{"heading":"Leben in zwei Sprachen","paragraphs":["Maltesisch hat viel aus dem Sizilianischen, Italienischen und Englischen entlehnt; die Alltagssprache mischt Maltesisch und Englisch, oft „Maltenglish“ genannt.","Die meisten Malteser sind zweisprachig, und Englisch bleibt die Sprache vieler Schulen, Unternehmen und Rechtstexte."]}],"en":[{"heading":"Semitic in Latin Letters","paragraphs":["Maltese is a Central Semitic language derived from late medieval Sicilian Arabic, and the only Semitic language written in the Latin alphabet. It is Malta's national language and the only official Semitic and Afroasiatic language of the European Union.","It became official in 1934 alongside English, after a long language question in which Italian, English and Maltese competed.","Usage shifts by region and generation: some island dialects keep distinct sound details, while younger city speakers lean more on English."]},{"heading":"Living Between Two Languages","paragraphs":["Maltese has borrowed heavily from Sicilian, Italian and English, and everyday speech mixes Maltese with English, often called 'Maltenglish'.","Most Maltese are bilingual in Maltese and English, and English remains the language of many schools, businesses and legal texts."]}]},"context":{"countries":["MT"],"region":"Southern Europe","continent":"europe","languages":["mt","en"],"period":"contemporary"},"tags":["languages","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Maltese language","de":"Maltese language","en":"Maltese language"},"url":"https://en.wikipedia.org/wiki/Maltese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Malta","de":"Languages of Malta","en":"Languages of Malta"},"url":"https://en.wikipedia.org/wiki/Languages_of_Malta","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة مالطية تتحادث بالمالطية على الطاولة، وتنتقل إلى الإنجليزية في مكالمة عمل، وتطلب بالمالطية عند البار، بينما اللافتة خارجاً تخلط اللغتين.","de":"Eine maltesische Familie plaudert am Tisch auf Maltesisch, wechselt für einen Arbeitsanruf ins Englische und bestellt an der Bar auf Maltesisch, während das Schild draußen beide Sprachen mischt.","en":"A Maltese family chats in Maltese at the table, switches to English for a work call and orders in Maltese at the bar, while the sign outside mixes both languages."},"misunderstanding":{"ar":"وصف اللغة بالسامية يخص القواعد والمفردات الأساسية، لا المعجم الحديث كله.","de":"Das Etikett „semitisch“ beschreibt Grammatik und Grundwortschatz, nicht das gesamte moderne Lexikon.","en":"The Semitic label describes grammar and core vocabulary, not the whole modern lexicon."},"comparison":{"ar":"مثل لغة تشبه بيتاً قديماً أُضيفت إليه غرف حديثة: الأساس سامي، والواجهة أوروبية متغيّرة.","de":"Wie ein altes Haus mit modernen Anbauten: Das Fundament ist semitisch, die Fassade europäisch und im Wandel.","en":"Like an old house with modern extensions: the foundation is Semitic, the facade European and changing."},"expression":{"original":"Kif int?","language":"Malti","gloss":{"ar":"كيف حالك؟","de":"Wie geht es dir?","en":"How are you?"},"usage":{"ar":"تحية يومية شائعة بين الأصدقاء والجيران، تُقال عند اللقاء أو في بداية مكالمة.","de":"Geläufige Alltagsbegrüßung unter Freunden und Nachbarn, beim Treffen oder zu Beginn eines Anrufs.","en":"A common everyday greeting among friends and neighbours, used on meeting or at the start of a call."},"transliteration":"Kif int?"}},{"id":"eur-050","version":2,"slug":"cyprus-two-official-languages-two-vernaculars-one-divided-island","contentType":"note","category":"languages","title":{"ar":"قبرص: لغتان رسميتان وعاميتان منفصلتان","de":"Zypern: zwei Amtssprachen, zwei getrennte Dialekte","en":"Cyprus: two official languages, two vernaculars apart"},"deck":{"ar":"اليونانية والتركية رسميتان، لكن الحياة اليومية تتحدث بلهجات محلية، والانقسام يعمق الفجوة اللغوية.","de":"Griechisch und Türkisch sind offiziell, doch im Alltag sprechen die Menschen lokale Dialekte – und die Teilung vertieft die sprachliche Kluft.","en":"Greek and Turkish are official, but daily life speaks local dialects, and the island's division deepens the linguistic gap."},"teaser":{"ar":"في قبرص، اللغة الرسمية ليست دائماً لغة الشارع، والانقسام السياسي يترك بصمته على الكلمات اليومية.","de":"Auf Zypern ist die Amtssprache nicht immer die Sprache der Straße, und die politische Teilung hinterlässt Spuren im täglichen Wortschatz.","en":"In Cyprus, the official language is not always the language of the street, and political division leaves its mark on everyday words."},"readingMinutes":1,"sections":{"ar":[{"heading":"الرسمي مقابل العامية","paragraphs":["جمهورية قبرص لديها لغتان رسميتان: اليونانية والتركية. الوثائق الرسمية تستخدم اليونانية الحديثة القياسية والتركية القياسية. لكن في الحياة اليومية، يتحدث القبارصة اليونانيون بلهجة قبرصية يونانية مميزة، بينما يتحدث القبارصة الأتراك بلهجة قبرصية تركية.","منذ انقسام عام 1974، تعيش الطائفتان بشكل منفصل إلى حد كبير، ونادراً ما تُستخدم اليونانية والتركية عبر خط وقف إطلاق النار. هذا الانفصال جعل اللهجتين تتطوران بشكل مستقل لعقود."]},{"heading":"لغات الأقليات والإنجليزية","paragraphs":["يعترف الدستور بالأرمنية والعربية القبرصية (المارونية) كلغات أقليات، وتحافظ الطائفتان على مدارس وكنائس خاصة بهما. الإنجليزية واسعة الانتشار في الأعمال والتعليم العالي والسياحة، وهي لغة مشتركة في العديد من البيئات المختلطة أو الدولية.","يختلف استخدام اللغة حسب المنطقة والجيل؛ فالشباب في المدن الساحلية قد ينتقلون بسلاسة بين اللهجة المحلية والإنجليزية، بينما يتمسك كبار السن في القرى باللهجة المحلية في حياتهم اليومية."]}],"de":[{"heading":"Offiziell versus Alltag","paragraphs":["Die Republik Zypern hat zwei Amtssprachen: Griechisch und Türkisch. Offizielle Dokumente verwenden Standardgriechisch und Standardtürkisch. Im Alltag sprechen griechische Zyprioten jedoch einen eigenständigen zypriotischen griechischen Dialekt, während türkische Zyprioten zypriotisches Türkisch sprechen.","Seit der Teilung 1974 leben die beiden Gemeinschaften weitgehend getrennt, und Griechisch und Türkisch werden selten über die Waffenstillstandslinie hinweg verwendet. Diese Trennung hat dazu geführt, dass sich die beiden Dialekte jahrzehntelang unabhängig voneinander entwickelt haben."]},{"heading":"Minderheitensprachen und Englisch","paragraphs":["Die Verfassung erkennt Armenisch und zypriotisches Arabisch (Maronitisch) als Minderheitensprachen an, und armenische Zyprioten und Maroniten unterhalten eigene Schulen und Kirchen. Englisch ist in Wirtschaft, Hochschulbildung und Tourismus weit verbreitet und dient als gemeinsame Sprache in vielen gemischten oder internationalen Kontexten.","Der Sprachgebrauch variiert je nach Region und Generation: Junge Menschen in Küstenstädten wechseln fließend zwischen lokalem Dialekt und Englisch, während ältere Bewohner auf dem Land im Alltag am lokalen Dialekt festhalten."]}],"en":[{"heading":"Official versus everyday speech","paragraphs":["The Republic of Cyprus has two official languages: Greek and Turkish. Official documents use Standard Modern Greek and Standard Turkish. In everyday life, however, Greek Cypriots speak Cypriot Greek, a divergent dialect with distinctive vocabulary, phonetics and syntax, while Turkish Cypriots speak Cypriot Turkish.","Since the 1974 division, the two communities have largely lived separately, and Greek and Turkish are rarely used across the ceasefire line. This separation has allowed the two vernaculars to develop independently for decades."]},{"heading":"Minority tongues and English","paragraphs":["The constitution recognises Armenian and Cypriot Arabic (Maronite) as minority languages, and Armenian Cypriots and Maronites maintain their own schools and churches. English is widely used in business, higher education and tourism and serves as the common language in many mixed or international settings.","Language use varies by region and generation: young people in coastal cities may switch smoothly between the local dialect and English, while older villagers hold on to the local dialect in daily life."]}]},"context":{"countries":["CY"],"region":"Eastern Mediterranean","continent":"europe","languages":["el","tr"],"period":"contemporary"},"tags":["languages","Eastern Mediterranean"],"sources":[{"organization":"Wikipedia","title":{"ar":"Languages of Cyprus","de":"Languages of Cyprus","en":"Languages of Cyprus"},"url":"https://en.wikipedia.org/wiki/Languages_of_Cyprus","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Cypriot Greek","de":"Cypriot Greek","en":"Cypriot Greek"},"url":"https://en.wikipedia.org/wiki/Cypriot_Greek","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صاحب متجر في نيقوسيا يتحدث القبرصية اليونانية مع زبون، ويبدل إلى الإنجليزية مع سائح، ويقرأ صحيفة باليونانية عند المنضدة.","de":"Ein Ladenbesitzer in Nikosia spricht mit einem Kunden zypriotisches Griechisch, wechselt für einen Touristen ins Englische und liest an der Theke eine griechischsprachige Zeitung.","en":"A Nicosia shopkeeper speaks Cypriot Greek to a customer, switches to English for a tourist and reads a Greek-language newspaper at the counter."},"misunderstanding":{"ar":"الاعتقاد بأن اليونانية والتركية الرسميتين تعكسان تلقائياً لغة الشارع، بينما اللهجات المحلية هي السائدة في الحياة اليومية.","de":"Die Annahme, dass die Amtssprachen Griechisch und Türkisch automatisch die Alltagssprache widerspiegeln, obwohl die lokalen Dialekte im täglichen Leben vorherrschen.","en":"Assuming that official Greek and Turkish automatically reflect the language of the street, when local dialects dominate everyday life."},"comparison":{"ar":"مثل بلجيكا حيث الهولندية والفرنسية رسميتان لكن الحياة اليومية تختلف، أو كتالونيا حيث اللغة المحلية أقوى في الشارع.","de":"Ähnlich wie in Belgien, wo Niederländisch und Französisch offiziell sind, der Alltag aber anders aussieht, oder in Katalonien, wo die lokale Sprache auf der Straße stärker ist.","en":"Similar to Belgium, where Dutch and French are official but daily life differs, or Catalonia, where the local language is stronger on the street."},"expression":{"original":"Καλημέρα","language":"Ελληνικά","gloss":{"ar":"صباح الخير","de":"Guten Morgen","en":"Good morning"},"usage":{"ar":"تحية صباحية شائعة في قبرص اليونانية، تُستخدم في المتاجر والمكاتب.","de":"Ein häufiger Morgengruß im zypriotischen Griechisch, verwendet in Geschäften und Büros.","en":"A common morning greeting in Cypriot Greek, used in shops and offices."},"transliteration":"kalimera"}},{"id":"eur-051","version":2,"slug":"andorra-a-country-that-runs-on-catalan","contentType":"note","category":"languages","title":{"ar":"أندورا: دولة تتحدث الكتالونية","de":"Andorra: ein Land auf Katalanisch","en":"Andorra: a country running on Catalan"},"deck":{"ar":"في وديان البرانس، تُدار الحياة العامة بلغة واحدة، بينما تتنوع اللغات داخل البيوت والمدارس.","de":"In den Pyrenäentälern läuft das öffentliche Leben auf einer Sprache, während in Häusern und Schulen mehrere Sprachen zusammenkommen.","en":"In the Pyrenean valleys, public life moves in one language while homes and schools bring several together."},"teaser":{"ar":"أندورا الدولة الوحيدة التي تجعل الكتالونية لغتها الرسمية الوحيدة، لكن سكانها يعيشون يومياً بلغات متعددة.","de":"Andorra ist der einzige Staat, in dem Katalanisch alleinige Amtssprache ist, doch im Alltag hört man viele Sprachen.","en":"Andorra is the only state where Catalan is the sole official language, yet daily life is filled with several languages."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة المؤسسات والحياة العامة","paragraphs":["أندورا هي الدولة الوحيدة في العالم التي تُعدّ الكتالونية لغتها الرسمية الوحيدة. فهي لغة البرلمان والمدارس والإدارة ومعظم وسائل الإعلام، ويستخدمها السكان في الشارع والمتاجر والدوائر الرسمية.","جعل دستور عام 1993 الكتالونية لغة رسمية، وأرسى أندورا إمارة مشتركة برلمانية. وبذلك ارتبطت اللغة بالنظام السياسي نفسه، لا بمجرد عادة يومية.","تختلف هذه الصورة بحسب المنطقة والجيل: فالأجيال الشابة تتعلم الكتالونية في المدرسة، بينما يحتفظ بعض كبار السن بعادات لغوية مختلفة في البيت."]},{"heading":"مدارس متعددة وبيوت متنوعة","paragraphs":["النظام المدرسي تعددي: تتعايش المناهج الأندورية والإسبانية والفرنسية، فقد يتعلم الطفل بالكتالونية أو الإسبانية أو الفرنسية حسب المدرسة التي يلتحق بها.","نسبة كبيرة من المقيمين أجانب، وكثير منهم يتحدث الإسبانية أو البرتغالية في المنزل ويستخدم الكتالونية في الحياة العامة. هكذا تصبح الكتالونية لغة اللقاء المشترك في الفضاء العام."]}],"de":[{"heading":"Die Sprache der Institutionen","paragraphs":["Andorra ist der einzige Staat der Welt, in dem Katalanisch die alleinige Amtssprache ist. Es ist die Sprache des Parlaments, der Schulen, der Verwaltung und der meisten Medien.","Die Verfassung von 1993 machte Katalanisch offiziell und begründete Andorra als parlamentarischen Kofürstentum. Die Sprache ist damit eng mit der politischen Ordnung verbunden.","Je nach Region und Generation zeigt sich das unterschiedlich: Jüngere lernen Katalanisch in der Schule, ältere Menschen behalten zu Hause andere sprachliche Gewohnheiten."]},{"heading":"Mehrere Schulen, viele Herkunftssprachen","paragraphs":["Das Schulsystem ist plural: andorranische, spanische und französische Lehrpläne bestehen nebeneinander, sodass Kinder je nach Schule auf Katalanisch, Spanisch oder Französisch unterrichtet werden.","Ein großer Teil der Einwohner sind Ausländer, viele sprechen zu Hause Spanisch oder Portugiesisch und nutzen Katalanisch im öffentlichen Leben. So wird Katalanisch zur gemeinsamen Sprache im öffentlichen Raum."]}],"en":[{"heading":"The language of institutions","paragraphs":["Andorra is the only state in the world where Catalan is the sole official language. It is the language of parliament, schools, administration and most media, and residents use it in the street, in shops and in offices.","The constitution of 1993 made Catalan official and established Andorra as a parliamentary co-principality, tying the language closely to the political order itself.","This picture varies by region and generation: younger people learn Catalan at school, while some older residents keep different language habits at home."]},{"heading":"Plural schools, mixed homes","paragraphs":["The school system is plural: Andorran, Spanish and French curricula coexist, so children may be taught in Catalan, Spanish or French depending on the school.","A large share of residents are foreign nationals, and many speak Spanish or Portuguese at home while using Catalan in public life. Catalan thus becomes the shared language of public space."]}]},"context":{"countries":["AD"],"region":"Pyrenees","continent":"europe","languages":["ca"],"period":"contemporary"},"tags":["languages","Pyrenees"],"sources":[{"organization":"Wikipedia","title":{"ar":"Culture of Andorra","de":"Culture of Andorra","en":"Culture of Andorra"},"url":"https://en.wikipedia.org/wiki/Culture_of_Andorra","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Catalan language","de":"Catalan language","en":"Catalan language"},"url":"https://en.wikipedia.org/wiki/Catalan_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طفل في مدرسة أندورية يكتب بالكتالونية، ويعود إلى بيت تتحدث أسرته فيه الإسبانية، ثم يتحول إلى الفرنسية في درس تزلج مع مدرب زائر.","de":"Ein Kind schreibt in einer andorranischen Schule auf Katalanisch, kehrt in eine spanischsprachige Familie zurück und wechselt im Skikurs mit einem Gastlehrer ins Französische.","en":"A child in an Andorran school writes in Catalan, goes home to a Spanish-speaking family and switches to French for a ski lesson with a visiting instructor."},"misunderstanding":{"ar":"يُظن أحياناً أن الكتالونية لغة هامشية في أندورا، لكنها لغة الدولة والمدارس والإدارة، وإن كان الإسباني يُسمع كثيراً في الحياة اليومية.","de":"Manchmal wird angenommen, Katalanisch sei in Andorra eine Randsprache, doch es ist die Sprache von Staat, Schulen und Verwaltung, auch wenn Spanisch im Alltag oft zu hören ist.","en":"People sometimes assume Catalan is a marginal language in Andorra, but it is the language of the state, schools and administration, even if Spanish is widely heard in daily life."},"comparison":{"ar":"تشبه أندورا حالات أوروبية صغيرة تعيش بلغة رسمية واحدة مع تنوع لغوي في البيوت، لكن وضع الكتالونية فيها فريد لأنه لا يشاركها أي لغة رسمية أخرى.","de":"Andorra ähnelt kleinen europäischen Staaten mit einer Amtssprache und mehrsprachigen Haushalten, doch die Lage des Katalanischen ist besonders, weil keine zweite Amtssprache danebensteht.","en":"Andorra resembles small European states with one official language and multilingual households, but Catalan's position is unusual because no second official language stands beside it."},"expression":{"original":"Bon dia","language":"Català","gloss":{"ar":"صباح الخير","de":"Guten Morgen","en":"Good morning"},"usage":{"ar":"تحية صباحية شائعة تُقال عند دخول المتاجر والمدارس والدوائر الرسمية.","de":"Übliche Morgengrußformel in Läden, Schulen und Ämtern.","en":"A common morning greeting when entering shops, schools and offices."},"transliteration":"bon dia"}},{"id":"eur-052","version":2,"slug":"san-marino-s-six-month-captains-and-the-oldest-republic","contentType":"detail","category":"traditions","title":{"ar":"قبطانان سان مارينو كل ستة أشهر","de":"Sechs Monate, zwei Kapitäne","en":"San Marino's two captains, six months each"},"deck":{"ar":"في هذه الجمهورية الصغيرة المحاطة بإيطاليا، يتولى رجلان منصبهما مرتين في السنة، في احتفال مدني يعود إلى قرون.","de":"In dem kleinen Staat innerhalb Italiens übernehmen zweimal im Jahr zwei Männer das höchste Amt, in einem zivilen Ritual mit langer Geschichte.","en":"In the small state surrounded by Italy, two men take the top office twice a year, in a civic ritual with centuries behind it."},"teaser":{"ar":"سان مارينو تصف نفسها بأنها أقدم جمهورية باقية، ويحكمها قبطانان متساويان يُنتخبان كل ستة أشهر في احتفال شعبي.","de":"San Marino nennt sich die älteste noch bestehende Republik. Regiert wird sie von zwei gleichberechtigten Kapitänen, die alle sechs Monate gewählt werden.","en":"San Marino calls itself the world's oldest surviving republic. It is led by two equal Captains Regent, chosen every six months in a ceremony that is part politics, part pageant."},"readingMinutes":1,"sections":{"ar":[{"heading":"حكّام بفترات قصيرة","paragraphs":["تقع سان مارينو داخل إيطاليا، وتقول إن الحجّار مارينوس أسّسها عام 301 ميلادية. يحكمها قائدان يُسمّيان القبطانين الحاكمين، يختارهما المجلس الأعظم العام كل ستة أشهر.","هذا النظام مأخوذ من القناصل الرومان: رجلان متساويان بلا سلطة تنفيذية تُذكر، وفترة قصيرة تمنع تراكم السلطة في يد واحدة.","يُختار القبطانان من أحزاب الائتلاف، فالمنصب طقس مدني قبل أن يكون وظيفة حكومية، مع مواكب بالأزياء التاريخية. وتختلف حرارة هذه المناسبة بين الأجيال، إذ يتابعها الشباب على الشاشات أكثر من الميدان."]},{"heading":"يوم التنصيب","paragraphs":["يقام حفل التنصيب في الأول من نيسان/أبريل والأول من تشرين الأول/أكتوبر من كل عام، ويعود هذا التقليد إلى عام 1243 على الأقل.","في ذلك اليوم تمتلئ الساحة أمام قصر الحكومة برماة القوس والنشاب والمسؤولين، بينما يتسلّم القبطانان الجديدان مهامهما.","أما الادعاء بأنها أقدم جمهورية فهو تقليد وطني أكثر منه حقيقة تاريخية مستقرة، وصلاحيات القبطانين رمزية إلى حد بعيد."]}],"de":[{"heading":"Kurze Amtszeiten gegen Machtfülle","paragraphs":["San Marino liegt vollständig in Italien und beruft sich auf den Steinmetz Marinus, der es 301 nach Christus gegründet haben soll. Zwei Staatsoberhäupter, die Capitani Reggenti, werden alle sechs Monate vom Großen und Allgemeinen Rat gewählt.","Das System stammt von den römischen Konsuln: zwei gleichgestellte Häupter ohne nennenswerte Exekutivgewalt, deren kurze Amtszeit die Anhäufung von Macht verhindern soll.","Die Kapitäne kommen aus Koalitionsparteien; das Amt ist ebenso bürgerliches Ritual wie Regierungsposten, mit Umzügen in historischen Kostümen. Je nach Generation und Region wird das Ereignis unterschiedlich verfolgt, oft am Bildschirm statt auf dem Platz."]},{"heading":"Der Tag der Vereidigung","paragraphs":["Die Amtseinführung findet jedes Jahr am 1. April und am 1. Oktober statt; die Tradition reicht mindestens bis 1243 zurück.","An diesem Tag füllt sich der Platz vor dem Palazzo Pubblico mit Armbrustschützen und Amtsträgern, während die neuen Kapitäne ihr Amt antreten.","Der Anspruch, die älteste Republik zu sein, ist eher nationale Tradition als gesicherte Tatsache, und die Befugnisse der Kapitäne sind weitgehend zeremoniell."]}],"en":[{"heading":"Short terms against concentrated power","paragraphs":["San Marino is a microstate surrounded by Italy, claiming the stonecutter Marinus founded it in 301 AD. Its two heads of state, the Captains Regent, are elected every six months by the Great and General Council.","The diarchy comes from the Roman consuls: two equal heads of state with no real executive power, serving short terms so power cannot accumulate.","The captains are drawn from coalition parties, and the office is a civic ritual as much as a government post, with processions in historical costume. How closely people follow it varies by generation and region, with many watching on screens rather than in the square."]},{"heading":"The day of investiture","paragraphs":["The investiture ceremony takes place on 1 April and 1 October each year, a tradition dating back at least to 1243.","On that day the square in front of the Palazzo Pubblico fills with crossbowmen and officials as the new Captains Regent take office for six months.","The 'oldest republic' claim is a national tradition rather than a settled historical fact, and the captains' powers are largely ceremonial."]}]},"context":{"countries":["SM"],"region":"Southern Europe","continent":"europe","languages":["it"],"period":"contemporary"},"tags":["traditions","Southern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Captains Regent","de":"Captains Regent","en":"Captains Regent"},"url":"https://en.wikipedia.org/wiki/Captains_Regent","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"San Marino","de":"San Marino","en":"San Marino"},"url":"https://en.wikipedia.org/wiki/San_Marino","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الأول من نيسان/أبريل تمتلئ الساحة أمام قصر الحكومة برماة القوس والنشاب والمسؤولين، بينما يتسلّم القبطانان الجديدان مهامهما لستة أشهر.","de":"Am 1. April füllt sich der Platz vor dem Palazzo Pubblico mit Armbrustschützen und Amtsträgern, während die neuen Kapitäne ihr Amt für sechs Monate antreten.","en":"On 1 April the square in front of the Palazzo Pubblico fills with crossbowmen and officials as the new Captains Regent take office for six months."},"misunderstanding":{"ar":"كثيرون يظنون أن القبطانين يحكمان البلاد فعليًا، لكن سلطاتهما رمزية غالبًا، والسياسة تتحدد في المجلس الأعظم العام وتحت تأثير إيطاليا.","de":"Viele halten die Kapitäne für die eigentlichen Regierenden, doch ihre Macht ist meist symbolisch; Politik wird im Großen und Allgemeinen Rat entschieden, unter italienischem Einfluss.","en":"Many assume the two captains actually run the country, but their powers are mostly symbolic; politics is decided in the Great and General Council and shaped by Italy's influence."},"comparison":{"ar":"يشبه هذا الثنائي القناصل الرومان، لكنه يختلف عن رئاسات اليوم التي تدوم سنوات، فالفترة القصيرة هنا هي جوهر الفكرة.","de":"Das Duo erinnert an die römischen Konsuln, unterscheidet sich aber von heutigen Präsidentschaften mit mehrjähriger Amtszeit – die Kürze ist hier der Kern.","en":"The pair echoes the Roman consuls but differs from modern presidencies that last years — here the brevity is the whole point."}},{"id":"eur-053","version":2,"slug":"wigilia-poland-s-christmas-eve-is-the-main-event","contentType":"note","category":"traditions","title":{"ar":"فيغيلية: عشاء عيد الميلاد البولندي","de":"Wigilia: Polens Weihnachtsabend als Hauptfest","en":"Wigilia: Poland's Christmas Eve Is the Main Event"},"deck":{"ar":"في بولندا يكون عشاء ليلة عيد الميلاد هو الحدث الأهم، لا يوم العيد نفسه، إذ تجتمع العائلة حول مائدة بلا لحم.","de":"In Polen ist das Abendessen am 24. Dezember für viele Familien wichtiger als der Weihnachtstag selbst – fleischlos und mit einem freien Platz.","en":"In Poland the supper on 24 December matters more than Christmas Day for many families, meatless and with one chair deliberately empty."},"teaser":{"ar":"عشاء فيغيلية في الرابع والعشرين من ديسمبر أهم من يوم العيد نفسه لدى كثير من العائلات البولندية، ويبدأ عند ظهور أول نجمة.","de":"Wigilia beginnt mit dem ersten Stern, bleibt fleischlos und verbindet Karpfen, Opłatek und einen leeren Stuhl zu einem Abend voller Erinnerung.","en":"Wigilia begins when the first star appears, stays meatless, and links carp, opłatek and an empty place into an evening of hospitality and memory."},"readingMinutes":1,"sections":{"ar":[{"heading":"مائدة تبدأ مع أول نجمة","paragraphs":["في بولندا يُقام عشاء فيغيلية مساء الرابع والعشرين من ديسمبر، وهو عند كثير من العائلات أهم من يوم عيد الميلاد نفسه. يبدأ العشاء تقليدياً عند ظهور أول نجمة في السماء، وتكون المائدة بلا لحم: كارب ورنجة وبيروغي وحساء الشمندر وعصير فواكه مجففة.","تُتداول قطعة خبز مقدسة تُسمى أوبواتيك على المائدة، فيكسر كل حاضر قطعة ويتبادل التمنيات مع الآخرين. وتُترك غالباً مكانة فارغة لضيف غير متوقع أو لأقارب غائبين، في تقليد يجمع بين حسن الضيافة والذاكرة."]},{"heading":"من المائدة إلى كنيسة منتصف الليل","paragraphs":["بعد العشاء يذهب كثيرون إلى باستيركا، قداس منتصف الليل، في الكنائس الكاثوليكية، وتُتبادل التهاني بعبارة «فيسوويتش شفيونت».","تختلف العادات بين الأجيال والمناطق: فقاعدة الأطباق الاثني عشر مثالية شعبية لا ممارسة شاملة، وفي المدن قد يكون العشاء أقصر والجانب الديني أضعف."]}],"de":[{"heading":"Ein Tisch, der mit dem ersten Stern beginnt","paragraphs":["In Polen findet am Abend des 24. Dezember das Wigilia-Abendessen statt, das für viele Familien wichtiger ist als der Weihnachtstag selbst. Traditionell beginnt es mit dem Erscheinen des ersten Sterns und bleibt fleischlos: typisch sind Karpfen, Hering, Pierogi, Rote-Bete-Suppe und Kompott aus Trockenfrüchten.","Am Tisch wird ein Opłatek geteilt, eine Weihnachtshostie; jeder bricht ein Stück ab und tauscht Wünsche aus. Oft bleibt ein Platz für einen unerwarteten Gast oder abwesende Verwandte frei – ein Brauch zwischen Gastfreundschaft und Erinnerung."]},{"heading":"Vom Tisch zur Mitternachtsmesse","paragraphs":["Nach dem Essen folgt in katholischen Kirchen die Pasterka, die Mitternachtsmesse, und man wünscht einander „Wesołych Świąt“.","Regionale und generationelle Unterschiede sind groß: Die Regel der zwölf Gerichte ist ein volkstümliches Ideal, kein allgemeiner Brauch, und in Städten fällt das Essen kürzer und der religiöse Teil schwächer aus."]}],"en":[{"heading":"A Table That Starts With the First Star","paragraphs":["In Poland, Wigilia is the Christmas Eve supper on 24 December, and for many families it is more important than Christmas Day itself. The meal traditionally begins when the first star appears and is meatless: typical dishes include carp, herring, pierogi, beetroot soup and dried-fruit compote.","An opłatek, a Christmas wafer, is shared at the table; each person breaks off a piece and exchanges wishes. An empty place is often set for an unexpected guest or for absent relatives, a custom linked to hospitality and memory."]},{"heading":"From the Table to Midnight Mass","paragraphs":["After supper, many go to Pasterka, the midnight Mass, in Catholic churches, and wishes of „Wesołych Świąt“ are exchanged.","Regional and generational variation is wide: the twelve-dish rule is a folk ideal rather than a universal practice, and in cities and among younger Poles the supper may be shorter and the religious element weaker."]}]},"context":{"countries":["PL"],"region":"Central Europe","continent":"europe","languages":["pl"],"period":"contemporary"},"tags":["traditions","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Wigilia","de":"Wigilia","en":"Wigilia"},"url":"https://en.wikipedia.org/wiki/Wigilia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Poland","de":"Culture of Poland","en":"Culture of Poland"},"url":"https://en.wikipedia.org/wiki/Culture_of_Poland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة بولندية تضع اثني عشر طبقاً على المائدة، وتتشارك الأوبواتيك، وتترك كرسياً فارغاً، ثم تذهب إلى باستيركا في منتصف الليل.","de":"Eine polnische Familie stellt zwölf Gerichte auf den Tisch, teilt den Opłatek, lässt einen Stuhl leer und geht um Mitternacht zur Pasterka.","en":"A Polish family sets twelve dishes on the table, shares the opłatek, leaves one chair empty and then goes to Pasterka at midnight."},"misunderstanding":{"ar":"يظن بعض الزوار أن يوم عيد الميلاد هو الذروة، لكن كثيراً من البولنديين يعتبرون ليلة الرابع والعشرين قلب الاحتفال.","de":"Manche Besucher halten den Weihnachtstag für den Höhepunkt, doch viele Polen sehen den Abend des 24. Dezember als Herzstück des Festes.","en":"Some visitors assume Christmas Day is the peak, but many Poles treat the evening of the 24th as the heart of the celebration."},"comparison":{"ar":"يشبه هذا العشاء احتفالات ليلة العيد في دول مجاورة، لكن الطابع النباتي وطقس الأوبواتيك والمكان الفارغ يمنحانه خصوصية بولندية.","de":"Ähnliche Abendfeiern gibt es in Nachbarländern, doch die fleischlose Küche, der Opłatek und der freie Platz machen Wigilia besonders polnisch.","en":"Neighbouring countries hold similar evening feasts, but the meatless menu, the opłatek and the empty place give Wigilia its distinctly Polish shape."}},{"id":"eur-054","version":2,"slug":"czechia-the-european-country-that-stopped-going-to-church","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"التشيك: أمة تركت الكنيسة خلفها","de":"Tschechien: Europas Land ohne Kirchgang","en":"Czechia: the European country that stopped going to church"},"deck":{"ar":"في التشيك، أصبح الإلحاد هو القاعدة، والكنائس شبه فارغة، لكن العطلات الدينية ما زالت مناسبات عائلية.","de":"In Tschechien ist Konfessionslosigkeit die Norm, Kirchen stehen leer, doch religiöse Feiertage bleiben Familienfeste.","en":"In Czechia, irreligion is the norm, churches stand empty, yet religious holidays remain family occasions."},"teaser":{"ar":"كيف تحولت التشيك من بلد يضم أكثر من 90% مسيحيين إلى واحدة من أكثر الدول الأوروبية علمانية؟","de":"Wie wurde aus einem Land mit über 90 Prozent Christen eine der säkularsten Nationen Europas?","en":"How did a country that was over 90% Christian become one of the most secular nations in Europe?"},"readingMinutes":1,"sections":{"ar":[{"heading":"تحول سريع في المشهد الديني","paragraphs":["في تعداد 2021، أعلن 47.8% من التشيك أنهم بلا دين، بينما وصف 21.3% أنفسهم كمؤمنين، ولم يعرّف سوى 11.7% أنفسهم كمسيحيين. هذا التغير جذري مقارنة بالنصف الأول من القرن العشرين، حين كان أكثر من 90% من التشيك مسيحيين، مما يجعله واحداً من أسرع الانهيارات الدينية في أوروبا.","بدأ الانحدار قبل الحقبة الشيوعية (1948-1989) التي عززت الإلحاد وقيّدت الكنائس، لكنه استمر بعد 1989. اليوم، العلمانية حاضرة في الحياة اليومية: كنائس فارغة، حفلات زفاف وجنازات مدنية، والدين أصبح شأناً خاصاً إلى حد كبير."]},{"heading":"عيد الميلاد كعائلة وطعام","paragraphs":["يبقى عيد الميلاد وعيد الفصح مناسبات ثقافية مهمة، لكن بالنسبة لكثير من التشيك هما مناسبتان عائليتان وغذائيتان أكثر منهما دينيتان. عائلة تشيكية تحتفل بعيد الميلاد مع سمك الشبوط والهدايا، وتتجادل حول جدول التلفزيون، ولا أحد يحضر قداساً.","التشيك ليست موحدة في إلحادها: الممارسة الدينية أعلى في مورافيا، وفي بعض المناطق الريفية، وبين مؤمنين يخفون إيمانهم، كما تظهر استطلاعات اهتماماً بالروحانية البديلة. ويختلف ذلك أيضاً بين الأجيال والمناطق، إذ يميل الشباب في المدن إلى العلمانية أكثر من كبار السن في الأرياف."]}],"de":[{"heading":"Ein rascher Wandel der Religiosität","paragraphs":["Beim Zensus 2021 bezeichneten sich 47,8 Prozent der Tschechen als irreligiös, 21,3 Prozent als gläubig und nur 11,7 Prozent als Christen. Dieser Wandel ist dramatisch: In der ersten Hälfte des 20. Jahrhunderts waren über 90 Prozent Christen, was ihn zu einem der schnellsten religiösen Zusammenbrüche Europas macht.","Der Rückgang begann vor der kommunistischen Ära (1948–1989), die Atheismus förderte und Kirchen einschränkte, und setzte sich nach 1989 fort. Säkularismus zeigt sich im Alltag: leere Kirchen, zivile Hochzeiten und Beerdigungen, Religion als Privatsache."]},{"heading":"Weihnachten als Familien- und Essensfest","paragraphs":["Weihnachten und Ostern bleiben wichtige kulturelle Feiertage, sind aber für viele Tschechen eher Familien- und Essensanlässe als religiöse Feste. Eine tschechische Familie feiert Weihnachten mit Karpfen und Geschenken, diskutiert über das Fernsehprogramm, und niemand besucht einen Gottesdienst.","Tschechien ist nicht flächendeckend atheistisch: In Mähren, in manchen ländlichen Gebieten und bei Gläubigen, die ihren Glauben privat halten, ist die religiöse Praxis höher; Umfragen zeigen auch Interesse an alternativer Spiritualität. Zudem variiert die Religiosität zwischen Generationen und Regionen, wobei junge Städter säkularer sind als ältere Menschen auf dem Land."]}],"en":[{"heading":"A rapid shift in religiosity","paragraphs":["In the 2021 census, 47.8% of Czechs declared themselves irreligious, while 21.3% described themselves as believers and only 11.7% identified with Christianity. This is a dramatic change: in the first half of the 20th century more than 90% of Czechs were Christians, making it one of the fastest religious collapses in Europe.","The decline began before the communist period from 1948 to 1989, which promoted atheism and restricted the churches, and it continued after 1989. Secularism is visible in everyday life: empty churches, civil weddings and funerals, and a public culture in which religion is largely a private matter."]},{"heading":"Christmas as a family and food occasion","paragraphs":["Christmas and Easter remain important cultural holidays, but for many Czechs they are family and food occasions rather than religious ones. A Czech family celebrates Christmas with carp and presents, argues about the television schedule, and nobody attends a church service.","Czechia is not uniformly atheist: religious practice is higher in Moravia, in some rural areas and among believers who keep their faith private, and surveys also show interest in alternative spirituality. This also varies by generation and region, with younger city dwellers more secular than older people in the countryside."]}]},"context":{"countries":["CZ"],"region":"Central Europe","continent":"europe","languages":["cs"],"period":"contemporary"},"tags":["beliefs-and-folklore","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Religion in the Czech Republic","de":"Religion in the Czech Republic","en":"Religion in the Czech Republic"},"url":"https://en.wikipedia.org/wiki/Religion_in_the_Czech_Republic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Secularization","de":"Secularization","en":"Secularization"},"url":"https://en.wikipedia.org/wiki/Secularization","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة تشيكية تحتفل بعيد الميلاد مع سمك الشبوط والهدايا، وتتجادل حول جدول التلفزيون، ولا أحد يحضر قداساً.","de":"Eine tschechische Familie feiert Weihnachten mit Karpfen und Geschenken, streitet über das Fernsehprogramm, und niemand geht in die Kirche.","en":"A Czech family celebrates Christmas with carp and presents, argues about the television schedule, and nobody attends a church service."},"misunderstanding":{"ar":"الاعتقاد بأن التشيك بلد ملحد بالكامل: في الواقع، هناك مؤمنون، خاصة في مورافيا والمناطق الريفية، وبعضهم يمارس إيمانه بشكل خاص.","de":"Die Annahme, Tschechien sei vollständig atheistisch: Tatsächlich gibt es Gläubige, besonders in Mähren und ländlichen Gebieten, von denen manche ihren Glauben privat ausüben.","en":"The assumption that Czechia is entirely atheist: in fact, there are believers, especially in Moravia and rural areas, some of whom practice their faith privately."},"comparison":{"ar":"بالمقارنة مع دول أوروبية أخرى، فإن انهيار الدين في التشيك أسرع وأكثر شمولاً، لكن العطلات الدينية ما زالت تحتفظ ببعد ثقافي قوي.","de":"Im Vergleich zu anderen europäischen Ländern verlief der religiöse Niedergang in Tschechien schneller und umfassender, doch religiöse Feiertage behalten eine starke kulturelle Bedeutung.","en":"Compared with other European countries, the religious decline in Czechia has been faster and more comprehensive, yet religious holidays retain strong cultural significance."}},{"id":"eur-055","version":2,"slug":"the-fujara-a-shepherd-s-instrument-that-became-a-national-symbol","contentType":"note","category":"music-and-dance","title":{"ar":"الفيجارا: آلة الراعي التي أصبحت رمزًا","de":"Die Fujara: Hirteninstrument wird Nationalsymbol","en":"The fujara: a shepherd's instrument turned symbol"},"deck":{"ar":"من جبال سلوفاكيا الوسطى، آلة نفخ خشبية طويلة تصنع ألحانًا عميقة وتعيد الحياة إلى تقليد كاد يندثر.","de":"Aus den Bergen der Mittelslowakei stammt eine lange Holzflöte, die tiefe, meditative Melodien spielt und eine fast verlorene Tradition wiederbelebt.","en":"From the mountains of central Slovakia comes a long wooden flute that plays deep, meditative melodies and revives a tradition nearly lost."},"teaser":{"ar":"آلة موسيقية طويلة من سلوفاكيا الوسطى، تعزف ألحانًا تأملية، وتحولت من رفيق الراعي إلى رمز ثقافي معترف به عالميًا.","de":"Ein langes Musikinstrument aus der Mittelslowakei, das meditative Melodien spielt und vom Hirtenbegleiter zum weltweit anerkannten Kultursymbol wurde.","en":"A long wooden flute from central Slovakia, played by shepherds, now a UNESCO-recognised symbol of regional identity and folk revival."},"readingMinutes":1,"sections":{"ar":[{"heading":"آلة من قلب الجبال","paragraphs":["الفيجارا آلة نفخ خشبية طويلة، يتراوح طولها بين 160 و200 سم، وتُضبط على نغمات A أو G أو F. لها ثلاثة ثقوب في الجزء السفلي، وقناة هواء موازية تغذي الفم، مما يمنحها صوتًا عميقًا يشبه الكونتراباص.","نشأت كآلة للرعاة، تُعزف منفردة في الجبال، وتُستخدم لألحان طويلة تأملية مع تنفس إيقاعي. كان الراعي يعزفها في العراء، فتملأ الوادي بصوتها العميق."]},{"heading":"من الرعي إلى المهرجانات","paragraphs":["اليوم، تُعزف موسيقى الفيجارا في المهرجانات الشعبية، وقد اعترفت اليونسكو بها كتراث ثقافي غير مادي. ارتبط إحياء الآلة بحركة الموسيقى الشعبية وبالحرفيين الذين ينحتونها ويزينونها في قرى منطقة بودبولياني.","يختلف حضور الفيجارا بين الأجيال والمناطق: فبعض الشباب في المدن لم يسمعها حية قط، بينما يحافظ كبار السن في القرى على تقليد العزف. هذا التباين يعكس حيوية التراث وقابليته للتغير."]}],"de":[{"heading":"Ein Instrument aus dem Herzen der Berge","paragraphs":["Die Fujara ist eine große Obertonschnabelflöte, typischerweise 160–200 cm lang und in A, G oder F gestimmt. Sie hat drei Tonlöcher im unteren Teil und einen parallelen Luftkanal (vzduchovod), der das Schnabelmundstück speist und einen tiefen, kontrabassartigen Klang erzeugt.","Ursprünglich war sie ein Hirteninstrument, das allein in den Bergen gespielt wurde, für lange, meditative Melodien mit rhythmischem Atmen. Der Hirte spielte im Freien, und der Klang füllte das Tal."]},{"heading":"Vom Weideland zu den Festivals","paragraphs":["Heute wird Fujara-Musik bei Volksfesten aufgeführt und ist von der UNESCO als immaterielles Kulturerbe anerkannt. Die Wiederbelebung des Instruments ist mit der Volksmusikbewegung und mit Herstellern verbunden, die die Flöten in den Dörfern rund um Podpoľanie schnitzen und verzieren.","Die Präsenz der Fujara variiert je nach Region und Generation: Manche Stadtjugendliche haben sie nie live gehört, während ältere Dorfbewohner die Spieltradition bewahren. Diese Unterschiede zeigen, wie lebendig und wandelbar das Erbe ist."]}],"en":[{"heading":"An instrument from the heart of the mountains","paragraphs":["The fujara is a large overtone fipple flute, typically 160–200 cm long and tuned in A, G or F. It has three tone holes on the lower body and a parallel air channel (vzduchovod) that feeds the fipple, giving a deep, contrabass sound.","It originated as a shepherd's instrument, played alone in the mountains for long, meditative melodies with rhythmic breathing. The shepherd played outdoors, and the sound filled the valley."]},{"heading":"From pasture to festival stage","paragraphs":["Today fujara music is performed at folk festivals and has been recognised by UNESCO as intangible cultural heritage. The instrument's revival is associated with the folk-music movement and with makers who carve and decorate the flutes in villages around Podpoľanie.","The fujara's presence varies by region and generation: some urban young people have never heard it live, while older villagers keep the playing tradition alive. This gap shows how heritage stays dynamic and adaptable."]}]},"context":{"countries":["SK"],"region":"Central Europe","continent":"europe","languages":["sk"],"period":"contemporary"},"tags":["music-and-dance","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fujara","de":"Fujara","en":"Fujara"},"url":"https://en.wikipedia.org/wiki/Fujara","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Slovakia","de":"Culture of Slovakia","en":"Culture of Slovakia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Slovakia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مهرجان صيفي، يعزف راعٍ منفردًا على الفيجارا، فيصمت الجمهور؛ اللحن مبني على نغمات طويلة وإيحاءات فوقية بدلًا من الكوردات.","de":"Auf einem Sommerfestival spielt ein Hirte ein Fujara-Solo, und das Publikum verstummt; die Melodie basiert auf langen Tönen und Obertönen statt auf Akkorden.","en":"At a summer festival, a shepherd plays a fujara solo and the audience falls silent; the melody is built on long notes and overtones rather than chords."},"misunderstanding":{"ar":"يظن كثيرون أن الفيجارا آلة وطنية لكل سلوفاكيا، لكنها في الواقع إقليمية تنتمي إلى سلوفاكيا الوسطى، وكثير من السلوفاك لم يروها تُعزف مباشرة.","de":"Viele halten die Fujara für ein nationales Instrument aller Slowaken, doch sie ist regional: Sie gehört zur Mittelslowakei, und viele Slowaken haben sie noch nie live gehört.","en":"Many assume the fujara is a national instrument for all Slovaks, but it is regional: it belongs to central Slovakia, and many Slovaks have never seen one played live."},"comparison":{"ar":"مثل آلة الديدجيريدو الأسترالية من حيث الصدى العميق والإيحاءات، لكن الفيجارا تصنع ألحانًا تأملية أكثر منها إيقاعية.","de":"Ähnlich dem australischen Didgeridoo in ihrem tiefen Dröhnen und den Obertönen, doch die Fujara erzeugt eher meditative Melodien als rhythmische Muster.","en":"Like the Australian didgeridoo in its deep drone and overtones, but the fujara produces more meditative melodies than rhythmic patterns."}},{"id":"eur-056","version":2,"slug":"hungarian-names-put-the-family-before-the-person","contentType":"language","category":"languages","title":{"ar":"في المجر، العائلة تسبق الاسم الشخصي","de":"In Ungarn steht die Familie vor dem Vornamen","en":"In Hungary, the family comes before the person"},"deck":{"ar":"ترتيب الاسم المجري يضع اسم العائلة أولاً في الكلام والكتابة، وهو اختلاف بسيط يربك الزائر قبل أن يفهم منطقه.","de":"Die ungarische Namensordnung stellt den Familiennamen in Sprache und Schrift voran – eine kleine Abweichung, die Besucher zuerst verwirrt.","en":"Hungarian name order puts the family name first in speech and writing, a small difference that unsettles visitors before they grasp its logic."},"teaser":{"ar":"في المجر يُكتب اسم العائلة قبل الاسم الشخصي، فتتغير طريقة قراءة الأسماء في الوثائق والملصقات والمحادثات اليومية.","de":"In Ungarn steht der Familienname zuerst, in Dokumenten, auf Schildern und im Gespräch. Das verändert, wie Namen gelesen und ausgesprochen werden.","en":"In Hungary the family name comes first on passports, badges and in conversation. That changes how names are read aloud and remembered."},"readingMinutes":1,"sections":{"ar":[{"heading":"اسم العائلة أولاً","paragraphs":["في المجر يأتي اسم العائلة أولاً في الكلام والكتابة معاً، فيُقال «فاركاس بيرتالان» لا «بيرتالان فاركاس»، وهو ترتيب شرقي نادر في أوروبا.","تشارك المجرية في هذا الترتيب لغاتٍ خارج القارة كالصينية واليابانية والكورية والفيتنامية، وبعض الاستخدام الباسكي، وهذا ما يجعلها استثناءً أوروبياً لافتاً.","يُعكس الترتيب عند الكتابة عن المجريين بلغات غربية، فيظهر الاسم الشخصي أولاً، وهذا ما يحيّر الزائر الذي يقرأ الاسم نفسه بصيغتين."]},{"heading":"الوثائق والحياة اليومية","paragraphs":["تكتب التواريخ المجرية بالسنة ثم الشهر ثم اليوم، وتتبع الوثائق الرسمية النمط نفسه، فيتعلم الناس قراءة الزمن كما يقرأون الأسماء.","تقليدياً حملت المرأة المتزوجة لاحقة «-نِه» ملحقة باسم الزوج، وفي قانون عام 2022 صار لها اختيار أوسع في اسم الزواج.","يختلف الأمر بين الأجيال والمناطق: فالشباب في المدن يعدّلون أسماءهم بسهولة للجمهور الأجنبي، بينما يتمسك كثيرون في القرى بالصيغة المحلية الكاملة."]}],"de":[{"heading":"Der Familienname zuerst","paragraphs":["In Ungarn steht der Familienname sowohl in der Rede als auch in der Schrift vorn: Es heißt „Farkas Bertalan“, nicht „Bertalan Farkas“ – eine in Europa seltene östliche Ordnung.","Ungarisch teilt diese Reihenfolge mit Sprachen außerhalb Europas wie Chinesisch, Japanisch, Koreanisch und Vietnamesisch sowie mit manchem baskischen Gebrauch.","Wird über Ungarn in westlichen Sprachen geschrieben, kehrt sich die Reihenfolge um; derselbe Name erscheint dann in zwei Formen und verwirrt Gäste."]},{"heading":"Dokumente und Alltag","paragraphs":["Ungarische Daten werden Jahr-Monat-Tag geschrieben, und amtliche Dokumente folgen demselben Muster, sodass man die Zeit wie die Namen liest.","Verheiratete Frauen trugen traditionell die Endung „-né“ am Namen des Mannes; ein Gesetz von 2022 erlaubt eine breitere Wahl des Ehenamens.","Regional und generationell zeigt sich Variation: Jüngere in Städten passen ihre Namen für fremde Ohren leichter an, während viele auf dem Land die vollständige heimische Form behalten."]}],"en":[{"heading":"Family name first","paragraphs":["Hungarian puts the family name first in both speech and writing, so the physicist is “Farkas Bertalan”, not “Bertalan Farkas” – an eastern order rare in Europe.","Hungarian shares this order with languages outside Europe such as Chinese, Japanese, Korean and Vietnamese, and with some Basque nationalist usage.","The order reverses when Hungarians are written about in Western-order languages, so the same person appears in two forms and visitors hesitate."]},{"heading":"Documents and daily life","paragraphs":["Hungarian dates run year-month-day, and formal documents follow the same pattern, so people read time the way they read names.","Married women traditionally took the suffix “-né” on the husband’s name, and a 2022 law allows a wider choice of married names.","Usage varies by region and generation: younger people in cities adapt their names more readily for foreign audiences, while many in villages keep the full home form."]}]},"context":{"countries":["HU"],"region":"Central Europe","continent":"europe","languages":["hu"],"period":"contemporary"},"tags":["languages","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hungarian name","de":"Hungarian name","en":"Hungarian name"},"url":"https://en.wikipedia.org/wiki/Hungarian_name","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hungarian language","de":"Hungarian language","en":"Hungarian language"},"url":"https://en.wikipedia.org/wiki/Hungarian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جواز سفر مجري يُكتب «ناجي أنّا»، وعلى شارة مؤتمر بالإنجليزية يُطبع «أنّا ناجي»؛ اسم العائلة واحد، لكن العُرف معكوس.","de":"Im ungarischen Reisepass steht „Nagy Anna“, auf dem englischen Konferenzschild „Anna Nagy“; der Familienname bleibt gleich, die Konvention kehrt sich um.","en":"A Hungarian passport lists “Nagy Anna”, and an English-language conference badge prints “Anna Nagy”; the family name is the same, but the convention is reversed."},"misunderstanding":{"ar":"يعتقد بعض الزوار أن الاسم الأخير هو الاسم الشخصي، فينادون الشخص باسم عائلته، وهو خطأ شائع عند أول لقاء.","de":"Manche Besucher halten den letzten Namen für den Vornamen und sprechen die Person mit dem Familiennamen an – ein häufiger Fehler beim ersten Treffen.","en":"Some visitors assume the last name is the given name and address the person by their family name – a common slip at a first meeting."},"comparison":{"ar":"يشبه هذا الترتيب ما نجده في الصينية واليابانية، بينما تعتمد معظم اللغات الأوروبية ترتيب الاسم الشخصي أولاً.","de":"Ähnlich ist es im Chinesischen und Japanischen, während die meisten europäischen Sprachen den Vornamen voranstellen.","en":"It resembles Chinese and Japanese practice, while most European languages put the given name first."},"expression":{"original":"Kovács János","language":"Magyar","gloss":{"ar":"فلان الفلاني، مكتوباً باسم العائلة أولاً","de":"Max Mustermann, mit Familienname zuerst","en":"John Smith, written family-name-first"},"usage":{"ar":"يُقرأ هكذا في الوثائق المجرية، ويُعكس الترتيب في المراسلات الأجنبية.","de":"So liest man es in ungarischen Dokumenten; in fremdsprachiger Post wird die Reihenfolge umgedreht.","en":"Read this way in Hungarian documents; the order flips in foreign correspondence."},"transliteration":"Kovács János"}},{"id":"eur-057","version":2,"slug":"martisor-march-begins-with-a-red-and-white-thread","contentType":"note","category":"traditions","title":{"ar":"مارتيسور: خيط أحمر وأبيض يعلن الربيع","de":"Mărțișor: Der Frühling beginnt mit rot-weißem Faden","en":"Mărțișor: March begins with a red-and-white thread"},"deck":{"ar":"في رومانيا ومولدوفا، يبدأ شهر مارس بتبادل تعويذة صغيرة مربوطة بخيوط حمراء وبيضاء، تحمل معاني الحيوية والنقاء.","de":"In Rumänien und Moldau läutet der 1. März eine Tradition ein, bei der ein kleines Amulett mit rot-weißen Fäden Vitalität und Reinheit symbolisiert.","en":"In Romania and Moldova, 1 March brings a small token tied with red and white strings, symbolizing vitality and purity as spring arrives."},"teaser":{"ar":"تقليد مارتيسور يجمع بين أسطورة رومانية وقدوم الربيع، حيث يهدي الرجال النساء تعويذة صغيرة تعلق على الملابس طوال الشهر.","de":"Mărțișor ist mehr als ein Frühlingsgruß: Frauen und Mädchen erhalten ein kleines Geschenk, das sie den ganzen März über an ihrer Kleidung tragen.","en":"Mărțișor is a spring tradition where women and girls receive a small gift pinned to their clothing, carrying wishes for health and renewal."},"readingMinutes":1,"sections":{"ar":[{"heading":"أصل التسمية والمعنى","paragraphs":["كلمة مارتيسور هي تصغير لكلمة مارتس، الاسم الشعبي القديم لشهر مارس، وتعني حرفيًا 'مارس الصغير'. ترتبط العادة باحتفالات رأس السنة الرومانية في الأول من مارس وبقدوم الربيع.","يرمز الخيط الأحمر إلى الحيوية، بينما يرمز الأبيض إلى النقاء أو الثلج. في الممارسة الحديثة، تتلقى النساء والفتيات المارتيسور ويرتدينه مثبتًا على ملابسهن خلال الجزء الأول من مارس."]},{"heading":"تقاليد حية عبر الحدود","paragraphs":["في الأول من مارس، يهدي الجد الروماني حفيدته حذوة حصان صغيرة من الفضة مربوطة بخيط أحمر وأبيض، فتدبسها على معطفها. هذا المشهد يتكرر في مولدوفا أيضًا، حيث يشترك التقليد في جذور متشابهة.","أدرجت اليونسكو هذا التقليد في قائمة التراث الثقافي غير المادي عام 2017، بالاشتراك مع تقليد مارتينيتسا البلغاري والممارسات المشابهة في مقدونيا الشمالية ومولدوفا. يختلف شكل التقليد ومعناه حسب المنطقة والعائلة، كما تتباين ممارسته بين الأجيال."]}],"de":[{"heading":"Name und Bedeutung","paragraphs":["Das Wort Mărțișor ist die Verkleinerungsform von marț, einem alten volkstümlichen Namen für den März, und bedeutet wörtlich 'kleiner März'. Der Brauch ist mit den römischen Neujahrsfeiern am 1. März und dem Frühlingsanfang verbunden.","Der rote Faden steht für Lebenskraft, der weiße für Reinheit oder Schnee. In der modernen Praxis erhalten Frauen und Mädchen den Mărțișor und tragen ihn im ersten Teil des März an der Kleidung."]},{"heading":"Gelebte Tradition über Grenzen hinweg","paragraphs":["Am 1. März schenkt ein rumänischer Großvater seiner Enkelin ein kleines silbernes Hufeisen, das mit rot-weißem Faden gebunden ist, und sie steckt es an ihren Mantel. Ähnliche Szenen spielen sich auch in Moldau ab, wo der Brauch verwandte Wurzeln hat.","2017 wurde die Tradition in die UNESCO-Liste des immateriellen Kulturerbes aufgenommen, gemeinsam mit der bulgarischen Martenitsa und verwandten Praktiken in Nordmazedonien und Moldau. Form und Bedeutung variieren je nach Region und Familie sowie zwischen den Generationen."]}],"en":[{"heading":"The name and its meaning","paragraphs":["The word Mărțișor is the diminutive of marț, an old folk name for March, and literally means 'little March'. The custom is linked to Roman New Year celebrations on 1 March and to the arrival of spring.","The red thread stands for vitality and the white for purity or snow. In modern practice, women and girls receive the mărțișor and wear it pinned to clothing during the first part of March."]},{"heading":"A living tradition across borders","paragraphs":["On 1 March a Romanian grandfather gives his granddaughter a small silver horseshoe tied with red and white thread, and she pins it to her coat. Similar scenes unfold in Moldova, where the custom shares related roots.","The tradition was inscribed on UNESCO's Intangible Cultural Heritage list in 2017, jointly with the similar Bulgarian martenitsa and related practices in North Macedonia and Moldova. Its form and meaning vary by region and family, and between generations."]}]},"context":{"countries":["RO"],"region":"Eastern Europe","continent":"europe","languages":["ro"],"period":"contemporary"},"tags":["traditions","Eastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Mărțișor","de":"Mărțișor","en":"Mărțișor"},"url":"https://en.wikipedia.org/wiki/M%C4%83r%C8%9Bi%C8%99or","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Romania","de":"Culture of Romania","en":"Culture of Romania"},"url":"https://en.wikipedia.org/wiki/Culture_of_Romania","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الأول من مارس، يهدي الجد الروماني حفيدته حذوة حصان صغيرة من الفضة مربوطة بخيط أحمر وأبيض، فتدبسها على معطفها.","de":"Am 1. März schenkt ein rumänischer Großvater seiner Enkelin ein kleines silbernes Hufeisen, das mit rot-weißem Faden gebunden ist, und sie steckt es an ihren Mantel.","en":"On 1 March a Romanian grandfather gives his granddaughter a small silver horseshoe tied with red and white thread, and she pins it to her coat."},"misunderstanding":{"ar":"يعتقد البعض أن المارتيسور مجرد زينة موسمية، لكنه في الواقع تعويذة رمزية تحمل دلالات الحيوية والنقاء وتُعد جزءًا من الهوية الثقافية.","de":"Manche halten den Mărțișor für rein dekorativ, doch er ist ein symbolisches Amulett mit Bedeutung für Lebenskraft und Reinheit.","en":"Some think the mărțișor is just a seasonal decoration, but it is a symbolic token with meanings of vitality and purity."},"comparison":{"ar":"يشبه المارتيسور تقليد مارتينيتسا البلغاري، وكلاهما مرتبط بعادات الربيع في البلقان، لكن لكل منهما تفاصيله المحلية.","de":"Der Mărțișor ähnelt der bulgarischen Martenitsa; beide gehören zu den Frühlingsbräuchen des Balkans, haben aber eigene lokale Ausprägungen.","en":"Mărțișor is closely related to the Bulgarian martenitsa; both are Balkan spring customs, each with its own local variations."}},{"id":"eur-058","version":2,"slug":"baba-marta-and-the-martenitsa-ritual-of-march","contentType":"note","category":"traditions","title":{"ar":"بابا مارتا: عيد الربيع في بلغاريا","de":"Baba Marta: Frühlingsbeginn in Bulgarien","en":"Baba Marta and the Martenitsa of March"},"deck":{"ar":"في الأول من مارس، يتبادل البلغاريون مارتينيتسا، خيوطاً حمراء وبيضاء، احتفالاً بنهاية الشتاء.","de":"Am 1. März tauschen Bulgarinnen und Bulgaren Martenitsi aus, rot-weiße Wollfäden, die den Winter verabschieden.","en":"On 1 March Bulgarians exchange red-and-white yarn tokens called martenitsi, marking winter's end and spring's beginning."},"teaser":{"ar":"بابا مارتا، الجدة مارس، تجلب الربيع. تعرّف على طقس المارتينيتسا وكيف يعلّق البلغاريون هذه التمائم حتى يرون اللقلق.","de":"Baba Marta, die „Oma März“, bringt den Frühling. Erfahren Sie, wie die Martenitsa getragen wird, bis der erste Storch gesichtet wird.","en":"Baba Marta, or Granny March, heralds spring. Discover how the martenitsa is worn until a stork or blossoming tree appears."},"readingMinutes":1,"sections":{"ar":[{"heading":"بابا مارتا والمارتينيتسا","paragraphs":["بابا مارتا هي شخصية أسطورية بلغارية تجلب نهاية الشتاء وبداية الربيع، ويُحتفل بها في الأول من مارس. في ذلك اليوم، يتبادل البلغاريون ويwearون مارتينيتسي: زخارف صغيرة من خيوط الصوف الحمراء والبيضاء، غالباً على شكل دميتين، بيزو (الأبيض) وبيندا (الأحمر).","العادة قديمة جداً وتعود إلى ما قبل المسيحية، مع تنويعات إقليمية في جميع أنحاء بلغاريا. في عام 2017، أدرجت اليونسكو الممارسات الثقافية المرتبطة بالأول من مارس في بلغاريا ومقدونيا الشمالية ومولدوفا ورومانيا."]},{"heading":"من التعليق إلى التمني","paragraphs":["يُعلق المارتينيتسا حتى يرى مرتديها لقلقاً أو سنونو أو شجرة مزهرة، ثم يربطها بشجرة فاكهة أو يضعها تحت حجر للعب لعبة التنبؤ بالمستقبل. يختلف مدى الالتزام بالعادة بين العائلات؛ ففي المدن غالباً ما تُتبادل المارتينيتسا كهدية صغيرة بدلاً من أن تُعاش كطقس تقويمي."]}],"de":[{"heading":"Baba Marta und die Martenitsa","paragraphs":["Baba Marta ist eine bulgarische mythologische Figur, die das Ende des Winters und den Beginn des Frühlings bringt und am 1. März gefeiert wird. An diesem Tag tauschen Bulgarinnen und Bulgaren Martenitsi aus und tragen sie: kleine rot-weiße Wollverzierungen, oft in Form zweier Puppen, Pizho (weiß) und Penda (rot).","Der Brauch ist sehr alt und vorchristlichen Ursprungs, mit regionalen Varianten in ganz Bulgarien. Im Jahr 2017 hat die UNESCO die verwandten kulturellen Praktiken des 1. März in Bulgarien, Nordmazedonien, Moldau und Rumänien eingetragen."]},{"heading":"Vom Tragen zum Wünschen","paragraphs":["Die Martenitsa wird getragen, bis der Träger einen Storch, eine Schwalbe oder einen blühenden Baum sieht; dann wird sie an einen Obstbaum gebunden oder unter einen Stein gelegt, um ein Wahrsagespiel zu spielen. Die Intensität der Ausübung variiert je nach Familie; in Städten wird die Martenitsa oft als kleines Geschenk ausgetauscht, statt als Kalenderritual gelebt zu werden."]}],"en":[{"heading":"Baba Marta and the Martenitsa","paragraphs":["Baba Marta ('Granny March') is a Bulgarian mythical figure who brings the end of winter and the beginning of spring, celebrated on 1 March. On that day Bulgarians exchange and wear martenitsi: small red-and-white yarn ornaments, often in the shape of two dolls, Pizho (white) and Penda (red).","The custom is very old and pre-Christian in origin, with regional variants across Bulgaria. In 2017 UNESCO inscribed the related cultural practices of 1 March in Bulgaria, North Macedonia, Moldova and Romania."]},{"heading":"From Wearing to Wishing","paragraphs":["The martenitsa is worn until the wearer sees a stork, a swallow or a blossoming tree, then tied to a fruit tree or placed under a stone for a fortune-telling game. Observance varies between families; in cities the martenitsa is often exchanged as a small gift rather than lived as a calendar ritual."]}]},"context":{"countries":["BG"],"region":"Southeastern Europe","continent":"europe","languages":["bg"],"period":"contemporary"},"tags":["traditions","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Baba Marta","de":"Baba Marta","en":"Baba Marta"},"url":"https://en.wikipedia.org/wiki/Baba_Marta","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Martenitsa","de":"Martenitsa","en":"Martenitsa"},"url":"https://en.wikipedia.org/wiki/Martenitsa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الأول من مارس، تُعطي الجدة لطفل بلغاري دمية صغيرة منسوجة باللونين الأحمر والأبيض، فيرتديها على معصمه حتى يرى أول لقلق.","de":"Am 1. März schenkt eine Großmutter einem bulgarischen Kind eine gewebte rot-weiße Puppe, die es am Handgelenk trägt, bis der erste Storch gesichtet wird.","en":"On 1 March a Bulgarian child is given a woven red-and-white doll by a grandparent and wears it on the wrist until the first stork is spotted."},"misunderstanding":{"ar":"بابا مارتا هي شخصية شعبية وليست قديسة دينية، والاحتفال يختلف بين العائلات؛ ففي المدن غالباً ما تُتبادل المارتينيتسا كهدية صغيرة بدلاً من أن تُعاش كطقس تقويمي.","de":"Baba Marta ist eine Volksfigur, keine religiöse Heilige, und die Beachtung variiert von Familie zu Familie; in Städten wird die Martenitsa oft als kleines Geschenk ausgetauscht, statt als Kalenderritual gelebt zu werden.","en":"Baba Marta is a folk figure, not a religious saint, and observance varies between families; in cities the martenitsa is often exchanged as a small gift rather than lived as a calendar ritual."},"comparison":{"ar":"بينما ترتبط المارتينيتسا في بلغاريا ببابا مارتا، فإن الممارسات المشابهة في مقدونيا الشمالية ومولدوفا ورومانيا تشترك في تقليد الأول من مارس ولكن مع اختلافات محلية في الرموز والتقاليد.","de":"Während die Martenitsa in Bulgarien mit Baba Marta verbunden ist, teilen ähnliche Bräuche in Nordmazedonien, Moldau und Rumänien die Tradition des 1. März, jedoch mit lokalen Unterschieden in Symbolik und Brauchtum.","en":"While the martenitsa in Bulgaria is tied to Baba Marta, similar practices in North Macedonia, Moldova and Romania share the 1 March tradition but differ in local symbols and customs."}},{"id":"eur-059","version":2,"slug":"the-vyshyvanka-as-an-everyday-national-statement","contentType":"note","category":"clothing-and-design","title":{"ar":"فِيشيفانكا: قميص مطرّز يحكي هوية","de":"Die Vyshyvanka als alltägliches Bekenntnis","en":"The vyshyvanka as an everyday national statement"},"deck":{"ar":"من ثوب القرية إلى رمز وطني يرتديه الناس في العمل والمدرسة، يحمل القميص المطرّز الأوكراني حكايات العائلات والمناطق.","de":"Vom Dorfgewand zum nationalen Zeichen: Das bestickte Hemd trägt Geschichten von Familien und Regionen bis in Büro und Klassenzimmer.","en":"From village dress to national symbol, the embroidered shirt carries family and regional stories into offices and classrooms."},"teaser":{"ar":"في أوكرانيا، القميص المطرّز ليس مجرد لباس؛ إنه علامة انتماء تتجدّد كل ربيع في يوم خاص.","de":"In der Ukraine ist das bestickte Hemd mehr als Kleidung – ein Zeichen der Zugehörigkeit, das jedes Frühjahr neu getragen wird.","en":"In Ukraine the embroidered shirt is more than clothing: it is a sign of belonging, renewed each spring on a dedicated day."},"readingMinutes":1,"sections":{"ar":[{"heading":"من القرية إلى الشارع","paragraphs":["الفِيشيفانكا قميص مطرّز في الزي الوطني الأوكراني والبيلاروسي، وتتمايز أنماط تطريزه بحسب المناطق والعائلات.","انتقل القميص من لباس القرية إلى رمز وطني؛ فقد ارتداه الكتّاب والمعارضون في العهد السوفييتي، ثم أصبح رمزًا جماهيريًا خلال الثورة البرتقالية عام 2004 وبعد عام 2014.","تختلف التفاصيل بين الأجيال والمناطق: قد يختار الشاب نمطًا مبسّطًا بينما تتمسك الجدة بنقوش قريتها."]},{"heading":"يوم يُلبَس فيه الانتماء","paragraphs":["بدأ يوم الفِيشيفانكا عام 2006، ويُحتفل به في الخميس الثالث من مايو، حين يرتدي الناس القمصان المطرّزة في العمل والمدرسة.","النقوش ليست زينة فقط؛ فزخارف البلوط والعنب والديكة والأشكال الهندسية تحمل معاني رمزية، وتتنوّع الألوان حسب المنطقة.","بعد الغزو الروسي عام 2022، أصبح القميص علامة بارزة على الهوية داخل البلاد وفي المهجر."]}],"de":[{"heading":"Vom Dorf auf die Straße","paragraphs":["Eine Vyshyvanka ist ein besticktes Hemd der ukrainischen und belarussischen Nationaltracht; in der Ukraine sind die Stickmuster regional und familiär geprägt.","Das Hemd wanderte vom Dorfgewand zum nationalen Symbol: Schriftsteller und Dissidenten trugen es in der Sowjetzeit, massenhaft verbreitet wurde es während der Orangen Revolution 2004 und nach 2014.","Die Details unterscheiden sich nach Region und Generation: Jüngere wählen oft schlichtere Muster, während die Großmutter an den Stickereien ihres Dorfes festhält."]},{"heading":"Ein Tag zum Tragen","paragraphs":["Der Tag der Vyshyvanka wurde 2006 ins Leben gerufen und wird am dritten Donnerstag im Mai begangen, wenn Menschen bestickte Hemden bei der Arbeit und in der Schule tragen.","Die Muster sind nicht bloß Schmuck: Eiche, Trauben, Hähne und geometrische Formen tragen symbolische Bedeutungen, und die Farbwahl variiert je nach Region.","Nach dem russischen Einfall 2022 wurde die Vyshyvanka im Inland und in der Diaspora zu einem auffälligen Zeichen der Identität."]}],"en":[{"heading":"From village dress to the street","paragraphs":["A vyshyvanka is an embroidered shirt in Ukrainian and Belarusian national costume, and in Ukraine the embroidery patterns are specific to regions and families.","The shirt moved from village dress to national symbol: writers and dissidents wore embroidered shirts in the Soviet era, and it became a mass symbol during the 2004 Orange Revolution and after 2014.","Details shift across regions and generations: a younger wearer may choose a pared-back pattern while a grandmother keeps the stitches of her own village."]},{"heading":"A day for wearing it","paragraphs":["Vyshyvanka Day, started in 2006, is marked on the third Thursday of May, when people wear embroidered shirts to work and school.","The patterns are not merely decorative: motifs of oak, grapes, roosters and geometric forms carry symbolic meanings, and colour choices vary by region.","After the 2022 Russian invasion, the vyshyvanka became a conspicuous sign of identity at home and in the diaspora."]}]},"context":{"countries":["UA"],"region":"Eastern Europe","continent":"europe","languages":["uk"],"period":"contemporary"},"tags":["clothing-and-design","Eastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Vyshyvanka","de":"Vyshyvanka","en":"Vyshyvanka"},"url":"https://en.wikipedia.org/wiki/Vyshyvanka","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Ukraine","de":"Culture of Ukraine","en":"Culture of Ukraine"},"url":"https://en.wikipedia.org/wiki/Culture_of_Ukraine","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في يوم الفِيشيفانكا يمتلئ مكتب في كييف بزملاء يرتدون قمصانًا مطرّزة، ويعير جدٌّ حفيده قميصًا طرّزته أمّه بنفسها.","de":"Am Tag der Vyshyvanka füllt sich ein Kiewer Büro mit Kolleginnen und Kollegen in bestickten Hemden, und ein Großvater leiht seinem Enkel ein Hemd, das seine eigene Mutter bestickt hat.","en":"On Vyshyvanka Day a Kyiv office fills with colleagues in embroidered shirts, and a grandfather lends his grandson a shirt embroidered by his own mother."},"misunderstanding":{"ar":"يُظنّ أن القميص زيّ تراثي جامد، لكنه لباس حيّ بأنماط إقليمية كثيرة، واستخدامه الرمزي الحالي حديث وذو طابع سياسي.","de":"Man hält das Hemd oft für ein starres Traditionsstück, doch es ist ein lebendiges Kleidungsstück mit vielen regionalen Stilen; seine heutige symbolische Nutzung ist modern und politisch.","en":"The shirt is often mistaken for a fixed piece of heritage, yet it is a living garment with many regional styles, and its current symbolic use is modern and politicised."},"comparison":{"ar":"لا يملك كل الأوكرانيين قميصًا مطرّزًا أو يرتدونه، وقد عرف العهد السوفييتي كبتًا للتقاليد وتسويقًا لها في الوقت نفسه.","de":"Nicht alle Ukrainerinnen und Ukrainer besitzen oder tragen eine Vyshyvanka, und die Sowjetzeit hat die Tradition zugleich unterdrückt und vermarktet.","en":"Not all Ukrainians own or wear one, and the Soviet period both suppressed and commercialised the tradition."}},{"id":"eur-060","version":2,"slug":"the-dacha-russia-s-weekend-second-life","contentType":"note","category":"everyday-life","title":{"ar":"الداشا: الحياة الثانية في عطلة نهاية الأسبوع","de":"Die Datscha: Russlands zweites Leben am Wochenende","en":"The dacha: Russia's weekend second life"},"deck":{"ar":"في روسيا، الداشا ليست مجرد منزل ريفي، بل عالم اجتماعي واقتصادي متجذر في تاريخ البلاد.","de":"Die Datscha ist weit mehr als ein Sommerhaus – sie ist eine soziale und wirtschaftliche Welt mit tiefen historischen Wurzeln.","en":"The dacha is more than a country home – it is a social and economic world rooted in Russian history."},"teaser":{"ar":"من منح القياصرة إلى توزيع السوفييت، تحولت الداشا إلى ظاهرة جماعية يعيشها الملايين كل صيف.","de":"Von der Zarenschenkung zur sowjetischen Massenerscheinung: Millionen verbringen ihren Sommer auf der Datscha.","en":"From tsarist land grants to Soviet mass distribution, millions of Russians spend their summers at the dacha."},"readingMinutes":1,"sections":{"ar":[{"heading":"منحة من القيصر إلى ظاهرة جماعية","paragraphs":["كلمة داشا تأتي من الفعل الروسي davat أي 'يعطي'، وكانت تشير أصلاً إلى الأرض التي يمنحها القيصر لنبلائه. في العهد السوفييتي، وزعت السلطات المحلية والمؤسسات قطع الأرض والبيوت البسيطة على المواطنين، فأصبحت الداشا ظاهرة جماعية.","كانت قطعة الأرض السوفييتية النموذجية ستة sotki أي 600 متر مربع، ولا تزال العديد من المستوطنات تحتفظ بإمداد مائي جماعي وروح الجيرة القوية."]},{"heading":"حياة اجتماعية بين الخضروات والجيران","paragraphs":["يقضي الداشنيكي عطلات نهاية الأسبوع والصيف في زراعة الخضروات والتوت والزهور، والداشا بقدر ما هي ممتلكات هي عالم اجتماعي. في مساء الجمعة، تأخذ عائلة موسكوية القطار إلى منزل خشبي بحديقة خضروات، حيث تعيش الجدة منذ مايو.","يختلف الأمر حسب المنطقة والجيل: بعض الداشا منازل فاخرة، وبعضها أكواخ خشبية صغيرة، والشباب الروس يستخدمونها أكثر للترفيه من إنتاج الغذاء. صورة الستة sotki هي القاعدة السوفييتية، وليست الواقع الحالي."]}],"de":[{"heading":"Vom Zarengeschenk zum Massenphänomen","paragraphs":["Das Wort Datscha stammt vom russischen Verb davat („geben“) und bezeichnete ursprünglich Land, das der Zar seinen Adligen zuteilte. In der Sowjetzeit verteilten lokale Behörden und Betriebe Datschas und Parzellen an Bürger, und das kleine Grundstück mit einfachem Haus wurde zum Massenphänomen.","Das typische sowjetische Datscha-Grundstück umfasste sechs Sotki (600 Quadratmeter), und viele Siedlungen haben noch heute eine gemeinsame Wasserversorgung und ein starkes Gefühl der Nachbarschaft."]},{"heading":"Soziales Leben zwischen Gemüse und Nachbarn","paragraphs":["Datschniki verbringen Wochenenden und Sommer mit dem Anbau von Gemüse, Beeren und Blumen, und die Datscha ist ebenso eine soziale Welt wie ein Grundstück. Am Freitagabend nimmt eine Moskauer Familie den Vorortzug zu einem Holzhaus mit Gemüsegarten, in dem die Großmutter seit Mai lebt.","Je nach Region und Generation unterscheidet sich die Datscha: Manche sind Luxushäuser, andere winzige Holzhütten, und jüngere Russen nutzen sie zunehmend zur Erholung statt zur Nahrungsproduktion. Das Bild der sechs Sotki ist die sowjetische Norm, nicht die heutige Realität."]}],"en":[{"heading":"From tsarist gift to mass phenomenon","paragraphs":["The word dacha comes from the Russian verb davat ('to give') and originally referred to land allotted by the tsar to his nobles. In the Soviet period, local authorities and enterprises distributed dachas and allotment plots to citizens, and the small plot with a simple house became a mass phenomenon.","The typical Soviet dacha plot was six sotki (600 square metres), and many settlements still have a collective water supply and a strong sense of neighbourliness."]},{"heading":"Social life among vegetables and neighbours","paragraphs":["Dachniki spend weekends and summers growing vegetables, berries and flowers, and the dacha is as much a social world as a property. On Friday evening a Moscow family takes the suburban train to a wooden house with a vegetable patch, where the grandmother has been living since May.","The dacha varies by region and generation: some are luxury houses, some are tiny wooden huts, and younger Russians increasingly use them for leisure rather than food production. The six-sotki image is the Soviet norm, not the current reality."]}]},"context":{"countries":["RU"],"region":"Eastern Europe","continent":"europe","languages":["ru"],"period":"contemporary"},"tags":["everyday-life","Eastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Dacha","de":"Dacha","en":"Dacha"},"url":"https://en.wikipedia.org/wiki/Dacha","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Allotment (gardening)","de":"Allotment (gardening)","en":"Allotment (gardening)"},"url":"https://en.wikipedia.org/wiki/Allotment_(gardening)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مساء الجمعة، تأخذ عائلة موسكوية القطار إلى منزل خشبي بحديقة خضروات، حيث تعيش الجدة منذ مايو.","de":"Am Freitagabend nimmt eine Moskauer Familie den Vorortzug zu einem Holzhaus mit Gemüsegarten, in dem die Großmutter seit Mai lebt.","en":"On Friday evening a Moscow family takes the suburban train to a wooden house with a vegetable patch, where the grandmother has been living since May."},"misunderstanding":{"ar":"يظن البعض أن الداشا مجرد منزل صيفي للترفيه، لكنها في الواقع كانت ولا تزال وسيلة لإنتاج الغذاء وبناء العلاقات الاجتماعية.","de":"Viele halten die Datscha für ein reines Freizeithaus, doch tatsächlich diente und dient sie der Nahrungsproduktion und dem sozialen Austausch.","en":"Many assume the dacha is just a leisure home, but in reality it has been a place for food production and social connection."},"comparison":{"ar":"على عكس المنازل الريفية في الغرب التي تُستخدم غالباً للعطلات فقط، تجمع الداشا بين الإنتاج الزراعي والحياة الاجتماعية والانتماء العائلي.","de":"Anders als westliche Landhäuser, die oft nur als Feriendomizil dienen, verbindet die Datscha Gartenarbeit, soziales Leben und familiäre Bindung.","en":"Unlike Western country cottages often used only for holidays, the dacha combines gardening, social life and family ties."}},{"id":"eur-061","version":2,"slug":"the-russian-anekdot-and-the-habit-of-political-irony","contentType":"note","category":"regional-humour","title":{"ar":"حكاية الأناكدوت الروسي وسخرية السياسة","de":"Der russische Anekdot und politische Ironie","en":"The Russian anekdot and political irony"},"deck":{"ar":"نكات قصيرة تُروى في المطابخ وعلى الهاتف، تحوّل النقص والرقابة إلى ضحك مشترك بين الأصدقاء.","de":"Kurze Witze, erzählt in Küchen und am Telefon, verwandeln Mangel und Zensur in gemeinsames Lachen unter Freunden.","en":"Short jokes told in kitchens and on the phone turn shortage and censorship into shared laughter among friends."},"teaser":{"ar":"في روسيا، الأناكدوت حكاية قصيرة بشخصيات ثابتة ونهاية مفاجئة، عاشت في المطابخ أيام الاتحاد السوفيتي وما زالت تتنفس على الإنترنت.","de":"In Russland ist der Anekdot eine kurze Geschichte mit festen Figuren und einer Pointe; er lebte in sowjetischen Küchen und atmet heute im Internet weiter.","en":"In Russia the anekdot is a short tale with fixed characters and a punchline; it lived in Soviet kitchens and still breathes on the internet today."},"readingMinutes":1,"sections":{"ar":[{"heading":"حكاية قصيرة بشخصيات معروفة","paragraphs":["الأناكدوت الروسي حكاية قصيرة أو حوار خيالي ينتهي بمفاجأة، ويقوم على أماكن ثابتة وشخصيات متكررة يعرفها المستمع قبل أن يبدأ الكلام.","من هذه الشخصيات فوفوتشكا التلميذ، وشعب التشوكشي في الشمال الذي يُقدَّم كغريب ساذج، وراديو أرمينيا، وأزواج وزوجات وحمَوات من الحياة اليومية.","تختلف النكات بين الأجيال والمناطق؛ فما يضحك شيوخ المدينة قد يبدو غامضاً لشبابها، لكن البنية القصيرة تبقى مشتركة."]},{"heading":"ضحك في المطبخ وهمس على الهاتف","paragraphs":["في العهد السوفيتي كانت النكات السياسية نوعاً رئيسياً، تُروى في المطابخ وعلى الهاتف، وتعمل تعليقاً مستتراً على النقص والرقابة والقادة.","كثير من النكات يقوم على التلاعب اللغوي والجناس الذي يصعب ترجمته، وبعضها انتقل إلى لغات أخرى بصيغ معدّلة.","اليوم يواصل النوع حياته على الإنترنت، لكن الشخصيات السوفيتية القديمة تتراجع عند الروس الأصغر سناً."]}],"de":[{"heading":"Kurze Geschichte mit bekannten Figuren","paragraphs":["Der russische Anekdot ist eine kurze erfundene Geschichte oder ein Dialog mit einer Pointe, aufgebaut auf festen Schauplätzen und wiederkehrenden Figuren, die der Zuhörer schon vor dem ersten Satz kennt.","Zu ihnen gehören Vovochka der Schuljunge, das nördliche Volk der Tschuktschen als naiver Außenseiter, Radio Armenien sowie Ehemann, Ehefrau und Schwiegermutter aus dem Alltag.","Je nach Region und Generation wirken die Witze unterschiedlich; was ältere Städter zum Lachen bringt, bleibt jüngeren oft fremd, doch die kurze Form verbindet sie."]},{"heading":"Lachen in der Küche, Flüstern am Telefon","paragraphs":["In der Sowjetzeit waren politische Witze ein Hauptgenre; sie wurden in Küchen und am Telefon erzählt und wirkten als verdeckter Kommentar zu Mangel, Zensur und Machthabern.","Viele Witze beruhen auf Wortspielen, die sich kaum übersetzen lassen, und manche wanderten in angepasster Form in andere Sprachen.","Heute lebt das Genre im Internet weiter, doch die alten sowjetischen Figuren verschwinden bei jüngeren Russen zusehends."]}],"en":[{"heading":"A short story with familiar faces","paragraphs":["The Russian anekdot is a short fictional story or dialogue with a punchline, built around fixed settings and recurring characters the listener knows before the first line.","They include Vovochka the schoolboy, the northern Chukchi as a naive outsider, Armenian Radio, and everyday figures such as the husband, wife and mother-in-law.","Jokes vary by region and generation; what makes older city dwellers laugh can seem opaque to younger Russians, yet the short form still connects them."]},{"heading":"Laughter in the kitchen, whispers on the phone","paragraphs":["In the Soviet era political jokes were a major genre, told in kitchens and on the phone, working as covert commentary on shortages, censorship and leaders.","Many jokes rely on linguistic puns and wordplay that resist translation, and some have travelled into other languages in adapted form.","Today the genre continues online, but the old Soviet characters are fading from use among younger Russians."]}]},"context":{"countries":["RU"],"region":"Eastern Europe","continent":"europe","languages":["ru"],"period":"contemporary"},"tags":["regional-humour","Eastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Russian jokes","de":"Russian jokes","en":"Russian jokes"},"url":"https://en.wikipedia.org/wiki/Russian_jokes","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Russian humour","de":"Russian humour","en":"Russian humour"},"url":"https://en.wikipedia.org/wiki/Russian_humour","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تحكي نكتة راديو أرمينيا سؤالاً ثم تعطي نهاية تعلّق على نقص ما؛ فيضحك المستمعون على عبث البيروقراطية لا على شخص بعينه.","de":"Ein Witz von Radio Armenien stellt eine Frage und liefert eine Pointe über einen Mangel; die Zuhörer lachen über die bürokratische Absurdität, nicht über eine Person.","en":"An Armenian Radio joke asks a question and gives a punchline that comments on a shortage; listeners laugh at the bureaucratic absurdity rather than at a person."},"misunderstanding":{"ar":"هذا النوع ليس دليلاً موثوقاً على ما يفكر فيه الروس: النكات تدور في المجال الخاص، والفكاهة السياسية صارت أكثر خطراً في الظروف الحالية، وصورة «الكآبة الروسية» هي بقدر ما هي صورة نمطية غربية بقدر ما هي وصف ذاتي محلي.","de":"Das Genre ist kein verlässlicher Führer zu dem, was Russen denken: Witze zirkulieren im Privaten, politische Humor ist unter den heutigen Bedingungen riskanter geworden, und das Bild der „russischen Melancholie“ ist ebenso westliches Klischee wie lokale Selbstbeschreibung.","en":"The genre is not a reliable guide to what Russians think: jokes circulate in private, political humour has become riskier under current conditions, and the image of 'Russian melancholy' is as much a Western stereotype as a local self-description."},"comparison":{"ar":"يشبه الأناكدوت الحكاية الشعبية القصيرة في ثقافات أخرى، لكنه يتميز بشخصيات ثابتة ونهاية حادة، وبقدرته على قول ما لا يُقال في العلن.","de":"Der Anekdot ähnelt kurzen Volkserzählungen anderer Kulturen, doch seine festen Figuren, die scharfe Pointe und die Fähigkeit, Unausgesprochenes zu sagen, machen ihn besonders.","en":"The anekdot resembles short folk tales in other cultures, but its fixed cast, sharp punchline and ability to voice what cannot be said openly make it distinctive."}},{"id":"eur-062","version":2,"slug":"klapa-dalmatian-singing-with-no-instruments-at-all","contentType":"note","category":"music-and-dance","title":{"ar":"كلابا: غناء دلماسي بلا آلات","de":"Klapa: Dalmatinischer Gesang ohne Instrumente","en":"Klapa: Dalmatian singing without instruments"},"deck":{"ar":"مجموعة أصدقاء يقفون في حلقة ويغنّون معًا، أصواتهم وحدها تكفي لملء ساحة حجرية في ليالي الصيف.","de":"Eine Gruppe von Freunden steht im Kreis und singt zusammen, und ihre Stimmen allein füllen an Sommerabenden einen steinernen Platz.","en":"A group of friends stands in a circle and sings together, and their voices alone fill a stone square on summer evenings."},"teaser":{"ar":"في دلماسيا الكرواتية يُغنّى الحب والبحر والخمر بأصوات بشرية فقط، وتقاليد عمرها قرون ما زالت تجمع الناس في المهرجانات.","de":"In der kroatischen Region Dalmatien werden Liebe, Meer und Wein nur mit menschlichen Stimmen besungen, und diese jahrhundertealte Tradition bringt Menschen noch heute bei Festivals zusammen.","en":"In Croatia's Dalmatia, love, the sea and wine are sung with human voices only, and this centuries-old tradition still brings people together at festivals today."},"readingMinutes":1,"sections":{"ar":[{"heading":"أصدقاء حول نغمة واحدة","paragraphs":["كلمة كلابا تعني حرفيًا «مجموعة أصدقاء»، وهذا جوهر هذا الغناء الجماعي من دلماسيا على الساحل الكرواتي. نشأ هذا التقليد جزئيًا من الغناء الكنسي، لكن موضوعاته اليوم دنيوية: الحب، والخمر، والبحر، والوطن.","تُبنى الموسيقى على التناغم واللحن، أما الإيقاع فدور ثانوي. تضم المجموعة النموذجية عدة أصوات رجالية أو نسائية مع صوت قائد يقود المجموعة.","يختلف الأمر بين الأجيال: بعض المجموعات تحافظ على الأداء التقليدي البسيط، بينما تقدم مجموعات شابة عروضًا مسرحية حديثة. هذا الاختلاف طبيعي في تقليد حيّ يتنفس مع أهله."]},{"heading":"مهرجانات تُبقي الصوت حيًّا","paragraphs":["في عام 2012 أُدرج غناء الكلابا في قائمة اليونسكو للتراث الثقافي غير المادي للبشرية، وهو اعتراف عالمي بتقليد محلي.","ساهمت المهرجانات، وخاصة في مدينة أوميش، في إبقاء التقليد حيًّا. في المهرجان الصيفي يقف رجال في ساحة حجرية ويغنّون بتناغم قريب، والجمهور يعرف اللازمة جيدًا ويرددها معهم.","لكن الكلابا مرتبطة بالساحل والجزر الدلماسية، لا بكرواتيا كلها. قد يعرف سكان المناطق الداخلية هذا الغناء بالكاد، لأن المهرجانات وحّدت الذخيرة الفنية وفق معايير المنافسة."]}],"de":[{"heading":"Freunde auf einem Ton","paragraphs":["Das Wort Klapa bedeutet wörtlich „eine Gruppe von Freunden“, und genau das ist der Kern dieses mehrstimmigen Gesangs aus Dalmatien an der kroatischen Küste. Die Tradition entstand teilweise aus dem Kirchengesang, doch heute sind die Themen weltlich: Liebe, Wein, Meer und Heimat.","Die Musik baut auf Harmonie und Melodie, der Rhythmus ist zweitrangig. Eine typische Gruppe hat mehrere Männer- oder Frauenstimmen mit einem Vorsänger.","Zwischen den Generationen gibt es Unterschiede: Manche Gruppen pflegen den schlichten traditionellen Vortrag, während jüngere Gruppen moderne szenische Aufführungen zeigen. Diese Vielfalt ist normal für eine lebendige Tradition."]},{"heading":"Festivals halten die Stimme lebendig","paragraphs":["Im Jahr 2012 wurde der Klapa-Gesang in die UNESCO-Liste des immateriellen Kulturerbes der Menschheit aufgenommen, eine weltweite Anerkennung einer lokalen Tradition.","Festivals, besonders in Omiš, halten die Tradition am Leben. Beim Sommerfestival singen Männer in enger Harmonie auf einem steinernen Platz, und das Publikum kennt die Refrains gut genug, um mitzusummen.","Doch Klapa ist eng mit der dalmatinischen Küste und den Inseln verbunden, nicht mit ganz Kroatien. Menschen im Landesinneren kennen diesen Gesang kaum, weil die Festivals das Repertoire nach Wettbewerbsregeln vereinheitlicht haben."]}],"en":[{"heading":"Friends on a single note","paragraphs":["The word klapa literally means 'a group of friends', and that is the heart of this part-singing tradition from Dalmatia on the Croatian coast. It grew partly from church singing, but today the themes are worldly: love, wine, the sea and the homeland.","The music is built on harmony and melody, while rhythm is secondary. A typical group has several male or female voices with a lead singer.","Things vary between generations: some groups keep the plain traditional delivery, while younger ones stage modern performances. That range is normal for a living tradition."]},{"heading":"Festivals keep the voice alive","paragraphs":["In 2012 klapa singing was inscribed on UNESCO's Representative List of the Intangible Cultural Heritage of Humanity, a global recognition of a local tradition.","Festivals, especially in Omiš, have kept the tradition alive. At a summer festival, men sing in close harmony on a stone square, and the audience knows the choruses well enough to hum along.","But klapa is closely tied to the Dalmatian coast and islands, not to Croatia as a whole. Inland Croatians may barely know it, because the festival repertoire has been standardised by competition."]}]},"context":{"countries":["HR"],"region":"Southeastern Europe","continent":"europe","languages":["hr"],"period":"contemporary"},"tags":["music-and-dance","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Klapa","de":"Klapa","en":"Klapa"},"url":"https://en.wikipedia.org/wiki/Klapa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Croatia","de":"Culture of Croatia","en":"Culture of Croatia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Croatia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مهرجان صيفي ببلدة دلماسية، تغني مجموعة كلابا رجالية بتناغم متقارب في ساحة حجرية، والجمهور يعرف اللازمة جيدًا ويتمتم معهم.","de":"Bei einem Sommerfestival in einer dalmatinischen Stadt singt eine Männerklapa in enger Harmonie auf einem steinernen Platz, und das Publikum kennt die Refrains gut genug, um mitzusummen.","en":"At a summer festival in a Dalmatian town, a men's klapa sings in close harmony on a stone square, and the audience knows the choruses well enough to hum along."},"misunderstanding":{"ar":"يظن البعض أن الكلابا غناء وطني لكل كرواتيا، لكنها في الحقيقة تقليد ساحلي وجزري مرتبط بدلماسيا وحدها.","de":"Manche halten Klapa für den Nationalgesang ganz Kroatiens, doch tatsächlich ist es eine Küsten- und Inseltradition Dalmatiens.","en":"Some assume klapa is the national song of all Croatia, but in fact it is a coastal and island tradition tied to Dalmatia alone."},"comparison":{"ar":"مثل الغناء الجماعي في كثير من ثقافات البحر المتوسط، تعتمد الكلابا على الأصوات البشرية وحدها دون أي آلة موسيقية.","de":"Wie vielerorts im Mittelmeerraum beruht der Gesang allein auf menschlichen Stimmen, ganz ohne Instrumente.","en":"As with much singing around the Mediterranean, klapa relies on human voices alone, with no instruments at all."}},{"id":"eur-063","version":2,"slug":"slava-a-family-s-saint-day-inherited-through-the-generations","contentType":"note","category":"family-and-friendship","title":{"ar":"سلافا: عيد القديس العائلي يتوارثه الأجيال","de":"Slava: der Familientag des Schutzheiligen","en":"Slava: a family's saint day, inherited through generations"},"deck":{"ar":"في صربيا، تحتفل كل عائلة بيوم قديسها الشفيع، وهو تقليد يتوارثه الأبناء عن الآباء ويجمع الأقارب والجيران.","de":"In Serbien feiert jede Familie den Tag ihres Schutzheiligen. Die Slava wird über Generationen weitergegeben und stärkt den Zusammenhalt von Familie und Nachbarschaft.","en":"In Serbia, each family celebrates its patron saint's feast day. The Slava is passed down through generations and strengthens family and neighbourhood ties."},"teaser":{"ar":"سلافا هو عيد القديس العائلي لدى الصرب الأرثوذكس، يُورث من الأب إلى الابن، ويجمع العائلة والجيران حول مائدة واحدة.","de":"Die Slava ist ein serbisch-orthodoxer Familientraditionstag, an dem eine Familie den Patronatsheiligen feiert – mit Brot, Kerze und Wein.","en":"Slava is a Serbian Orthodox family tradition: a day to honour the patron saint with bread, candle and wine, inherited from father to son."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يُورث عيد القديس؟","paragraphs":["سلافا هو تقليد صربي أرثوذكسي تجتمع فيه العائلة في يوم عيد قديسها الشفيع. يُورث القديس عن طريق الأب، لذا ينتقل عيد العائلة عادة من الأب إلى الابن، ويُحدد التاريخ حسب التقويم الكنسي.","تختلف طريقة الاحتفال بين العائلات والمناطق، كما تختلف بين الأجيال؛ فبعض العائلات تلتزم بشعائر كنسية صارمة، بينما يكتفي البعض الآخر بحفلة عائلية بسيطة. وفي المدن، قد يكون الاحتفال أكثر تواضعًا مما هو عليه في الريف."]},{"heading":"مائدة تجمع العائلة والجيران","paragraphs":["يشمل الطقس خبزًا خاصًا يُسمى «سلافسكي كولاتش»، وشمعة، وقمحًا مسلوقًا «كولجيفو»، ونبيذًا أحمر، وبخورًا. ويُستقبل الضيوف ويُطعمون، مما يعزز الروابط العائلية وعلاقات الجيرة.","في عام 2014، أُدرجت سلافا في القائمة التمثيلية للتراث الثقافي غير المادي للبشرية لدى اليونسكو."]}],"de":[{"heading":"Vererbung des Schutzheiligen","paragraphs":["Die Slava ist eine serbisch-orthodoxe Tradition, bei der eine Familie am Festtag ihres Schutzheiligen zusammenkommt. Der Heilige wird patrilinear vererbt, sodass die Slava meist vom Vater auf den Sohn übergeht; das Datum richtet sich nach dem Kirchenkalender.","Die Feier unterscheidet sich je nach Familie, Region und Generation: Manche halten strenge kirchliche Riten ein, andere feiern entspannt im Familienkreis. In Städten fällt die Slava oft bescheidener aus als das dörfliche Ideal."]},{"heading":"Gemeinschaft am gedeckten Tisch","paragraphs":["Zum Ritual gehören ein spezielles Brot (slavski kolač), eine Kerze, gekochter Weizen (koljivo), Rotwein und Weihrauch. Gäste werden willkommen geheißen und bewirtet, wodurch familiäre und nachbarschaftliche Bande gefestigt werden.","Im Jahr 2014 wurde die Slava in die Repräsentative Liste des immateriellen Kulturerbes der Menschheit der UNESCO aufgenommen."]}],"en":[{"heading":"How the saint is inherited","paragraphs":["Slava is a Serbian Orthodox tradition in which a family gathers on the feast day of its patron saint. The saint is inherited patrilineally, so a family's slava usually passes from father to son, and the date is fixed by the church calendar.","Celebrations vary by family, region and generation: some keep strict church observance, while others enjoy a relaxed family party. Urban families may celebrate more modestly than the village ideal."]},{"heading":"A table that binds family and neighbours","paragraphs":["The ritual includes a special bread (slavski kolač), a candle, boiled wheat (koljivo), red wine and incense. Guests are welcomed and fed, and the slava is an occasion for reaffirming family and neighbourhood ties.","In 2014 the Slava was inscribed on UNESCO's Representative List of the Intangible Cultural Heritage of Humanity."]}]},"context":{"countries":["RS"],"region":"Southeastern Europe","continent":"europe","languages":["sr"],"period":"contemporary"},"tags":["family-and-friendship","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Slava (tradition)","de":"Slava (tradition)","en":"Slava (tradition)"},"url":"https://en.wikipedia.org/wiki/Slava_(tradition)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Serbia","de":"Culture of Serbia","en":"Culture of Serbia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Serbia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عيد سلافا لعائلته، يشعل الرجل الصربي الشمعة، ويقطع الخبز مع الكاهن أو أكبر أفراد العائلة، ثم يقدم الراكيا والطعام للأقارب والجيران.","de":"Bei der Slava seiner Familie entzündet ein serbischer Mann die Kerze, schneidet das Brot mit dem Priester oder dem ältesten Familienmitglied und serviert anschließend Rakija und Essen an Verwandte und Nachbarn.","en":"On his family's slava a Serbian man lights the candle, cuts the bread with the priest or eldest family member, and then serves rakija and food to relatives and neighbours."},"misunderstanding":{"ar":"سلافا ليس عيدًا وطنيًا عامًا يحتفل به جميع الصرب في التاريخ نفسه، بل هو عيد عائلي خاص لكل أسرة، وقد لا تحتفل به بعض العائلات الصربية غير الأرثوذكسية.","de":"Die Slava ist kein allgemeiner Feiertag, den alle Serben am selben Datum begehen. Sie ist ein familienspezifisches Fest und wird nicht von allen serbischen Familien gefeiert, insbesondere nicht von nicht-orthodoxen.","en":"Slava is not a national holiday celebrated by all Serbs on the same date; it is a family-specific feast, and not all Serbian families celebrate it, especially non-Orthodox ones."},"comparison":{"ar":"يمكن مقارنة سلافا بأعياد القديسين الشفيعين في المجتمعات المسيحية الأخرى، لكن ما يميزه هو توارثه عبر خط الأب وارتباطه الوثيق بالعائلة والجيرة.","de":"Die Slava ähnelt Patronatsfesten in anderen christlichen Gemeinschaften, doch die patrilineare Weitergabe und die enge Bindung an Familie und Nachbarschaft machen sie besonders.","en":"Slava resembles patron saint days in other Christian communities, but its patrilineal inheritance and close link to family and neighbourhood make it distinctive."}},{"id":"eur-064","version":2,"slug":"the-kafana-and-the-long-serbian-evening","contentType":"scene","category":"food-and-hospitality","title":{"ar":"الكنافة والمساء الصربي الطويل","de":"Die Kafana und der lange serbische Abend","en":"The kafana and the long Serbian evening"},"deck":{"ar":"مقهى وحانة ومجلس سمر في آن واحد، حيث يمتد الحديث والموسيقى حتى ساعة متأخرة.","de":"Ein Kaffeehaus, eine Kneipe und ein Treffpunkt zugleich, wo Gespräche und Musik bis tief in die Nacht dauern.","en":"A coffeehouse, a tavern and a gathering place at once, where talk and music stretch deep into the night."},"teaser":{"ar":"في الكنافة يلتقي القهوة والراكيا والأغنية الشعبية، فيمتد المساء ساعات طويلة بين الأصدقاء والضحك والدموع.","de":"In der Kafana treffen Kaffee, Rakija und Volksmusik aufeinander, und der Abend dehnt sich über viele Stunden zwischen Freunden, Lachen und Tränen.","en":"In the kafana, coffee, rakija and folk music meet, and the evening stretches over many hours among friends, laughter and tears."},"readingMinutes":1,"sections":{"ar":[{"heading":"من مقهى إلى مجلس سمر","paragraphs":["الكنافة مقهى أو حانة صغيرة تنتشر في جنوب شرق أوروبا، بدأت بتقديم القهوة والمشروبات الساخنة ثم صارت تقدم الطعام والشراب. انتقل هذا التقليد في العهد العثماني وتحوّل إلى مكان للاجتماع، تقليديًا للرجال، حيث تجتمع القهوة والراكيا والحديث.","تختلف العادات من جيل إلى جيل ومن مدينة إلى أخرى، فبعض الأماكن ما زالت تحافظ على طابعها القديم بينما اختار الشباب أماكن أكثر هدوءًا."]},{"heading":"الموسيقى والليل الطويل","paragraphs":["كثير من الكنافات فيها موسيقى حية، وترتبط بالغناء الشعبي الصربي وموسيقى النحاس والليالي الطويلة والغناء العاطفي. كانت هذه الأماكن أيضًا ملتقى للسياسيين والأدباء، وما زالت رمزًا لمساء بطيء ودافئ.","لكن الصورة الدخانية الحنينية ليست القصة كلها، فقد غيّرت قوانين منع التدخين والأسعار وعادات الشرب لدى الأجيال الجديدة ملامح المشهد."]}],"de":[{"heading":"Vom Kaffeehaus zum Treffpunkt","paragraphs":["Eine Kafana ist ein Kaffeehaus, Bistro oder eine Taverne in Südosteuropa, ursprünglich für Kaffee und warme Getränke, heute meist auch für Alkohol und Essen. Das Konzept verbreitete sich während der osmanischen Herrschaft und wurde zum gesellschaftlichen Treffpunkt, traditionell für Männer, wo Kaffee, Rakija und Gespräch zusammengehörten.","Die Bräuche unterscheiden sich je nach Region und Generation: Manche Häuser pflegen den alten Charakter, während jüngere Gäste ruhigere Orte wählen."]},{"heading":"Musik und lange Nächte","paragraphs":["Viele Kafanas bieten Live-Musik und sind mit serbischer Volks- und Blasmusik, langen Nächten und emotionalem Singen verbunden. Sie waren politische und literarische Treffpunkte und bleiben ein Symbol für einen langsamen, geselligen Abend.","Doch das verklärte Bild der verrauchten Taverne ist nur ein Teil der Geschichte: Rauchverbote, Preise und veränderte Trinkgewohnheiten jüngerer Menschen haben die Szene gewandelt."]}],"en":[{"heading":"From coffeehouse to gathering place","paragraphs":["A kafana is a coffeehouse, bistro or tavern common in Southeast Europe, originally serving coffee and warm drinks and now usually alcohol and food as well. The concept spread during Ottoman rule and evolved into a social gathering place, traditionally for men, where coffee, rakija and conversation went together.","Customs vary by region and generation: some houses keep their old character, while younger guests often choose quieter places."]},{"heading":"Music and long nights","paragraphs":["Many kafanas feature live music and are associated with Serbian folk and brass music, long nights and emotional singing. They have been political and literary meeting places and remain a symbol of a particular kind of slow, sociable evening.","But the nostalgic image of the smoky tavern is only part of the story: smoking bans, prices and younger drinking habits have changed the scene."]}]},"context":{"countries":["RS"],"region":"Southeastern Europe","continent":"europe","languages":["sr"],"period":"contemporary"},"tags":["food-and-hospitality","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kafana","de":"Kafana","en":"Kafana"},"url":"https://en.wikipedia.org/wiki/Kafana","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Rakia","de":"Rakia","en":"Rakia"},"url":"https://en.wikipedia.org/wiki/Rakia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يلتقي مجموعة أصدقاء في كنافة ببلغراد عند التاسعة مساءً، يطلبون المشاوي والراكيا، ويبقون حتى يحزم الفرقة آلاتها بعد الثانية صباحًا.","de":"Eine Gruppe Freunde trifft sich um neun in einer Belgrader Kafana, bestellt Gegrilltes und Rakija und bleibt, bis die Band nach zwei Uhr morgens zusammenpackt.","en":"A group of friends meets at a Belgrade kafana at nine, orders grilled food and rakija, and stays until the band packs up after two in the morning."},"misunderstanding":{"ar":"يظن البعض أن الكنافة اختراع صربي خالص، لكنها مؤسسة بلقانية مشتركة لها نظائر بأسماء مختلفة في المنطقة.","de":"Viele halten die Kafana für eine rein serbische Erfindung, doch sie ist eine gemeinsame Balkan-Institution mit ähnlichen Häusern unter anderen Namen.","en":"Many assume the kafana is a purely Serbian invention, but it is a shared Balkan institution with similar places under different names."},"comparison":{"ar":"تشبه الكنافة المقاهي الشعبية في بلدان أخرى، لكن ما يميزها هو الجمع بين القهوة والطعام والموسيقى الحية في مساء واحد طويل.","de":"Die Kafana ähnelt Volkscafés anderswo, doch sie verbindet Kaffee, Essen und Live-Musik in einem einzigen langen Abend.","en":"The kafana resembles people's cafés elsewhere, yet it combines coffee, food and live music in one long evening."}},{"id":"eur-065","version":2,"slug":"sevdalinka-bosnia-s-slow-song-of-love-and-loss","contentType":"note","category":"music-and-dance","title":{"ar":"سيفدالينكا: أغنية الحب والفقد البطيئة","de":"Sevdalinka: Bosniens langsames Lied der Liebe","en":"Sevdalinka: Bosnia's Slow Song of Love"},"deck":{"ar":"في مدن البوسنة العثمانية وُلدت أغنية بطيئة تُروى فيها قصص الحب والفراق، وما زالت تُغنّى حتى اليوم.","de":"In den osmanischen Städten Bosniens entstand ein langsames Lied, das von Liebe und Verlust erzählt und bis heute gesungen wird.","en":"In Ottoman-era Bosnian towns a slow song took root, telling of love and loss, and it is still sung today."},"teaser":{"ar":"سيفدالينكا، أو سيفداه، لون من الأغنية الشعبية الحضرية في البوسنة والهرسك، يمزج بين الشجن والحنين، ويُؤدى بصوت فردي وآلات قليلة.","de":"Sevdalinka, auch Sevdah genannt, ist eine traditionelle städtische Volksliedgattung aus Bosnien und Herzegowina, die Sehnsucht und Liebe in melancholischen Melodien verbindet.","en":"Sevdalinka, also called sevdah, is a traditional urban folk song from Bosnia and Herzegovina, blending longing and love in slow, melismatic melodies."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور في المدن العثمانية","paragraphs":["نشأت السيفدالينكا في المدن البوسنية إبان العهد العثماني، حيث كانت تُعزف على آلة الساز ثم على الأكورديون، وتُؤدى بصوت مغنٍّ وفرقة صغيرة.","كلمة سيفداه مشتقة من العربية والتركية وتعني الحب أو الشغف، والأغاني بطيئة ومزخرفة لحنيًا، تدور غالبًا حول الحب والشوق والفراق.","كثير من السيفدالينكات مجهولة المؤلف وتناقلها الناس شفويًا، بينما تُعرف أسماء مؤلفي أشهر نسخها."]},{"heading":"أغنية تتجاوز الحدود","paragraphs":["تنتشر السيفدالينكا في البوسنة والهرسك وصربيا وكرواتيا والجبل الأسود، وتُعد جزءًا من الهوية البوسنية بشكل خاص، مع تباين في الأسلوب بين الأجيال والمناطق.","في عام 2024 أُدرجت السيفدالينكا في قائمة اليونسكو التمثيلية للتراث الثقافي غير المادي للبشرية.","ورغم الصورة الشرقية التي ارتبطت بها لاحقًا، فإن التوزيعات الموسيقية الحديثة غيّرت من صوتها، ما يعكس مرونة هذا الفن وقدرته على التجدد."]}],"de":[{"heading":"Wurzeln in osmanischen Städten","paragraphs":["Die Sevdalinka entwickelte sich in den osmanischen Städten Bosniens, wo sie zunächst mit der Saz, später mit dem Akkordeon begleitet wurde und von einer Sängerin oder einem Sänger mit kleinem Ensemble vorgetragen wird.","Das Wort Sevdah stammt aus dem Arabischen und Türkischen und bedeutet Liebe oder Leidenschaft. Die Lieder sind langsam und melismatisch, meist geht es um Liebe, Sehnsucht und Trennung.","Viele Sevdalinkas sind anonym und wurden mündlich überliefert, während die Komponisten der bekanntesten Versionen oft bekannt sind."]},{"heading":"Ein Lied über Grenzen hinweg","paragraphs":["Sevdalinka ist in Bosnien und Herzegowina, Serbien, Kroatien und Montenegro verbreitet und wird besonders mit der bosniakischen Identität verbunden, wobei sich Stil und Vortrag je nach Region und Generation unterscheiden.","Im Jahr 2024 wurde Sevdalinka in die Repräsentative Liste des immateriellen Kulturerbes der Menschheit der UNESCO aufgenommen.","Das oft als 'orientalisch' bezeichnete Image ist teilweise eine spätere Konstruktion, und Pop-Arrangements haben den Klang der Gattung verändert."]}],"en":[{"heading":"Roots in Ottoman Towns","paragraphs":["Sevdalinka developed in Ottoman-era Bosnian towns, played on the saz and later the accordion, and performed by a singer with a small ensemble.","The word sevdah derives from Arabic and Turkish, meaning love or passion. The songs are slow and melismatic, usually about love, longing and separation.","Many sevdalinkas are anonymous and were passed down orally, while the composers of the best-known versions are often known."]},{"heading":"A Song Across Borders","paragraphs":["Sevdalinka is shared across Bosnia and Herzegovina, Serbia, Croatia and Montenegro and is associated with Bosniak identity in particular, with regional and generational variation in style and performance.","In 2024 sevdalinka was added to UNESCO's Representative List of the Intangible Cultural Heritage of Humanity.","The genre's 'Oriental' image is partly a later construction, and pop arrangements have changed how it sounds."]}]},"context":{"countries":["BA"],"region":"Southeastern Europe","continent":"europe","languages":["bs"],"period":"contemporary"},"tags":["music-and-dance","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sevdalinka","de":"Sevdalinka","en":"Sevdalinka"},"url":"https://en.wikipedia.org/wiki/Sevdalinka","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Bosnia and Herzegovina","de":"Culture of Bosnia and Herzegovina","en":"Culture of Bosnia and Herzegovina"},"url":"https://en.wikipedia.org/wiki/Culture_of_Bosnia_and_Herzegovina","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مقهى بسراييفو يؤدي مغنٍّ أغنية 'كاد يا بوغوه نا بيمباشو' برفقة أكورديون وغيتار، ويردد كبار السن اللازمة بهدوء من طاولاتهم.","de":"In einem Café in Sarajevo singt eine Sängerin 'Kad ja pođoh na Bembašu' mit Akkordeon und Gitarre, und die älteren Gäste summen den Refrain leise von ihren Tischen.","en":"At a Sarajevo café a singer performs 'Kad ja pođoh na Bembašu' with accordion and guitar, and the older guests sing the refrain quietly from their tables."},"misunderstanding":{"ar":"يُظن أحيانًا أن السيفدالينكا حكر على البوسنيين وحدهم، لكنها مشتركة بين عدة شعوب في المنطقة، وصورتها 'الشرقية' نتاج بناء لاحق أكثر مما هي جوهر تاريخي.","de":"Manchmal wird angenommen, Sevdalinka sei ausschließlich bosniakisch, doch sie wird von mehreren Völkern der Region geteilt, und ihr 'orientalisches' Image ist eher eine spätere Zuschreibung.","en":"It is sometimes assumed that sevdalinka belongs only to Bosniaks, but it is shared by several peoples in the region, and its 'Oriental' image is partly a later construction rather than a historical essence."},"comparison":{"ar":"مثل البلوز في أمريكا، تعبر السيفدالينكا عن الشوق والفقد بأسلوب بطيء، لكنها تختلف في سياقها الحضري العثماني وأدائها الجماعي في المقاهي.","de":"Ähnlich wie der Blues in Amerika drückt die Sevdalinka Sehnsucht und Verlust in langsamer Form aus, unterscheidet sich aber durch ihren osmanisch-städtischen Kontext und die gemeinschaftliche Aufführung in Cafés.","en":"Like the blues in America, sevdalinka expresses longing and loss in a slow form, but it differs in its Ottoman urban context and its communal performance in cafés."}},{"id":"eur-066","version":2,"slug":"besa-the-albanian-word-that-binds-a-promise","contentType":"language","category":"communication","title":{"ar":"البيسا: كلمة تُلزِم صاحبها بالوفاء","de":"Besa: das albanische Wort, das ein Versprechen bindet","en":"Besa: the Albanian word that binds a promise"},"deck":{"ar":"في ألبانيا، الوعد ليس مجرد كلام عابر، بل التزام أخلاقي مقدّس توارثته الأجيال.","de":"In Albanien ist ein Versprechen mehr als eine flüchtige Bemerkung – es ist eine heilige, vererbte moralische Verpflichtung.","en":"In Albania a promise is more than a passing remark; it is a sacred, inherited moral obligation."},"teaser":{"ar":"كيف تحوّلت كلمة واحدة في ألبانيا إلى عهد لا يُنقض، وإلى اسم شخصي وحجة أخلاقية في الحياة العامة؟","de":"Wie wurde ein einziges Wort in Albanien zu einem unbrechbaren Eid, zu einem Vornamen und zu einer moralischen Instanz im öffentlichen Leben?","en":"How did a single word in Albania become an unbreakable oath, a given name and a moral reference in public life?"},"readingMinutes":1,"sections":{"ar":[{"heading":"وعدٌ مقدّس في القانون العرفي","paragraphs":["البيسا (besa) مفهوم ثقافي ألباني يُترجم عادةً بـ«عهد الشرف» أو «الوعد المقدّس»، ويُعدّ مقدّسًا لا يُنقض. وهو ركن أساسي في القانون العرفي التقليدي المعروف بـ«الكانون»، الذي نظّم حياة المجتمع القبلي شفويًا لقرون طويلة.","كان للبيسا التزامات عملية: من أعطى بيسا كان عليه أن يحمي الضيف، أو يفي بوعده، أو يضمن هدنة، حتى لو كلّفه ذلك ثمنًا شخصيًا باهظًا."]},{"heading":"من الاسم إلى الحياة العامة","paragraphs":["من البيسا اشتُقّت صفة «بيسنيك» أي الأمين أو الموثوق، ولا يزال «بيسا» و«بيسنيك» من الأسماء الشخصية الشائعة في ألبانيا.","يُستشهد بالمفهوم كثيرًا في روايات إيواء الألبان لليهود خلال الحرب العالمية الثانية، كما تُستخدم «البيسا» مرجعًا أخلاقيًا في الحياة العامة الحديثة. ويختلف حضور الكلمة بين الأجيال والمناطق، إذ يستخدمها الشباب في المدن اليوم بمعنى وعد يومي بسيط أكثر منه رمزًا بطوليًا."]}],"de":[{"heading":"Ein heiliges Versprechen im Gewohnheitsrecht","paragraphs":["Besa (unbestimmte Form besë) ist ein albanisches Kulturprinzip, das meist mit „Ehrenwort“, „feierlicher Treue“ oder „Ehrenpfand“ übersetzt wird und als heilig und unverletzlich gilt. Es ist ein Eckpfeiler des traditionellen albanischen Gewohnheitsrechts, des Kanun, der die Stammesgesellschaft jahrhundertelang mündlich regelte.","Besa brachte praktische Pflichten mit sich: Wer Besa gab, musste einen Gast schützen, ein Versprechen halten oder einen Waffenstillstand garantieren – selbst um persönlichen Preis."]},{"heading":"Vom Wort zum öffentlichen Maßstab","paragraphs":["Vom Begriff besa leitet sich das Adjektiv besnik ab, „treu“ oder „vertrauenswürdig“; Besa und Besnik sind bis heute beliebte albanische Vornamen.","Das Konzept wird oft in Berichten genannt, wonach Albaner während des Zweiten Weltkriegs Juden beherbergten, und „Besa“ dient im modernen öffentlichen Leben als moralische Referenz. Je nach Region und Generation variiert die Verwendung: Jüngere in den Städten nutzen das Wort heute oft schlicht für ein alltägliches Versprechen, nicht nur im heroischen Sinn."]}],"en":[{"heading":"A sacred pledge in customary law","paragraphs":["Besa (indefinite form besë) is an Albanian cultural precept usually translated as 'pledge of honour', 'solemn faith' or 'word of honour', and it is regarded as sacred and inviolable. It is a cornerstone of Albanian traditional customary law, the Kanun, which regulated tribal society orally for centuries.","Besa carried practical obligations: a person who gave besa was expected to protect a guest, keep a promise or guarantee a truce, even at personal cost."]},{"heading":"From a name to public life","paragraphs":["The adjective besnik, derived from besa, means 'faithful' or 'trustworthy', and Besa and Besnik remain popular Albanian given names.","The concept is often cited in accounts of Albanians sheltering Jews during the Second World War, and 'Besa' has been used as a moral reference in modern Albanian public life. Its use varies by region and generation: younger people in cities often mean a simple everyday promise rather than a heroic code."]}]},"context":{"countries":["AL"],"region":"Southeastern Europe","continent":"europe","languages":["sq"],"period":"contemporary"},"tags":["communication","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Besa (Albanian culture)","de":"Besa (Albanian culture)","en":"Besa (Albanian culture)"},"url":"https://en.wikipedia.org/wiki/Besa_(Albanian_culture)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kanun (Albania)","de":"Kanun (Albania)","en":"Kanun (Albania)"},"url":"https://en.wikipedia.org/wiki/Kanun_(Albania)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتفق عائلتان في ثأر قديم على بيسا بمناسبة حفل زفاف؛ فطوال مدة الاحتفال لا يحق لأحد أن يمسّ سلاحًا أو يسعى للانتقام.","de":"Zwei Familien in einer Blutrache vereinbaren eine Besa für eine Hochzeit; während der Feier darf niemand eine Waffe berühren oder Rache suchen.","en":"Two families in a blood feud agree to a besa for a wedding; for the duration of the celebration no one may touch a weapon or seek revenge."},"misunderstanding":{"ar":"قد تحجب الصورة الرومانسية للبيسا قسوة القانون العرفي الذي تنتمي إليه، بما فيه الثأر والقواعد الأبوية؛ فالألبان المعاصرون يستخدمون الكلمة في الكلام اليومي بمعنى وعد، لا بالمعنى البطولي فقط.","de":"Das romantische Bild der Besa kann die Härte des Gewohnheitsrechts verdecken, zu dem sie gehört, einschließlich Blutrache und patriarchaler Regeln; moderne Albaner verwenden das Wort im Alltag für ein Versprechen, nicht nur im heroischen Sinn.","en":"The romantic image of besa can obscure the harshness of the customary code it belongs to, including blood feud and patriarchal rules; modern Albanians use the word in everyday speech for a promise, not only in the heroic sense."},"comparison":{"ar":"تشبه البيسا في وظيفتها الاجتماعية فكرة «كلمة الشرف» في مجتمعات متوسطية أخرى، لكنها تكتسب في ألبانيا ثقلًا قانونيًا عرفيًا يجعلها ملزمة للجماعة لا للفرد وحده.","de":"In ihrer sozialen Funktion ähnelt die Besa dem „Ehrenwort“ anderer mediterraner Gesellschaften, doch in Albanien hat sie ein gewohnheitsrechtliches Gewicht, das die Gemeinschaft bindet, nicht nur den Einzelnen.","en":"In its social function besa resembles the 'word of honour' of other Mediterranean societies, but in Albania it carries a customary legal weight that binds the community, not only the individual."},"expression":{"original":"Besa","language":"Shqip","gloss":{"ar":"عهد شرف؛ وعد يجب الوفاء به","de":"Ehrenpfand; ein Versprechen, das gehalten werden muss","en":"a pledge of honour; a promise that must be kept"},"usage":{"ar":"تُقال عند إعطاء وعد ملزم، أو لوصف شخص موثوق يُعتمد على كلمته.","de":"Wird verwendet, wenn man ein bindendes Versprechen gibt oder eine Person beschreibt, auf deren Wort man sich verlassen kann.","en":"Said when giving a binding promise, or to describe someone whose word can be trusted."},"transliteration":"besa"}},{"id":"eur-067","version":2,"slug":"macedonian-standardised-in-1945-contested-ever-since","contentType":"note","category":"languages","title":{"ar":"المقدونية: معيار لغوي مثير للجدل","de":"Mazedonisch: ein Standard, der streitet","en":"Macedonian: a standard still argued over"},"deck":{"ar":"لغة سلافية جنوبية يتحدثها نحو 1.7 مليون شخص، صاغها قرار سياسي عام 1945 وما زال الجدل حولها قائماً.","de":"Eine südslawische Sprache mit rund 1,7 Millionen Sprechenden, 1945 politisch standardisiert und bis heute umstritten.","en":"An Eastern South Slavic language spoken by around 1.7 million people, standardised in 1945 and politically contested ever since."},"teaser":{"ar":"كيف تصبح اللغة قضية هوية وطنية؟ قصة المقدونية تكشف العلاقة بين السياسة والكلام اليومي.","de":"Wie wird eine Sprache zum Politikum? Die Geschichte des Mazedonischen zeigt, wie eng Alltag und nationale Identität verbunden sind.","en":"How does a language become a political question? Macedonian shows how closely everyday speech and national identity are tied together."},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة الناس في الحياة اليومية","paragraphs":["المقدونية لغة سلافية جنوبية شرقية، يتحدثها نحو 1.7 مليون شخص كلغة أم، وهي اللغة الرسمية في مقدونيا الشمالية. يستخدمها الناس في البيت والمدرسة والإعلام، وتُدرَّس في الجامعات ولها تقليد أدبي وصحفي قائم بذاته.","تختلف طريقة الكلام بين الأجيال والمناطق: فشباب المدن يمزجون مفردات أجنبية، بينما يحافظ كبار السن في القرى على تعبيرات محلية قديمة."]},{"heading":"معيار صُنع بالسياسة","paragraphs":["وُضع المعيار في 1944-1945 على أساس اللهجات الوسطى، بعد إنشاء جمهورية مقدونيا اليوغسلافية. منذ ذلك الحين، يعتبر معظم اللغويين خارج بلغاريا المقدونية معياراً سلافياً جنوبياً مستقلاً، بينما يصفها لغويون بلغاريون كثيراً بأنها لهجة من البلغارية، وقد تحوّل الخلاف إلى قضية سياسية حادة.","يُعترف بالمقدونية لغة أقلية في أجزاء من ألبانيا والبوسنة والهرسك وصربيا وكوسوفو، ما يجعلها حاضرة في حياة مجتمعات متعددة خارج حدود الدولة."]}],"de":[{"heading":"Sprache im Alltag der Menschen","paragraphs":["Mazedonisch ist eine ostsüdslawische Sprache, die rund 1,7 Millionen Menschen als Erstsprache sprechen; sie ist Amtssprache in Nordmazedonien. Man hört sie zu Hause, in Schulen und Medien, sie wird an Universitäten gelehrt und hat eine eigene literarische Tradition.","Je nach Region und Generation klingt der Alltag unterschiedlich: Stadtjugendliche mischen fremde Wörter ein, ältere Menschen auf dem Land bewahren ältere lokale Wendungen."]},{"heading":"Ein Standard aus politischer Entscheidung","paragraphs":["Der Standard wurde 1944–45 auf Basis zentraler Dialekte geschaffen, nach der Gründung der jugoslawischen Republik Mazedonien. Die meisten Sprachwissenschaftler außerhalb Bulgariens betrachten Mazedonisch als eigenständigen südslawischen Standard, während bulgarische Linguisten es oft als Dialekt des Bulgarischen beschreiben; der Streit ist politisch aufgeladen.","Zudem ist Mazedonisch als Minderheitensprache in Teilen Albaniens, Bosnien-Herzegowinas, Serbiens und des Kosovo anerkannt, was es über die Staatsgrenzen hinaus präsent hält."]}],"en":[{"heading":"A language of daily life","paragraphs":["Macedonian is an Eastern South Slavic language spoken as a first language by around 1.7 million people and the official language of North Macedonia. People use it at home, in schools and in the media; it is taught at universities and has its own literary tradition.","Speech varies by region and generation: young people in cities mix in foreign words, while older villagers keep older local expressions."]},{"heading":"A standard made by politics","paragraphs":["The standard was created in 1944–45 on the basis of central dialects, after the Yugoslav Republic of Macedonia was founded. Most linguists outside Bulgaria treat Macedonian as a separate South Slavic standard, while Bulgarian linguists have often described it as a dialect of Bulgarian, and the dispute has been politically charged.","Macedonian is also recognised as a minority language in parts of Albania, Bosnia and Herzegovina, Serbia and Kosovo, which keeps it present beyond the state's borders."]}]},"context":{"countries":["MK"],"region":"Southeastern Europe","continent":"europe","languages":["mk"],"period":"contemporary"},"tags":["languages","Southeastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Macedonian language","de":"Macedonian language","en":"Macedonian language"},"url":"https://en.wikipedia.org/wiki/Macedonian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Macedonia naming dispute","de":"Macedonia naming dispute","en":"Macedonia naming dispute"},"url":"https://en.wikipedia.org/wiki/Macedonia_naming_dispute","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالب في سكوبيه يقرأ رواية مقدونية للصف، ويشاهد نشرة أخبار بالمقدونية، ويسمع اعتراضات بلغارية على وضع اللغة عبر شبكات التواصل.","de":"Eine Studentin in Skopje liest für den Unterricht einen mazedonischen Roman, sieht Nachrichten auf Mazedonisch und liest in sozialen Medien bulgarische Einwände gegen den Status der Sprache.","en":"A student in Skopje reads a Macedonian novel for class, watches a Macedonian-language news broadcast and hears Bulgarian objections to the language's status on social media."},"misunderstanding":{"ar":"اللغة نفسها ليست موضع شك، لأن الناس يتحدثونها فعلاً، لكن تصنيفها السياسي محل نزاع؛ كما يصعب قياس عدد المتحدثين ومدى حضور المقدونية في المهجر.","de":"Die Sprache selbst steht nicht infrage, weil Menschen sie sprechen; umstritten ist ihre politische Einordnung, und auch die Zahl der Sprechenden und die Reichweite in der Diaspora sind schwer zu messen.","en":"The language itself is not in doubt, since people speak it, but its political classification is contested; the number of speakers and the reach of Macedonian in the diaspora are also difficult to measure."},"comparison":{"ar":"حين يصف لغوي بلغاري المقدونية بأنها لهجة، لا ينفي وجودها، بل يعيد تعريف حدودها؛ وهذا يذكّر بجدالات لغوية مشابهة في دول أخرى.","de":"Wenn ein bulgarischer Linguist Mazedonisch als Dialekt beschreibt, leugnet er nicht seine Existenz, sondern verschiebt die Grenze; ähnliche Sprachdebatten gibt es auch anderswo.","en":"When a Bulgarian linguist calls Macedonian a dialect, he does not deny that people speak it; he redraws its boundary, much as similar language disputes do elsewhere."},"expression":{"original":"Здраво","language":"Македонски","gloss":{"ar":"مرحباً","de":"Hallo","en":"Hello"},"usage":{"ar":"تحية يومية غير رسمية تُستخدم عند اللقاء بين الأصدقاء والمعارف.","de":"Alltägliche informelle Begrüßung unter Freunden und Bekannten.","en":"An everyday informal greeting used among friends and acquaintances."},"transliteration":"zdravo"}},{"id":"eur-068","version":2,"slug":"slovenia-s-beekeeping-culture-and-the-birthday-of-world-bee-day","contentType":"note","category":"nature-and-seasons","title":{"ar":"نحل سلوفينيا ويوم النحل العالمي","de":"Sloweniens Imkerei und der Weltbienentag","en":"Slovenia's Bees and a Worldwide Day"},"deck":{"ar":"تربية النحل في سلوفينيا عادة وطنية تمتد من الحدائق إلى الأسطح، ويرتبط بها يوم عالمي يحمل تاريخ ميلاد رائدها.","de":"Imkerei ist in Slowenien ein Volkssport: Bienenstöcke stehen im Garten und auf Dächern, und ein weltweiter Gedenktag erinnert an einen slowenischen Pionier.","en":"Beekeeping in Slovenia is a national pastime, with hives in gardens and on rooftops, and a global day tied to a Slovene pioneer's birthday."},"teaser":{"ar":"في سلوفينيا يُربّى النحل في الحدائق وعلى الأسطح، ويرتبط اسم البلد بنحل كارنيولا الهادئ وبعيد ميلاد معلّم نحّال من القرن الثامن عشر.","de":"Die sanfte Krainer Biene, bemalte Bienenstöcke und ein Geburtstag im Mai verbinden sich in Slowenien zu einer lebendigen Alltagskultur.","en":"The gentle Carniolan bee, painted hives and a May birthday link everyday Slovene life to a worldwide campaign for pollinators."},"readingMinutes":1,"sections":{"ar":[{"heading":"نحل هادئ وتراث شعبي","paragraphs":["تشتهر سلوفينيا بنحل العسل الكارنيولي الأصلي المعروف بوداعته، ويستخدمه النحّالون في أنحاء العالم. وتربية النحل هنا عادة وطنية كثيفة الانتشار، فتُربى الخلايا في الحدائق وعلى الأسطح كما في المناحل.","وتُعدّ لوحات الخلايا المرسومة من القرن الثامن عشر والتاسع عشر جزءاً من التراث الثقافي، وتُعاد اليوم إنتاجها كتذكارات. ويختلف الاهتمام بين الأجيال والمناطق، لكن حضور النحل في الحياة اليومية يبقى واسعاً."]},{"heading":"من فيينا إلى الأمم المتحدة","paragraphs":["يُعتبر أنطون يانشا، النحّال السلوفيني ومعلّم الإمبراطورية في فيينا في القرن الثامن عشر، رائداً في تربية النحل الحديثة، وقد وُلد في العشرين من مايو.","وفي عام 2017 أعلنت الجمعية العامة للأمم المتحدة يوم العشرين من مايو يوماً عالمياً للنحل بناءً على اقتراح سلوفينيا، وكانت أول مناسبة في 2018. غير أن نجاح الحملة لا يعني أن حال الملقّحات كلها جيدة، فصحة نحل العسل والملقّحات البرية مسألتان مختلفتان."]}],"de":[{"heading":"Sanfte Bienen, lebendige Nachbarschaft","paragraphs":["Slowenien hat eine starke Imkereitradition, und die einheimische Krainer Honigbiene gilt wegen ihrer Sanftmut als geschätzt bei Imkern weltweit. Bienenstöcke stehen in Gärten und auf Dächern ebenso wie in Bienenhäusern.","Bemalte Bienenstockbretter aus dem 18. und 19. Jahrhundert gehören zum kulturellen Erbe und werden heute als Andenken nachgebildet. Je nach Region und Generation ist das Engagement unterschiedlich, doch die Bienen bleiben im Alltag sichtbar."]},{"heading":"Von Wien zu den Vereinten Nationen","paragraphs":["Anton Janša, ein slowenischer Imker und kaiserlicher Lehrer in Wien im 18. Jahrhundert, gilt als Pionier der modernen Bienenzucht; er wurde am 20. Mai geboren.","2017 erklärte die UN-Generalversammlung auf Vorschlag Sloweniens den 20. Mai zum Weltbienentag, die erste Begehung fand 2018 statt. Der diplomatische Erfolg bedeutet jedoch nicht, dass es allen Bestäubern gut geht: Bienengesundheit und wild lebende Bestäuber sind verschiedene Themen."]}],"en":[{"heading":"Gentle Bees in Everyday Life","paragraphs":["Slovenia has a strong beekeeping tradition, and the native Carniolan honey bee is prized for its gentleness and used by beekeepers around the world. Hives are kept in gardens and on rooftops as well as in apiaries, and the country has a high density of beekeepers.","Painted beehive panels from the 18th and 19th centuries are part of the cultural heritage and are now reproduced as souvenirs. Interest varies by region and generation, but bees remain a familiar presence in daily life."]},{"heading":"From Vienna to the United Nations","paragraphs":["Anton Janša, an 18th-century Slovene beekeeper and imperial teacher in Vienna, is regarded as a pioneer of modern apiculture; he was born on 20 May.","In 2017 the UN General Assembly proclaimed 20 May World Bee Day on a proposal from Slovenia, and the first observance was in 2018. The campaign's success does not mean all is well for pollinators: honeybee health and wild pollinators are different issues."]}]},"context":{"countries":["SI"],"region":"Central Europe","continent":"europe","languages":["sl"],"period":"contemporary"},"tags":["nature-and-seasons","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Carniolan honey bee","de":"Carniolan honey bee","en":"Carniolan honey bee"},"url":"https://en.wikipedia.org/wiki/Carniolan_honey_bee","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"World Bee Day","de":"World Bee Day","en":"World Bee Day"},"url":"https://en.wikipedia.org/wiki/World_Bee_Day","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية سلوفينية تعتني أسرة بصف من الخلايا المرسومة في آخر الحديقة، وفي مايو تنظم جمعية النحالين المحلية يوماً مفتوحاً.","de":"In einem slowenischen Dorf pflegt eine Familie eine Reihe bemalter Bienenstöcke am Ende des Gartens, und im Mai veranstaltet der örtliche Imkerverein einen Tag der offenen Tür.","en":"In a Slovenian village a family tends a row of painted hives at the end of the garden, and in May the local beekeeping society holds an open day."},"misunderstanding":{"ar":"يُفهم أحياناً أن يوم النحل العالمي احتفال محلي بالعسل فقط، والحقيقة أنه مناسبة دولية أُقرّت باقتراح سلوفيني وتتناول قضايا الملقّحات.","de":"Manchmal gilt der Weltbienentag nur als lokales Honigfest, doch er ist ein internationaler Anlass auf slowenische Initiative und betrifft alle Bestäuber.","en":"World Bee Day is sometimes taken as a purely local honey festival, but it is an international observance proposed by Slovenia and concerned with pollinators broadly."},"comparison":{"ar":"يشبه هذا الاهتمام الشعبي ما نجده في بلدان أوروبية أخرى حيث تُربى خلايا في الحدائق، لكن كثافة النحّالين في سلوفينيا أعلى.","de":"Ähnliche Gartenimkerei gibt es in anderen europäischen Ländern, aber die Dichte der Imker ist in Slowenien besonders hoch.","en":"Garden beekeeping is common in other European countries too, but Slovenia's density of beekeepers is unusually high."}},{"id":"eur-069","version":2,"slug":"roma-europe-s-largest-minority-and-the-language-that-holds-it-together","contentType":"note","category":"migration-and-identity","title":{"ar":"الروما: أكبر أقلية في أوروبا","de":"Roma: Europas größte Minderheit","en":"Roma: Europe's Largest Minority"},"deck":{"ar":"لغة تجمع شعوبًا متفرقة عبر القارة","de":"Eine Sprache, die verstreute Gemeinschaften verbindet","en":"One language, many scattered communities"},"teaser":{"ar":"عشرة إلى اثني عشر مليون شخص، تاريخ من الهجرة والاضطهاد، ولغة هندية-آرية تربط مجتمعات متباعدة في أوروبا.","de":"Zehn bis zwölf Millionen Menschen, eine Geschichte von Migration und Verfolgung und eine indoarische Sprache, die weit entfernte Gemeinschaften in Europa verbindet.","en":"Ten to twelve million people, a history of migration and persecution, and an Indo-Aryan language that links far-flung communities across Europe."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الهند إلى أوروبا","paragraphs":["يُعدّ الروما أكبر أقلية إثنية في أوروبا، إذ يُقدَّر عددهم بعشرة إلى اثني عشر مليون نسمة عبر القارة. وتشير الأدلة اللغوية والجينية إلى أصولهم في شمال غرب الهند، مع هجرة غربيّة وصلت أوروبا نحو القرنين الثالث عشر والرابع عشر.","الرومنية لغة هندية-آرية كبرى بمجموعات لهجية رئيسية مثل الرومنية البلقانية والفلاخية والسنتية، وكثير من المجتمعات يتحدث أيضًا أصنافًا مختلطة تُعرف بالبارا-رومانية. وتختلف هذه اللهجات اختلافًا كبيرًا بين الأجيال والمناطق، فيتحدث الشيوخ لهجة لا يعرفها الشباب المولودون في المدينة."]},{"heading":"اسم مشترك وذاكرة ثقيلة","paragraphs":["اتخذ مؤتمر الروما العالمي عام 1971 علمًا ونشيدًا مشتركين، وأصبح «روما» الاسم الجماعي المفضّل في المؤسسات الدولية. غير أن الروما ليسوا مجتمعًا واحدًا: فاللغة والدين والمهنة والوضع القانوني تتباين تباينًا هائلًا بين البلدان وداخلها.","استُعبدت مجتمعات روما في الإمارات الرومنية حتى منتصف القرن التاسع عشر، واضطُهدت في عهد النازيين خلال «بورايموس»، ولا تزال تواجه اليوم فصلًا واسعًا في السكن والتعليم والعمل."]}],"de":[{"heading":"Von Indien nach Europa","paragraphs":["Die Roma sind Europas größte ethnische Minderheit, geschätzt auf zehn bis zwölf Millionen Menschen auf dem Kontinent. Sprachliche und genetische Hinweise deuten auf Ursprünge im Nordwesten Indiens hin, mit einer Westwanderung, die Europa etwa im 13. und 14. Jahrhundert erreichte.","Romani ist eine indoarische Makrosprache mit großen Dialektgruppen wie Balkan-Romani, Vlax-Romani und Sinte-Romani; viele Gemeinschaften sprechen auch gemischte Para-Romani-Varietäten. Diese Dialekte unterscheiden sich stark zwischen Regionen und Generationen: Ältere sprechen oft eine Variante, die in der Stadt geborene Jugendliche nicht mehr kennen."]},{"heading":"Ein gemeinsamer Name, schwere Erinnerung","paragraphs":["Der Welt-Roma-Kongress von 1971 verabschiedete eine gemeinsame Flagge und Hymne, und „Roma“ wurde in internationalen Institutionen zum bevorzugten Sammelnamen. Doch Roma sind keine einzelne Gemeinschaft: Sprache, Religion, Beruf und Rechtsstatus unterscheiden sich enorm zwischen und innerhalb der Länder.","In den rumänischen Fürstentümern wurden Roma-Gemeinschaften bis Mitte des 19. Jahrhunderts versklavt und unter den Nazis im Porajmos verfolgt; heute begegnen ihnen weitverbreitete Segregation in Wohnen, Bildung und Arbeit."]}],"en":[{"heading":"From India to Europe","paragraphs":["The Roma are Europe's largest ethnic minority, estimated at ten to twelve million people across the continent. Linguistic and genetic evidence suggests origins in north-western India, with westward migration reaching Europe around the 13th and 14th centuries.","Romani is an Indo-Aryan macrolanguage with major dialect groups such as Balkan Romani, Vlax Romani and Sinte Romani; many communities also speak mixed Para-Romani varieties. These dialects vary sharply between regions and generations, so elders may speak a variety that city-born teenagers no longer know."]},{"heading":"A shared name, a heavy memory","paragraphs":["The 1971 World Romani Congress adopted a common flag and anthem, and 'Roma' became the preferred collective name in international institutions. Yet Roma are not a single community: language, religion, occupation and legal status vary enormously between and within countries.","Roma communities were enslaved in the Romanian principalities until the mid-19th century and persecuted under the Nazis in the Porajmos; today they face widespread segregation in housing, education and employment."]}]},"context":{"countries":[],"region":"Europe","community":"Roma","continent":"europe","languages":["rom"],"period":"contemporary"},"tags":["migration-and-identity","Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Romani people","de":"Romani people","en":"Romani people"},"url":"https://en.wikipedia.org/wiki/Romani_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Romani language","de":"Romani language","en":"Romani language"},"url":"https://en.wikipedia.org/wiki/Romani_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية سلوفاكية، يذهب أطفال من مستوطنة روما إلى مدرسة منفصلة بينما يبحث آباؤهم عن عمل في الخارج ويرسلون المال إلى الديار.","de":"In einem slowakischen Dorf besuchen Kinder aus einer Roma-Siedlung eine getrennte Schule, während ihre Eltern im Ausland Arbeit suchen und Geld nach Hause schicken.","en":"In a Slovak village, children from a Roma settlement attend a segregated school while their parents look for work abroad and send money home."},"misunderstanding":{"ar":"كثيرًا ما يُفترض أن الروما جماعة متجانسة تتحدث لغة واحدة وتعيش على نمط واحد، مع أن الواقع تنوّع لغوي واجتماعي واسع.","de":"Häufig wird angenommen, Roma seien eine homogene Gruppe mit einer Sprache und einer Lebensweise, obwohl die sprachliche und soziale Vielfalt groß ist.","en":"Outsiders often assume Roma are one homogeneous group with one language and one way of life, though the linguistic and social diversity is vast."},"comparison":{"ar":"كما تختلف المجتمعات المهاجرة في أوروبا بين الجيل الأول والثاني، تختلف مجتمعات الروما بين من يحافظ على اللغة ومن ينتقل إلى لغة الأغلبية.","de":"Wie sich Migrationsgemeinschaften in Europa zwischen erster und zweiter Generation verändern, so unterscheiden sich Roma-Gemeinschaften zwischen Sprachbewahrung und Wechsel zur Mehrheitssprache.","en":"Just as migrant communities in Europe change between first and second generations, Roma communities differ between keeping the language and shifting to the majority tongue."}},{"id":"eur-070","version":2,"slug":"joik-singing-a-person-not-about-one","contentType":"note","category":"music-and-dance","title":{"ar":"الجويك: تغنٍّ بالشخص لا عنه","de":"Joik: einen Menschen singen, nicht über ihn","en":"Joik: singing a person, not about one"},"deck":{"ar":"شكل غنائي سامي يختصر الإنسان أو المكان في لحن قصير متكرر، فيتعرف المستمع إلى صاحبه من النغمة قبل أي شرح.","de":"Eine traditionelle samische Gesangsform, die eine Person, ein Tier oder einen Ort im Klang vergegenwärtigt statt über sie zu erzählen.","en":"A traditional Sámi song form that evokes a person, animal or place in sound rather than telling a story about them."},"teaser":{"ar":"في مهرجانات سامي يغنّي المؤدي قريباً له بلحن لا كلمات له، فيعرف الحاضرون من هو قبل أن يُذكر اسمه.","de":"Auf einem samischen Festival joikt eine Sängerin einen Verwandten, und das Publikum erkennt ihn an der Melodie, bevor sein Name fällt.","en":"At a Sámi festival a performer joiks a relative, and listeners recognise the person from the melody before anyone explains who it is."},"readingMinutes":1,"sections":{"ar":[{"heading":"لحن يحمل صاحبه","paragraphs":["الجويك أغنية سامية تقليدية لا تحكي عن الشخص أو الحيوان أو المكان، بل تستحضره بالصوت. فالمؤدي لا يصف، بل يجعل المستمع يشعر بالحضور من خلال مقاطع قصيرة وتكرار وجرس صوتي مميز.","لا يحتاج الجويك إلى كلمات بالضرورة، وقد يُؤدى فردياً أو جماعياً. ويختلف أسلوبه من منطقة إلى أخرى، ويُسمى المؤدي joikaaja أو joiker أو jojkare بحسب اللغة، كما تتباين العادة بين الأجيال وبين القرى."]},{"heading":"من التحريم إلى المسرح","paragraphs":["اعتبر المبشرون المسيحيون الجويك وثنياً وثبطوا ممارسته، فبقي حياً جزئياً داخل العائلات والمجتمعات المحلية. واليوم يُؤدى في المهرجانات وفي الموسيقى المعاصرة.","أدخل موسيقيون ساميون الجويك في البوب والروك وموسيقى الأفلام، وصار علامة على الهوية السامية في النرويج والسويد وفنلندا وروسيا."]}],"de":[{"heading":"Eine Melodie, die jemanden trägt","paragraphs":["Ein Joik ist eine traditionelle samische Gesangsform, in der die Ausführenden eine Person, ein Tier oder einen Ort heraufbeschwören, statt über sie zu singen. Kurze Motive, Wiederholung und eine eigentümliche Stimmfärbung tragen die Wirkung.","Text ist nicht nötig: Joik kann allein oder in der Gruppe erklingen. Die regionalen Stile unterscheiden sich, und die Ausführenden heißen je nach Sprache joikaaja, joiker oder jojkare; auch zwischen Generationen und Orten gibt es merkliche Unterschiede."]},{"heading":"Vom Verdacht zur Bühne","paragraphs":["Christliche Missionare hielten Joik für heidnisch und rieten davon ab; erhalten blieb die Tradition teils in Familien und lokalen Gemeinschaften. Heute erklingt sie auf Festivals und in zeitgenössischer Musik.","Samische Musikerinnen und Musiker brachten Joik in Pop, Rock und Filmmusik. Der Stil gilt als ein Merkmal samischer Identität in Norwegen, Schweden, Finnland und Russland."]}],"en":[{"heading":"A melody that carries someone","paragraphs":["A joik is a traditional Sámi song form in which the performer evokes a person, animal or place rather than singing about it. Short motifs, repetition and a distinctive vocal timbre do the work.","Lyrics are not required, and a joik can be performed alone or in a group. Regional styles differ, performers are called joikaaja, joiker or jojkare depending on the language, and the habit varies noticeably between generations and localities."]},{"heading":"From suspicion to the stage","paragraphs":["Christian missionaries treated joik as pagan and discouraged it, and the tradition survived partly through families and local communities. It is now performed at festivals and in contemporary music.","Sámi musicians have brought joik into pop, rock and film music, and the style is one marker of Sámi identity across Norway, Sweden, Finland and Russia."]}]},"context":{"countries":["NO","SE","FI"],"region":"Sápmi (Northern Europe)","community":"Sámi","continent":"europe","languages":["se","nb","sv","fi"],"period":"contemporary"},"tags":["music-and-dance","Sápmi (Northern Europe)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Joik","de":"Joik","en":"Joik"},"url":"https://en.wikipedia.org/wiki/Joik","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Sámi people","de":"Sámi people","en":"Sámi people"},"url":"https://en.wikipedia.org/wiki/S%C3%A1mi_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مهرجان سامي يؤدي مغنٍّ الجويك لقريب له باسمه، فيتعرف المستمعون إلى الشخص من اللحن قبل أن يشرح أحد من هو.","de":"Auf einem samischen Festival joikt jemand den Namen eines Verwandten, und die Zuhörenden erkennen die Person an der Melodie, bevor jemand erklärt, wer gemeint ist.","en":"At a Sámi festival a performer joiks a relative's name, and listeners recognise the person from the melody before anyone explains who it is."},"misunderstanding":{"ar":"ليس الجويك نوعاً واحداً، بل أساليب إقليمية وملكية شخصية للألحان، والحد بين التقليدي والحديث محل جدل داخل المجتمعات السامية، وكثيراً ما يخطئ الغرباء فيظنونه غناءً عن الطبيعة.","de":"Joik ist kein einzelnes Genre: regionale Stile, persönliches Eigentum an Joiks und die Grenze zwischen traditioneller und moderner Aufführung werden in samischen Gemeinschaften diskutiert, und Außenstehende halten ihn oft für Gesang über die Natur.","en":"Joik is not a single genre: regional styles, personal ownership of joiks and the boundary between traditional and modern performance are all debated within Sámi communities, and outsiders often mistake it for a form of singing about nature."},"comparison":{"ar":"يشبه الجويك إلى حد ما نداءً عائلياً خاصاً: لحن قصير يعرف به أهل البيت من المقصود دون أن يُنطق اسم، لكنه هنا فن كامل له مؤدوه وأساليبه.","de":"Ähnlich wie ein familiärer Ruf funktioniert ein Joik als kurzes Erkennungszeichen, bei dem die Eingeweihten sofort wissen, wer gemeint ist, ohne dass ein Name fallen muss.","en":"A joik works a little like a family call-sign: a short phrase by which those who know immediately recognise who is meant, without a name ever being spoken."}},{"id":"eur-071","version":2,"slug":"british-asians-and-the-making-of-brick-lane","contentType":"note","category":"migration-and-identity","title":{"ar":"البريطانيون الآسيويون في بريك لين","de":"Britische Asiaten und die Brick Lane","en":"British Asians and the Making of Brick Lane"},"deck":{"ar":"كيف أصبح بريك لين مركزًا للمجتمع البنغلاديشي في لندن، وكيف تعكس قصته أوسع قصة الهجرة الآسيوية إلى بريطانيا.","de":"Wie die Brick Lane zum Zentrum der bangladeschischen Gemeinschaft in London wurde und die größere Geschichte asiatischer Migration nach Großbritannien erzählt.","en":"How Brick Lane became the centre of London's Bangladeshi community, and how its story reflects the wider history of Asian migration to Britain."},"teaser":{"ar":"من الهجرة بعد الحرب إلى الجيل الجديد، قصة حي لندني يجمع بين الكاري والمسجد والسوق، ويكشف تحولات الهوية البريطانية الآسيوية.","de":"Von der Nachkriegsmigration bis zur neuen Generation: Die Geschichte eines Londoner Viertels mit Curryhäusern, Moschee und Markt, die den Wandel britisch-asiatischer Identität zeigt.","en":"From post-war migration to the new generation, the story of a London neighbourhood of curry houses, a mosque and a street market reveals the shifts in British Asian identity."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور الهجرة","paragraphs":["بعد الحرب العالمية الثانية، دفعت نقص العمالة بريطانيا إلى جلب مهاجرين من الهند وباكستان وبنغلاديش. وفي عام 1972، أدى طرد الآسيويين من أوغندا إلى موجة جديدة من العائلات.","استقر многие منهم في شرق لندن، حيث تحول بريك لين تدريجيًا إلى مركز للمجتمع البنغلاديشي، مع مطاعم الكاري والمسجد وسوق الشارع.","لا يزال تاريخ الحي الهوغونوتي واليهودي مرئيًا في المباني، مما يعكس طبقات من الهجرة والتعايش. وتختلف التجربة حسب المنطقة والجيل، فبعض العائلات انتقلت إلى الضواحي بينما بقي آخرون في الحي."]},{"heading":"هوية متعددة","paragraphs":["في تعداد 2021، عرّف 5.76 مليون شخص، أي 8.6% من سكان المملكة المتحدة، أنفسهم بأنهم آسيويون أو بريطانيون آسيويون.","انتشر مصطلح 'بريطاني آسيوي' في الثمانينيات، لكنه يغطي مجتمعات ولغات وديانات مختلفة جدًا، بما في ذلك الهنود والباكستانيون والبنغلاديشيون والسريلانكيون والآسيويون من شرق أفريقيا.","شهد بريك لين صراعات حول الاستطباب والتجارة والهوية، وتراجعت تجارة مطاعم الكاري مع انتقال الأجيال الشابة إلى أعمال أخرى. ويختلف هذا المشهد بين الأجيال، فالشباب قد يحتفظون بالروابط الثقافية لكنهم يبتعدون عن المهن التقليدية."]}],"de":[{"heading":"Wurzeln der Migration","paragraphs":["Nach dem Zweiten Weltkrieg brachte der Arbeitskräftemangel Migranten aus Indien, Pakistan und Bangladesch nach Großbritannien. Die Vertreibung der Asiaten aus Uganda 1972 fügte eine weitere Welle von Familien hinzu.","Viele ließen sich im Osten Londons nieder, wo die Brick Lane allmählich zum Zentrum der bangladeschischen Gemeinschaft wurde, mit Curryhäusern, einer Moschee und einem Straßenmarkt.","Die hugenottische und jüdische Geschichte des Viertels ist noch in den Gebäuden sichtbar und spiegelt Schichten von Migration und Zusammenleben wider. Die Erfahrungen variieren je nach Region und Generation: Einige Familien zogen in die Vororte, andere blieben im Viertel."]},{"heading":"Vielfältige Identität","paragraphs":["Bei der Volkszählung 2021 bezeichneten sich 5,76 Millionen Menschen, also 8,6 % der UK-Bevölkerung, als asiatisch oder britisch-asiatisch.","Der Begriff 'British Asian' wurde in den 1980er Jahren populär, umfasst aber sehr unterschiedliche Gemeinschaften, Sprachen und Religionen, darunter indische, pakistanische, bangladeschische, sri-lankische und ostafrikanische asiatische Familien.","Die Brick Lane war Schauplatz von Auseinandersetzungen um Gentrifizierung, Lizenzierung und kulturelle Eigentümerschaft, und das Curryhaus-Gewerbe ist zurückgegangen, da jüngere Generationen andere Berufe ergreifen. Diese Entwicklung unterscheidet sich zwischen den Generationen: Jüngere bewahren kulturelle Bindungen, wenden sich aber von traditionellen Berufen ab."]}],"en":[{"heading":"Roots of Migration","paragraphs":["After the Second World War, labour shortages brought migrants from India, Pakistan and Bangladesh to Britain. The 1972 expulsion of Asians from Uganda added a further wave of families.","Many settled in east London, where Brick Lane gradually became the centre of a Bangladeshi community, with curry houses, a mosque and a street market.","The area's earlier Huguenot and Jewish history is still visible in the buildings, reflecting layers of migration and coexistence. Experience varies by region and generation: some families moved to the suburbs while others stayed in the neighbourhood."]},{"heading":"A Multifaceted Identity","paragraphs":["In the 2021 census, 5.76 million people, or 8.6% of the UK population, identified as Asian or Asian British.","The label 'British Asian' was popularised in the 1980s, but it covers very different communities, languages and religions, including Indian, Pakistani, Bangladeshi, Sri Lankan and East African Asian families.","Brick Lane has been a battleground over gentrification, licensing and cultural ownership, and the curry-house trade has declined as younger generations move into other work. This shift varies between generations: younger people may keep cultural ties but move away from traditional trades."]}]},"context":{"countries":["GB"],"region":"British Isles","community":"British Asians","continent":"europe","languages":["en","bn","ur"],"period":"contemporary"},"tags":["migration-and-identity","British Isles"],"sources":[{"organization":"Wikipedia","title":{"ar":"British Asians","de":"British Asians","en":"British Asians"},"url":"https://en.wikipedia.org/wiki/British_Asians","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Brick Lane","de":"Brick Lane","en":"Brick Lane"},"url":"https://en.wikipedia.org/wiki/Brick_Lane","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في صباح يوم أحد، تتسوق عائلة بنغلاديشية لشراء الخضروات في بريك لين بينما يصور السياح الفن الجداري ويقدم أحد المطاعم عرضًا للكاري.","de":"An einem Sonntagmorgen kauft eine bangladeschische Familie Gemüse in der Brick Lane, während Touristen Street Art fotografieren und ein Restaurantwerber ein Curry-Angebot anpreist.","en":"On a Sunday morning a Bangladeshi family shops for vegetables on Brick Lane while tourists photograph the street art and a restaurant tout offers a curry deal."},"misunderstanding":{"ar":"'بريطاني آسيوي' فئة سياسية وتعدادية واسعة وليس مجتمعًا واحدًا: البنغلاديشيون والهنود والباكستانيون وغيرهم يختلفون في اللغة والطبقة والدين، وقصة بريك لين خاصة بحي واحد في لندن.","de":"'British Asian' ist eine breite politische und Volkszählungskategorie, keine Gemeinschaft: Bangladescher, Inder, Pakistaner und andere unterscheiden sich in Sprache, Klasse und Religion, und die Brick-Lane-Geschichte ist spezifisch für ein Londoner Viertel.","en":"'British Asian' is a broad political and census category, not a community: Bangladeshis, Indians, Pakistanis and others differ in language, class and religion, and the Brick Lane story is specific to one London neighbourhood."},"comparison":{"ar":"بينما يركز بريك لين على الهوية البنغلاديشية، تعكس أحياء أخرى مثل ساوثهول في لندن أو كاسلفيلد في مانشستر مجتمعات هندية وباكستانية مختلفة، مما يظهر تنوع التجربة البريطانية الآسيوية.","de":"Während die Brick Lane die bangladeschische Identität in den Vordergrund stellt, spiegeln andere Viertel wie Southall in London oder Rusholme in Manchester unterschiedliche indische und pakistanische Gemeinschaften wider und zeigen die Vielfalt der britisch-asiatischen Erfahrung.","en":"While Brick Lane foregrounds Bangladeshi identity, other areas such as Southall in London or Rusholme in Manchester reflect different Indian and Pakistani communities, showing the diversity of the British Asian experience."}},{"id":"eur-072","version":2,"slug":"vietnamese-czechs-and-the-corner-shop","contentType":"note","category":"migration-and-identity","title":{"ar":"الفيتناميون التشيك وسوق الزاوية","de":"Vietnamesische Tschechen und der Eckladen","en":"Vietnamese Czechs and the corner shop"},"deck":{"ar":"كيف أصبحت متاجر البقالة الفيتنامية جزءًا من الحياة اليومية التشيكية، وكيف تعيش أجيال المهاجرين بين عالمين.","de":"Wie vietnamesische Lebensmittelgeschäfte Teil des tschechischen Alltags wurden und wie Migrantengenerationen zwischen zwei Welten leben.","en":"How Vietnamese grocery stores became part of Czech daily life, and how migrant generations live between two worlds."},"teaser":{"ar":"من طلاب وعمال ستينيات القرن الماضي إلى أصحاب متاجر الزاوية، قصة الفيتناميين في التشيك ليست مجرد قصة تجارة، بل حياة بين ثقافتين.","de":"Von Studenten und Arbeitern der 1960er Jahre zu Eckladenbesitzern: Die Geschichte der Vietnamesen in Tschechien ist mehr als Handel, sie ist ein Leben zwischen zwei Kulturen.","en":"From students and workers in the 1960s to corner-shop owners: the story of Vietnamese in Czechia is more than trade, it is a life between two cultures."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الطلاب إلى أصحاب المتاجر","paragraphs":["بدأ الاستيطان الفيتنامي الكبير في تشيكوسلوفاكيا في الخمسينيات والستينيات، عندما دعت البلاد طلابًا وعمالًا من فيتنام الشمالية. بعد عام 1989، بقي الكثيرون وافتتحوا متاجر صغيرة، خاصة بقالات الزاوية (potraviny) التي أصبحت جزءًا مألوفًا من المدن والقرى التشيكية.","اليوم، يُعد الفيتناميون ثالث أكبر أقلية عرقية في الجمهورية التشيكية بعد السلوفاك والأوكرانيين، وأكبر مجموعة آسيوية، بأكثر من 38 ألف شخص حسب إحصاء 2021."]},{"heading":"حياة المجتمع بين جيلين","paragraphs":["غالبًا ما يُوصف المجتمع من خلال «الجيل الأول والنصف»: شباب وصلوا أطفالًا ويتنقلون بين العالمين الفيتنامي والتشيكي. تحافظ المدارس الفيتنامية والمعابد البوذية وشبكات الأعمال على حياة المجتمع، بينما يدخل الجيل الثاني بشكل متزايد الجامعات والمهن التشيكية.","يختلف هذا الاندماج بين المناطق والأجيال: ففي المدن الكبرى، يدرس الشباب غالبًا في جامعات تشيكية، بينما تستمر العائلات في البلدات الصغيرة بإدارة المتاجر مع الحفاظ على تقاليدها."]}],"de":[{"heading":"Von Studenten zu Ladenbesitzern","paragraphs":["Die große vietnamesische Ansiedlung in der Tschechoslowakei begann in den 1950er und 1960er Jahren, als das Land Studenten und Arbeiter aus Nordvietnam einlud. Nach 1989 blieben viele und eröffneten kleine Geschäfte, besonders die potraviny-Eckläden, die zu einem festen Bestandteil tschechischer Städte und Dörfer wurden.","Heute sind Vietnamesen die drittgrößte ethnische Minderheit in Tschechien nach Slowaken und Ukrainern und die größte asiatische Gruppe, mit mehr als 38.000 Menschen laut Volkszählung 2021."]},{"heading":"Gemeinschaftsleben zwischen zwei Generationen","paragraphs":["Die Gemeinschaft wird oft durch die „1,5-Generation“ beschrieben: junge Menschen, die als Kinder ankamen und sich zwischen vietnamesischer und tschechischer Welt bewegen. Vietnamesische Schulen, buddhistische Pagoden und Geschäftsnetzwerke erhalten das Gemeinschaftsleben, während die zweite Generation zunehmend tschechische Universitäten und Berufe ergreift.","Diese Integration variiert regional und generationell: In Großstädten studieren junge Leute oft an tschechischen Universitäten, während Familien in Kleinstädten weiterhin Läden führen und Traditionen bewahren."]}],"en":[{"heading":"From students to shop owners","paragraphs":["Large-scale Vietnamese settlement in Czechoslovakia began in the 1950s and 1960s, when the country invited students and workers from North Vietnam. After 1989, many stayed and opened small shops, especially the potraviny corner grocery, which became a fixture of Czech towns and villages.","Today, Vietnamese people are the third-largest ethnic minority in the Czech Republic after Slovaks and Ukrainians, and the largest Asian group, with more than 38,000 people in the 2021 census."]},{"heading":"Community life across generations","paragraphs":["The community is often described through the '1.5 generation': young people who arrived as children and move between Vietnamese and Czech worlds. Vietnamese-language schools, Buddhist pagodas and business networks maintain community life, while the second generation increasingly enters Czech universities and professions.","This integration varies by region and generation: in large cities, young people often study at Czech universities, while families in smaller towns continue running shops while preserving traditions."]}]},"context":{"countries":["CZ"],"region":"Central Europe","community":"Vietnamese Czechs","continent":"europe","languages":["vi","cs"],"period":"contemporary"},"tags":["migration-and-identity","Central Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Vietnamese people in the Czech Republic","de":"Vietnamese people in the Czech Republic","en":"Vietnamese people in the Czech Republic"},"url":"https://en.wikipedia.org/wiki/Vietnamese_people_in_the_Czech_Republic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of the Czech Republic","de":"Culture of the Czech Republic","en":"Culture of the Czech Republic"},"url":"https://en.wikipedia.org/wiki/Culture_of_the_Czech_Republic","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يشتري زبون تشيكي خضارًا وبيرة من بقالة فيتنامية في التاسعة مساءً، وتترجم ابنة صاحب المتجر، المولودة في براغ، بين والديها والمورد.","de":"Ein tschechischer Kunde kauft um 21 Uhr Gemüse und Bier in einem vietnamesischen potraviny, und die in Prag geborene Tochter des Besitzers übersetzt zwischen ihren Eltern und dem Lieferanten.","en":"A Czech customer buys vegetables and beer at a Vietnamese potraviny at 9 p.m., and the owner's daughter, born in Prague, translates between her parents and the supplier."},"misunderstanding":{"ar":"الصورة النمطية لمتجر الزاوية تختزل مجتمعًا متنوعًا يضم طلابًا ومهنيين وتشيكيين من الجيل الثاني؛ كما أن عدد الفيتناميين صغير نسبيًا ويتركز في المدن التي توفرت فيها المتاجر.","de":"Das Eckladen-Klischee vereinfacht eine vielfältige Gemeinschaft mit Studenten, Berufstätigen und Tschechen der zweiten Generation; zudem ist die vietnamesische Bevölkerung relativ klein und konzentriert sich auf Städte, in denen Läden verfügbar waren.","en":"The corner-shop stereotype flattens a diverse community that includes students, professionals and second-generation Czechs; the Vietnamese population is also relatively small and concentrated in towns where shops were available."},"comparison":{"ar":"في فيتنام، الأسواق التقليدية هي مركز الحياة اليومية، بينما في التشيك أصبح متجر الزاوية الفيتنامي نقطة لقاء غير رسمية بين الثقافتين.","de":"In Vietnam sind traditionelle Märkte das Zentrum des Alltags, während in Tschechien der vietnamesische Eckladen zu einem informellen Treffpunkt zwischen den Kulturen wurde.","en":"In Vietnam, traditional markets are the center of daily life, while in Czechia the Vietnamese corner shop has become an informal meeting point between cultures."}},{"id":"eur-073","version":2,"slug":"albanians-in-switzerland-the-diaspora-next-door","contentType":"note","category":"migration-and-identity","title":{"ar":"ألبان سويسرا: الشتات المجاور","de":"Albaner in der Schweiz: die Diaspora nebenan","en":"Albanians in Switzerland: the diaspora next door"},"deck":{"ar":"من هم الألبان في سويسرا وكيف يعيشون بين ثقافتين؟","de":"Wer sind die Albaner in der Schweiz und wie leben sie zwischen zwei Kulturen?","en":"Who are the Albanians in Switzerland and how do they live between two cultures?"},"teaser":{"ar":"يشكل الألبان في سويسرا واحدة من أكبر مجموعات المهاجرين، حيث تمتد جذورهم من كوسوفو ومقدونيا الشمالية، مع حضور بارز في كرة القدم والحياة العامة.","de":"Albaner in der Schweiz gehören zu den größten Einwanderergruppen. Ihre Wurzeln liegen vor allem im Kosovo und in Nordmazedonien, und viele sind im Fussball und öffentlichen Leben präsent.","en":"Albanians in Switzerland form one of the largest immigrant groups, with roots mainly in Kosovo and North Macedonia, and a visible presence in football and public life."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور الهجرة وتوزيعها","paragraphs":["يعود أصل معظم الألبان في سويسرا إلى كوسوفو ومقدونيا الشمالية، وإلى حد أقل ألبانيا وغيرها من المناطق الناطقة بالألبانية. في الثمانينيات، عاش عدد محدود من مواطني يوغوسلافيا في سويسرا، لكن الهجرة الألبانية الكبرى جاءت في التسعينيات والألفينيات، خاصة أثناء حرب كوسوفو وبعدها.","يشكل المجتمع اليوم واحدة من أكبر مجموعات المهاجرين في سويسرا، والألبانية من أكثر اللغات غير الوطنية انتشارًا في البلاد. وتختلف التجارب بين الأجيال والمناطق، إذ تتباين درجة الحفاظ على اللغة الأم بين العائلات الحضرية والريفية."]},{"heading":"الهوية المزدوجة والحياة اليومية","paragraphs":["برز الجيل الثاني من الألبان في كرة القدم السويسرية والحياة العامة، وأصبح لاعبون مثل غرانيت تشاكا وتشيردان شاكيري رموزًا للهوية المزدوجة. هذه الصورة تسلط الضوء على مسار نجاح واحد فقط من مسارات هجرة أوسع."]}],"de":[{"heading":"Migrationsgeschichte und Verteilung","paragraphs":["Die meisten Albaner in der Schweiz stammen aus dem Kosovo, aus Nordmazedonien und in geringerem Umfang aus Albanien und anderen albanischsprachigen Gebieten. In den 1980er-Jahren lebten nur wenige jugoslawische Staatsbürger in der Schweiz, doch der grösste Teil der albanischen Einwanderung kam in den 1990er- und 2000er-Jahren, besonders während und nach dem Kosovo-Krieg.","Heute ist die Gemeinschaft eine der grössten Einwanderergruppen der Schweiz, und Albanisch gehört zu den am weitesten verbreiteten nicht-nationalen Sprachen des Landes. Die Erfahrungen unterscheiden sich je nach Generation und Region, da städtische und ländliche Familien ihre Herkunftssprache unterschiedlich stark pflegen."]},{"heading":"Doppelte Identität und Alltag","paragraphs":["Die zweite Generation ist im Schweizer Fussball und im öffentlichen Leben prominent vertreten; Spieler wie Granit Xhaka und Xherdan Shaqiri gelten als Symbole einer doppelten Identität. Dieses Bild zeigt jedoch nur einen erfolgreichen Strang einer viel breiteren Migrationsgeschichte."]}],"en":[{"heading":"Migration roots and distribution","paragraphs":["Most Albanians in Switzerland trace their origins to Kosovo, North Macedonia and, to a lesser extent, Albania and other Albanian-speaking territories. While moderate numbers of Yugoslav citizens lived in Switzerland in the 1980s, the bulk of Albanian immigration came in the 1990s and 2000s, especially during and after the Kosovo war.","Today the community is one of the largest immigrant groups in Switzerland, and Albanian is among the most widely spoken non-national languages in the country. Experiences vary by generation and region, as urban and rural families maintain the heritage language to different degrees."]},{"heading":"Dual identity and everyday life","paragraphs":["Second-generation Albanians are prominent in Swiss football and public life, and players such as Granit Xhaka and Xherdan Shaqiri have become symbols of dual identity. This image highlights only one successful strand of a much broader migration story."]}]},"context":{"countries":["CH"],"region":"Alpine region","community":"Albanians in Switzerland","continent":"europe","languages":["sq","de","fr","it"],"period":"contemporary"},"tags":["migration-and-identity","Alpine region"],"sources":[{"organization":"Wikipedia","title":{"ar":"Albanians in Switzerland","de":"Albanians in Switzerland","en":"Albanians in Switzerland"},"url":"https://en.wikipedia.org/wiki/Albanians_in_Switzerland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Switzerland","de":"Culture of Switzerland","en":"Culture of Switzerland"},"url":"https://en.wikipedia.org/wiki/Culture_of_Switzerland","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مراهق سويسري ألباني يتحدث الألمانية السويسرية في المدرسة، والألبانية في المنزل، ويشاهد مباراة كوسوفو مع أبناء عمومته في عطلة نهاية الأسبوع.","de":"Ein Schweizer Albaner der zweiten Generation spricht in der Schule Schweizerdeutsch, zu Hause Albanisch und schaut am Wochenende mit seinen Cousins ein Kosovo-Spiel.","en":"A Swiss-Albanian teenager speaks Swiss German at school, Albanian at home and watches a Kosovo match with cousins on the weekend."},"misunderstanding":{"ar":"ليس كل الألبان في سويسرا من كوسوفو، كما أن صورة نجوم كرة القدم لا تمثل سوى جزء من قصة أوسع تشمل تحديات الاندماج في اللغة والتعليم.","de":"Nicht alle Albaner in der Schweiz stammen aus dem Kosovo, und die Fussballstars repräsentieren nur einen kleinen Teil einer Geschichte, die auch Herausforderungen bei Sprache, Bildung und Integration umfasst.","en":"Not all Albanians in Switzerland are from Kosovo, and the football-celebrity image represents only a small part of a wider story that includes challenges of language, education and integration."},"comparison":{"ar":"بينما يركز النقاش العام على نجوم كرة القدم، يعيش كثيرون حياة يومية بعيدة عن الأضواء، حيث تبقى الروابط مع كوسوفو ومقدونيا الشمالية قوية عبر التحويلات المالية والزيارات العائلية.","de":"Während die öffentliche Debatte oft auf Fussballstars fokussiert, führen viele ein Leben abseits des Rampenlichts, wobei die Verbindungen zum Kosovo und zu Nordmazedonien durch Geldtransfers und Familienbesuche stark bleiben.","en":"While public debate often focuses on football stars, many live everyday lives away from the spotlight, with ties to Kosovo and North Macedonia kept strong through remittances and family visits."}},{"id":"eur-074","version":2,"slug":"the-emptying-european-village","contentType":"note","category":"cultural-change","title":{"ar":"هجرة الأرياف وموت القرى الأوروبية","de":"Das leere Dorf in Europa","en":"The emptying European village"},"deck":{"ar":"كيف تفرغ القرى في جنوب وشرق أوروبا، ومن يبقى ليواجه التحديات؟","de":"Landflucht verändert Süd- und Osteuropa: Wer bleibt, wenn Schulen und Busse verschwinden?","en":"Rural flight reshapes southern and eastern Europe: who stays when schools and buses disappear?"},"teaser":{"ar":"هجرة الأرياف تغير وجه أوروبا: منازل مهجورة، مدارس مغلقة، وشيوخ ينتظرون حافلة مرتين في الأسبوع.","de":"Landflucht prägt Europas Dörfer: verlassene Häuser, alternde Bevölkerung und der tägliche Kampf um Busse und Ärzte.","en":"Across southern and eastern Europe, villages are losing schools, shops and buses, leaving older residents to cope with growing isolation."},"readingMinutes":1,"sections":{"ar":[{"heading":"لماذا تفرغ القرى؟","paragraphs":["هجرة الأرياف هي انتقال الناس من الريف إلى المدن، مدفوعة بميكنة الزراعة، وقلة الخدمات، والبحث عن العمل والتعليم. في جنوب وشرق أوروبا، يظهر هذا النمط في المنازل المهجورة والشيخوخة السكانية: إسبانيا الفارغة، ومخططات المنازل بيورو واحد في إيطاليا، والداخل البرتغالي هي الأمثلة الأبرز.","تتقدم أوروبا كلها في العمر: انخفاض الخصوبة وطول العمر المتوقع يقلصان السكان في سن العمل ويوسعان عدد المتقاعدين. القرى الصغيرة تفقد المدارس والمحلات والحافلات والأطباء أولاً، مما يجعل بقاء من تبقى، وغالباً النساء الأكبر سناً، أصعب."]},{"heading":"من يبقى وكيف يعيش؟","paragraphs":["في قرية في داخل إسبانيا، تغلق المدرسة عندما يرحل آخر طفل، ويُخفض خط الحافلات إلى مرتين في الأسبوع، ومعظم السكان المتبقين فوق السبعين. تختلف هذه الظاهرة إقليمياً وجيلياً: فبعض المناطق القريبة من المدن تنمو بفضل التنقل والسياحة، بينما تفرغ أخرى."]}],"de":[{"heading":"Warum Dörfer leer laufen","paragraphs":["Landflucht ist die Abwanderung vom Land in die Städte, angetrieben durch mechanisierte Landwirtschaft, weniger Dienstleistungen und die Suche nach Arbeit und Bildung. In Süd- und Osteuropa zeigt sich das Muster in verlassenen Häusern und alternden Bevölkerungen: Spaniens 'leeres Spanien', Italiens Ein-Euro-Haus-Programme und Portugals Landesinneres sind die bekanntesten Beispiele.","Europa insgesamt altert: Geringere Fruchtbarkeit und längere Lebenserwartung verkleinern die Bevölkerung im erwerbsfähigen Alter und vergrößern die Zahl der Rentner. Kleine Dörfer verlieren zuerst Schulen, Geschäfte, Busse und Ärzte, was es für die Verbleibenden, oft ältere Frauen, schwerer macht zu bleiben."]},{"heading":"Wer bleibt und wie man lebt","paragraphs":["In einem Dorf im spanischen Landesinneren schließt die Schule, wenn das letzte Kind geht, der Bus fährt nur noch zweimal pro Woche, und die verbliebenen Bewohner sind meist über 70. Regional und generationell variiert dies: Manche ländlichen Gebiete nahe Städten wachsen durch Pendeln und Tourismus, andere leeren sich."]}],"en":[{"heading":"Why villages empty","paragraphs":["Rural flight is the movement of people from the countryside to cities, driven by mechanised agriculture, fewer services and the search for work and education. In southern and eastern Europe the pattern is visible in abandoned houses and ageing populations: Spain's 'emptied Spain', Italy's one-euro house schemes and Portugal's interior are the best-known examples.","Europe as a whole is ageing: lower fertility and longer life expectancy are shrinking the working-age population and expanding the number of retired people. Small villages lose schools, shops, buses and doctors first, which makes it harder for those who remain, often older women, to stay."]},{"heading":"Who stays and how they live","paragraphs":["In a village in inland Spain, the school closes when the last child leaves, the bus service is cut to twice a week, and the remaining residents are mostly over 70. This varies by region and generation: some rural areas near cities are growing through commuting and tourism, while others empty."]}]},"context":{"countries":["ES","PT","IT","RO","BG","HR"],"region":"Southern and Eastern Europe","continent":"europe","languages":["es","pt","it","ro","bg","hr"],"period":"contemporary"},"tags":["cultural-change","Southern and Eastern Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Rural flight","de":"Rural flight","en":"Rural flight"},"url":"https://en.wikipedia.org/wiki/Rural_flight","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ageing of Europe","de":"Ageing of Europe","en":"Ageing of Europe"},"url":"https://en.wikipedia.org/wiki/Ageing_of_Europe","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية في داخل إسبانيا، تغلق المدرسة عندما يرحل آخر طفل، ويُخفض خط الحافلات إلى مرتين في الأسبوع، ومعظم السكان المتبقين فوق السبعين.","de":"In einem Dorf im spanischen Landesinneren schließt die Schule, wenn das letzte Kind geht, der Bus fährt nur noch zweimal pro Woche, und die verbliebenen Bewohner sind meist über 70.","en":"In a village in inland Spain, the school closes when the last child leaves, the bus service is cut to twice a week, and the remaining residents are mostly over 70."},"misunderstanding":{"ar":"هجرة الأرياف ليست موحدة: بعض المناطق الريفية القريبة من المدن تنمو من خلال التنقل والسياحة، بينما تفرغ أخرى؛ صورة 'القرية المهجورة' قد تخفي مجتمعات نشطة ومقاومة محلية.","de":"Landflucht ist nicht einheitlich: Manche ländlichen Gebiete nahe Städten wachsen durch Pendeln und Tourismus, andere leeren sich; das Bild vom 'verlassenen Dorf' kann aktive Gemeinschaften und lokalen Widerstand verbergen.","en":"Rural flight is not uniform: some rural areas near cities are growing through commuting and tourism, while others empty; the 'abandoned village' image can hide active communities and local resistance."},"comparison":{"ar":"بينما تتباين استجابات الحكومات والاتحاد الأوروبي بصناديق التنمية الريفية ومشاريع النطاق العريض وحوافز الانتقال، لم ينعكس الاتجاه الديموغرافي بعد.","de":"Regierungen und die EU reagieren mit Mitteln für ländliche Entwicklung, Breitbandprojekten und Umsiedlungsanreizen, doch der demografische Trend hat sich nicht umgekehrt.","en":"Governments and the EU respond with rural development funds, broadband projects and relocation incentives, but the demographic trend has not reversed."}},{"id":"eur-075","version":2,"slug":"two-clocks-punctuality-in-europe-is-a-rule-not-a-fact","contentType":"note","category":"social-behaviour","title":{"ar":"ساعتان: الالتزام بالوقت قاعدة لا حقيقة","de":"Zwei Uhren: Pünktlichkeit ist Regel, nicht Tatsache","en":"Two clocks: punctuality is a rule, not a fact"},"deck":{"ar":"في أوروبا يحمل التأخر دلالات اجتماعية متباينة، بين مواعيد صارمة وأخرى مرنة حسب السياق والعلاقة.","de":"In Europa bedeutet Zuspätkommen je nach Land und Anlass etwas anderes: mal eine Entschuldigung wert, mal kaum bemerkenswert.","en":"Across Europe, arriving late carries different social meanings: in some places it demands an apology, in others it barely registers."},"teaser":{"ar":"موعد العمل ليس كعزيمة العشاء، والتأخر بضع دقائق قد يستوجب اعتذاراً في الشمال ولا يلاحظ في الجنوب.","de":"Ein Geschäftstermin ist kein Abendessen: Wenige Minuten Verspätung verlangen im Norden eine Entschuldigung, im Süden oft gar nichts.","en":"A business meeting is not a dinner invitation: a few minutes late needs an apology in the north and often goes unnoticed in the south."},"readingMinutes":1,"sections":{"ar":[{"heading":"متى يكون التأخر خطأً؟","paragraphs":["في كثير من شمال أوروبا، الوصول متأخراً بضع دقائق إلى اجتماع يستدعي اعتذاراً صريحاً، لأن الوقت يُفهم كالتزام متبادل. أما في أجزاء من الجنوب، فقد يمرّ التأخر نفسه دون تعليق، خصوصاً في المناسبات الخاصة.","هذا الاختلاف لا يعني أن الشماليين دائماً دقيقون والجنوبيين دائماً متسامحون؛ فبنك في هامبورغ قد يكون صارماً بينما سكان الريف الألماني أقل التزاماً، ولقاء عمل في روما قد يبدأ في موعده بينما لا تنطبق القاعدة على دعوة عشاء.","تتغير القواعد أيضاً بحسب الجيل والمدينة والسياق: موعد العمل يختلف عن العزيمة الخاصة، والشباب في المدن الكبرى قد يتبنون إيقاعاً أكثر مرونة من أسرهم."]},{"heading":"الساعة الأكاديمية والبنية التحتية","paragraphs":["تُظهر «الربع الأكاديمي» أن التأخر يمكن أن يكون قاعدة مؤسسية: في جامعات فنلندا والسويد تبدأ المحاضرات تقليدياً بعد ربع ساعة من الساعة المعلنة، ولا يُعدّ الطالب متأخراً.","لكن الالتزام بالوقت لا يعتمد على المزاج وحده؛ فالنقل العام السويسري يسير وفق جدول منشور، بينما تعاني قطارات ألمانيا من تأخيرات متكررة، ما يعني أن المعايير والبنية التحتية أمران مختلفان.","لهذا يبقى التناقض بين الشمال والجنوب اختصاراً يستخدمه الناس لفهم بعضهم، لا قاعدة يتبعها الأفراد بانتظام."]}],"de":[{"heading":"Wann Zuspätkommen zählt","paragraphs":["In weiten Teilen Nordeuropas erfordert es eine ausdrückliche Entschuldigung, einige Minuten zu spät zu einem Treffen zu erscheinen, weil Zeit als gegenseitige Verpflichtung gilt. In Teilen des Südens bleibt dieselbe Verspätung oft unbemerkt, besonders bei privaten Anlässen.","Das heißt nicht, dass Nordeuropäer immer streng und Südeuropäer immer locker sind: Ein Hamburger Banker kann unerbittlich sein, während Menschen auf dem deutschen Land weniger pünktlich sind, und ein Geschäftstermin in Rom kann pünktlich beginnen, eine Einladung zum Abendessen aber nicht.","Auch Generation und Stadtgröße verändern die Regeln: Jüngere in großen Städten leben oft flexibler als ihre Eltern, und der berufliche Kontext folgt anderen Maßstäben als der private."]},{"heading":"Akademisches Viertel und Infrastruktur","paragraphs":["Das akademische Viertel zeigt, dass Unpünktlichkeit institutionell geregelt sein kann: In finnischen und schwedischen Universitäten beginnen Vorlesungen traditionell 15 Minuten nach der angegebenen Zeit, ohne dass Studierende als verspätet gelten.","Pünktlichkeit hängt aber nicht nur von Mentalität ab: Der Schweizer Nahverkehr fährt nach veröffentlichtem Fahrplan, während deutsche Züge oft Verspätung haben – Norm und Infrastruktur sind verschiedene Dinge.","Der Nord-Süd-Gegensatz bleibt deshalb eine Kurzformel, mit der Menschen einander erklären, keine Regel, der Einzelne konsequent folgen."]}],"en":[{"heading":"When lateness counts","paragraphs":["In much of northern Europe, arriving a few minutes late to a meeting requires an explicit apology, because time is understood as a mutual obligation. In parts of the south, the same arrival may be unremarkable, especially at private occasions.","This does not make northerners uniformly strict or southerners uniformly relaxed: a Hamburg banker may be unforgiving while rural Germans are less punctual, and a Rome business meeting can start on time while a Roman dinner invitation does not.","Generation and city size change the rules too: younger people in large cities often keep a more flexible rhythm than their parents, and work contexts follow different standards from private ones."]},{"heading":"The academic quarter and infrastructure","paragraphs":["The academic quarter shows that lateness can be institutional: in Finnish and Swedish universities, lectures traditionally begin 15 minutes after the stated hour, and students are not considered late.","Punctuality is not only a matter of attitude: Swiss public transport runs to a published timetable, while German trains often do not, so norms and infrastructure are different things.","The north-south contrast therefore remains a shorthand people use to explain each other, not a rule individuals follow consistently."]}]},"context":{"countries":["DE","CH","FI","IT"],"region":"Europe","continent":"europe","languages":["de","fi","it"],"period":"contemporary"},"tags":["social-behaviour","Europe"],"sources":[{"organization":"Wikipedia","title":{"ar":"Punctuality","de":"Punctuality","en":"Punctuality"},"url":"https://en.wikipedia.org/wiki/Punctuality","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Academic quarter (class timing)","de":"Academic quarter (class timing)","en":"Academic quarter (class timing)"},"url":"https://en.wikipedia.org/wiki/Academic_quarter_(class_timing)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل طالب فنلندي الساعة 10:15 لمحاضرة تبدأ في 10:00 فلا يكون متأخراً؛ ويصل الطالب نفسه في موعده إلى اجتماع ألماني فيعتذر لأن التأخر ملموس.","de":"Eine finnische Studentin kommt um 10:15 zu einer Vorlesung um 10:00 und ist nicht zu spät; dieselbe Person erscheint pünktlich zu einem deutschen Meeting und entschuldigt sich, weil die Verspätung spürbar ist.","en":"A Finnish student arrives at 10:15 for a 10:00 lecture and is not late; the same student arrives on time for a German meeting and apologises, because the lateness is noticeable."},"misunderstanding":{"ar":"الاعتقاد الشائع أن كل الألمان والسويسريين دقيقون بالضرورة، وكل الإيطاليين متسامحون مع الوقت، وهو تبسيط لا يصمد أمام اختلاف الطبقة والعمر وحجم المدينة.","de":"Der verbreitete Irrtum, alle Deutschen und Schweizer seien zwangsläufig pünktlich und alle Italiener entspannt, hält der Prüfung durch Klasse, Alter und Stadtgröße nicht stand.","en":"The common belief that all Germans and Swiss are necessarily punctual and all Italians relaxed about time does not survive differences of class, age and city size."},"comparison":{"ar":"في ألمانيا قد يكون التأخر عيباً مهنياً، وفي فنلندا يُحتسب الربع الأكاديمي ضمن التقاليد الجامعية، وفي إيطاليا يفرّق الناس بوضوح بين موعد العمل والعزيمة الاجتماعية.","de":"In Deutschland kann Verspätung als beruflicher Fehler gelten, in Finnland gehört das akademische Viertel zur Universitätstradition, in Italien unterscheiden Menschen klar zwischen Geschäftstermin und gesellschaftlicher Einladung.","en":"In Germany lateness can read as a professional fault, in Finland the academic quarter belongs to university tradition, and in Italy people clearly separate a business meeting from a social invitation."}},{"id":"lng-001","version":2,"slug":"wolof-greetings-that-ask-after-the-whole-household-one-person-at-a-time","contentType":"scene","category":"communication","title":{"ar":"تحيات الولوف: سؤال عن كل فرد في الأسرة","de":"Wolof-Grüße, die nach jedem Haushaltsmitglied fragen","en":"Wolof greetings that ask after the whole household"},"deck":{"ar":"في السنغال الغربية يبدأ اللقاء بسلسلة أسئلة عن الأهل واحداً واحداً قبل أي حديث آخر","de":"In Westsenegal beginnt jede Begegnung mit einer Kette von Fragen nach den Angehörigen, einzeln und der Reihe nach","en":"In western Senegal an encounter opens with a chain of questions about each relative in turn, before anything else is discussed"},"teaser":{"ar":"التحية عند متحدثي الولوف ليست كلمة عابرة بل طقس اعتراف: تسأل عن كل قريب بالاسم قبل أن تصل إلى أي معلومة.","de":"Ein Gruß ist bei Wolof-Sprechern keine flüchtige Formel, sondern ein Ritual der Anerkennung: erst die Menschen, dann die Informationen.","en":"For Wolof speakers a greeting is not a passing formula but a ritual of recognition: the people come first, the information afterwards."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس الاعتراف قبل الكلام","paragraphs":["يُفتح اللقاء بـ«السلام عليكم»، ثم «نكا نغا دف؟» أي كيف حالك، ويُجاب بـ«ما نغي في ريكّ» أي أنا هنا فقط.","تواصل التحية بسؤال المحاور عن كل فرد من أسرته بالتتابع، وقد يكرر السؤال نفسه لكل واحد منهم.","الطقس يتعلق بالاعتراف بالآخر قبل تبادل المعلومات، لذا يجوز أن تجيب بمشكلة بدل «بخير»."]},{"heading":"صيغ الجمع والاحترام","paragraphs":["توجد صيغ جمع واحترام: «نكا نغين دف؟» تخاطب جماعة أو أسرة كبيرة باحترام بدل شخص واحد.","في داكار يخلط المتحدثون الولوف والفرنسية بحرية في العمل، لكن تسلسل التحية نفسه يبقى غالباً بالولوف.","تختلف طول التحية اختلافاً حاداً بين داكار وكازامانس والريف، وكثير من المحادثات الحضرية تتجاوز الأقارب كلياً."]}],"de":[{"heading":"Anerkennung vor dem Gespräch","paragraphs":["Eine Begegnung beginnt mit Salaamaalekum, dann folgt Naka nga def? – wie geht es dir –, beantwortet mit Maa ngi fi rekk, ich bin nur hier.","Der Gruß geht weiter, indem man der Reihe nach nach jedem Angehörigen fragt; dieselbe Frage kann für jedes Familienmitglied wiederholt werden.","Es geht um Anerkennung vor Information, deshalb ist es zulässig, statt „gut“ ein Problem zu nennen."]},{"heading":"Pluralformen und Respekt","paragraphs":["Es gibt Plural- und Höflichkeitsformen: Naka ngeen def? richtet sich an eine Gruppe oder einen älteren Haushalt statt an eine Person.","In Dakar mischen Sprecher Wolof und Französisch im Geschäft frei, doch die Grußsequenz selbst bleibt meist im Wolof.","Die Länge des Grußes schwankt stark zwischen Dakar, Casamance und ländlichen Gebieten; viele städtische Gespräche überspringen die Verwandten ganz."]}],"en":[{"heading":"Recognition before conversation","paragraphs":["A Wolof encounter opens with Salaamaalekum, then Naka nga def? (how are you), answered Maa ngi fi rekk (I am here only).","Greetings continue by asking after each relative in turn, and the asker may repeat the same question for every family member.","The ritual is about recognition before information, so answering with a problem rather than fine is acceptable."]},{"heading":"Plural forms and respect","paragraphs":["Plural and respectful forms exist: Naka ngeen def? addresses a group or an elder household rather than one person.","Dakar speakers mix Wolof and French freely in business, but the greeting sequence itself usually stays in Wolof.","Greeting length varies sharply between Dakar, Casamance and rural areas; not every Wolof speaker follows the full sequence, and many urban conversations skip the relatives entirely."]}]},"context":{"countries":["SN"],"region":"Western Senegal (Dakar, Thies, Saint-Louis)","continent":"africa","languages":["wo","fr"],"period":"contemporary"},"tags":["communication","Western Senegal (Dakar, Thies, Saint-Louis)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Wolof language","de":"Wolof language","en":"Wolof language"},"url":"https://en.wikipedia.org/wiki/Wolof_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Senegal","de":"Languages of Senegal","en":"Languages of Senegal"},"url":"https://en.wikipedia.org/wiki/Languages_of_Senegal","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"شاب يدخل فناءً في تييس فيسلّم على كل كبير على حدة ويبقى واقفاً حتى يردّ الأكبر، لأن تحية بلا ردّ ستجعل الأسرة كلها تبدو غير مرحّبة.","de":"Ein junger Mann betritt einen Hof in Thies, grüßt jeden Älteren einzeln und bleibt stehen, bis der Älteste antwortet, denn ein unbeantworteter Gruß würde die ganze Familie unfreundlich erscheinen lassen.","en":"A young man entering a courtyard in Thies greets each elder separately and stays standing until the oldest replies, because an unanswered greeting would mark the whole family as unwelcoming."},"misunderstanding":{"ar":"يظن الزائر أن تكرار السؤال عن الأقارب حشو أو فضول، لكنه في الحقيقة إقرار بأن كل فرد في البيت حاضر في بال المتكلم.","de":"Besucher halten das wiederholte Fragen nach Verwandten für Neugier, doch es ist die Bestätigung, dass jeder im Haus im Kopf des Sprechenden präsent ist.","en":"Visitors take the repeated questions about relatives for curiosity, but they confirm that every person in the house is present in the speaker's mind."},"comparison":{"ar":"يشبه هذا التسلسل تحيات كثيرة في غرب أفريقيا، لكن ما يميزه هو إصرار السائل على المرور بكل فرد بدل سؤال واحد جامع.","de":"Ähnliche Grußketten gibt es in vielen Teilen Westafrikas, doch hier besteht der Sprecher darauf, jeden Menschen einzeln zu nennen statt mit einer Sammelfrage.","en":"Similar greeting chains exist across West Africa, but here the asker insists on naming each person rather than offering one collective question."},"expression":{"original":"Naka nga def?","language":"Wolof","gloss":{"ar":"كيف حالك؟","de":"Wie geht es dir?","en":"How are you?"},"usage":{"ar":"تقال عند افتتاح اللقاء بعد السلام عليكم، ويُجاب عليها بـ«ما نغي في ريكّ».","de":"Wird nach Salaamaalekum zur Eröffnung gesagt und mit Maa ngi fi rekk beantwortet.","en":"Said after Salaamaalekum to open an encounter, and answered with Maa ngi fi rekk."},"transliteration":"naka nga def"}},{"id":"lng-002","version":2,"slug":"sanankuya-the-malian-licence-to-insult-your-joking-cousin","contentType":"note","category":"communication","title":{"ar":"سانانكويا: رخصة المزاح في مالي","de":"Sanankuya: die Lizenz zum Necken in Mali","en":"Sanankuya: Mali's licence to insult your joking cousin"},"deck":{"ar":"علاقة قرابة طقسية تربط عائلات وقبائل، فيصبح التهكم واجباً لا إهانة، وتُبنى عليها التزامات اجتماعية حقيقية.","de":"Eine rituelle Verwandtschaft zwischen Familien und Volksgruppen macht Spott zur Pflicht statt zur Beleidigung – mit echten sozialen Verpflichtungen.","en":"A ritual kinship between families and ethnic groups makes mockery obligatory rather than offensive, and it comes with real social obligations."},"teaser":{"ar":"في مالي، قد يطالبك غريب بطعام لأنه يحمل لقباً معيناً، وعليك أن تضحك لا أن تغضب.","de":"In Mali kann ein Fremder Essen verlangen, weil sein Nachname dazugehört. Lachen ist dann Pflicht, nicht Empörung.","en":"In Mali a stranger may demand your food because of his surname. The script says you laugh, not take offence."},"readingMinutes":1,"sections":{"ar":[{"heading":"عائلات تتقاسم المزاح","paragraphs":["تربط سانانكويا عائلات بأكملها أو جماعات عرقية، مثل مزارعي البامبارا وصيادي البوزو، في علاقة يكون فيها السخرية إلزامية لا مسيئة.","قد يطالب المازح بالطعام، أو يتهم الآخر بالجشع، أو يناديه بابن عبد، وعلى الطرف الآخر أن يضحك بدل أن يرد.","تحمل العلاقة واجبات: على الطرفين المساعدة في الأعراس والجنازات، ومنع أي خلاف من التصاعد."]},{"heading":"من اللقب إلى السياسة","paragraphs":["أسماء العائلات تُفعّل العلاقة عند التعارف، فيحمل اللقب توقعات اجتماعية قبل أن يُعرف أي شيء آخر عن صاحبه.","استخدمت مالي في انتقالها الديمقراطي في التسعينيات خطاب سانانكويا علناً للمصالحة بين نخب الشمال والجنوب.","تختلف الممارسة بين المدينة والريف وبين الأجيال، فكثير من الشباب في باماكو يعرفون القاعدة لكنهم يمارسونها بشكل رمزي أكثر."]}],"de":[{"heading":"Familien, die Spott teilen","paragraphs":["Sanankuya verbindet ganze Clans oder Volksgruppen, etwa Bambara-Bauern und Bozo-Fischer, in einer Beziehung, in der Neckerei Pflicht und nicht Beleidigung ist.","Ein Scherzpartner darf Essen fordern, den anderen der Gier bezichtigen oder ihn Nachkomme eines Sklaven nennen; der Betroffene muss lachen statt zurückzuschlagen.","Die Beziehung bringt Pflichten mit sich: Beide Seiten helfen bei Hochzeiten und Beerdigungen und dürfen einen Streit nicht eskalieren lassen."]},{"heading":"Vom Nachnamen zur Politik","paragraphs":["Familiennamen lösen die Beziehung bei der Vorstellung aus, sodass ein Nachname soziale Erwartungen weckt, bevor man sonst etwas weiß.","Malis demokratischer Übergang in den 1990er Jahren nutzte die Sanankuya-Rhetorik öffentlich, um politische Eliten aus Nord und Süd zu versöhnen.","Die Praxis unterscheidet sich regional und zwischen Generationen: Viele junge Menschen in Bamako kennen die Regel, leben sie aber eher symbolisch."]}],"en":[{"heading":"Families that trade insults","paragraphs":["Sanankuya pairs whole clans or ethnic groups, for example Bambara farmers and Bozo fishers, in a relationship where mockery is obligatory rather than offensive.","A joker may demand food, accuse the other of greed or call them a slave's descendant, and the target must laugh rather than retaliate.","The relationship carries obligations: the parties must help at weddings and funerals and must not let a quarrel escalate."]},{"heading":"From surname to politics","paragraphs":["Family names can trigger the relationship on introduction, so a surname carries social expectations before anything else is known.","Mali's 1990s democratic transition used sanankuya rhetoric publicly to reconcile northern and southern political elites.","Practice varies by region and generation: many young people in Bamako know the rule but live it more symbolically than their grandparents do."]}]},"context":{"countries":["ML"],"region":"Mali (Bamako, Segou, Mopti)","continent":"africa","languages":["bm","fr"],"period":"contemporary"},"tags":["communication","Mali (Bamako, Segou, Mopti)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Joking relationship","de":"Joking relationship","en":"Joking relationship"},"url":"https://en.wikipedia.org/wiki/Joking_relationship","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bambara language","de":"Bambara language","en":"Bambara language"},"url":"https://en.wikipedia.org/wiki/Bambara_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يلتقي غريبان في باماكو فيكتشفان أنهما تراوري وديارا؛ يطالب التراوري فوراً الديارا بعنزة، ويصبح ذلك التهكم المتوقع سبباً لتبادل أرقام الهاتف.","de":"Zwei Fremde treffen sich in Bamako und stellen fest, dass sie Traore und Diarra sind; der Traore verlangt sofort eine Ziege vom Diarra, und der eingeübte Spott wird zum Grund, Telefonnummern zu tauschen.","en":"Two strangers meeting in Bamako discover they are Traore and Diarra; the Traore immediately claims the Diarra owes him a goat, and the scripted insult becomes the reason they exchange phone numbers."},"misunderstanding":{"ar":"ليست كل الألقاب أو الأزواج العرقية في مالي تحمل سانانكويا، والممارسة الحضرية غالباً رمزية. التهكم دورٌ متفق عليه، وليس رخصة للزائر كي يرتجل.","de":"Nicht jeder malische Name und nicht jede Gruppierung trägt Sanankuya, und in der Stadt bleibt die Praxis oft symbolisch. Die Neckerei ist eingeübtes Rollenspiel, keine Lizenz für Besucher zum Improvisieren.","en":"Not every Malian name or ethnic pairing carries sanankuya, and urban practice is often symbolic. The insults are scripted role-play, never a licence for a visitor to improvise."},"comparison":{"ar":"يشبه هذا العُرف المزاح العائلي في ثقافات أخرى، لكنه في مالي مرتبط بألقاب محددة وبالتزامات واضحة في الأفراح والأحزان.","de":"Ähnlich wie familiärer Spott in anderen Kulturen, ist Sanankuya in Mali an bestimmte Nachnamen und klare Pflichten bei Festen und Trauerfällen gebunden.","en":"Like family teasing elsewhere, sanankuya is bounded: it attaches to specific surnames and brings duties at weddings and funerals, not free insults for everyone."},"expression":{"original":"Sanankuya","language":"Bamanankan (Bambara)","gloss":{"ar":"علاقة مزاح / دعابة مميزة","de":"Scherzverwandtschaft / privilegiertes Necken","en":"joking relationship / privileged banter"},"usage":{"ar":"تُذكر عند التعريف بالنفس أو شرح علاقة بين عائلتين أو جماعتين.","de":"Wird genannt, wenn man sich vorstellt oder eine Beziehung zwischen zwei Familien erklärt.","en":"Used when introducing yourself or explaining a bond between two families or groups."},"transliteration":"sanankuya"}},{"id":"lng-003","version":2,"slug":"three-tones-one-syllable-how-yoruba-pitch-separates-hand-respect-and-money","contentType":"language","category":"languages","title":{"ar":"ثلاث نغمات، مقطع واحد: كيف يفصل اليوروبا بين اليد والاحترام والمال","de":"Drei Töne, eine Silbe: Wie Yoruba Hand, Respekt und Geld trennt","en":"Three tones, one syllable: how Yoruba pitch separates hand, respect and money"},"deck":{"ar":"في جنوب غرب نيجيريا، تعتمد لغة اليوروبا على النغمة لتمييز الكلمات وتحديد الأدوار النحوية، مما يجعل الكتابة بدون علامات نغمية تحديًا يوميًا.","de":"Im Südwesten Nigerias entscheidet die Tonhöhe in der Yoruba-Sprache über Wortbedeutung und grammatische Rollen – ein Alltagsphänomen mit Tücken in der Schrift.","en":"In southwest Nigeria, Yoruba uses pitch to distinguish words and grammatical roles, making written communication without tone marks a daily challenge."},"teaser":{"ar":"لغة اليوروبا تستخدم ثلاث نغمات لتغيير معاني الكلمات، فكلمة واحدة قد تعني يدًا أو احترامًا أو مالًا حسب النغمة.","de":"Yoruba nutzt drei Tonhöhen, um Wörter zu unterscheiden: Ein und dieselbe Silbe kann Hand, Respekt oder Geld bedeuten – je nach Ton.","en":"Yoruba uses three pitch levels to change meaning: one syllable can mean hand, respect or money depending on the tone."},"readingMinutes":1,"sections":{"ar":[{"heading":"النغمة تصنع المعنى","paragraphs":["في لغة اليوروبا، تُحدد ثلاث مستويات للنغمة باستخدام علامات التشكيل: النغمة العالية والنغمة المنخفضة، بينما النغمة المتوسطة غير المشكولة لا تقل تمييزًا عنهما. على سبيل المثال، كلمة Ọwọ́ تعني \"يد\"، وọ̀wọ̀ تعني \"احترام\"، وowó تعني \"مال\". الكلمتان الأوليان تشتركان في الحروف الساكنة والمتحركة وتختلفان فقط في النغمة.","النغمة لا تقتصر على المفردات، بل تحمل أيضًا وظيفة نحوية. الضمير المكتوب o يعني \"أنت\" على نغمة معينة، و\"هو\" أو \"هي\" على نغمة أخرى، لذا فإن طبقة الصوت تحدد دور الكلمة في الجملة."]},{"heading":"الكتابة والتحديات اليومية","paragraphs":["تُكتب اليوروبا بنقاط تحت الحروف e وo وs بالإضافة إلى علامات النغمة. لكن على لوحات المفاتيح التي تفتقر إلى هذه العلامات، يضطر القراء إلى استنتاج المعنى من السياق. هذا الوضع شائع في الرسائل النصية ووسائل التواصل الاجتماعي.","اليوروبا هي إحدى اللغات الوطنية الثلاث في نيجيريا وتُدرّس في مدارس الجنوب الغربي، لكن اللغة الإنجليزية تهيمن على التعليم الثانوي العالي. يختلف إدراك النغمة في الكلام السريع بين اللهجات المختلفة، مما يضيف طبقة من التعقيد للمتعلمين."]}],"de":[{"heading":"Tonhöhe als Bedeutungsträger","paragraphs":["Yoruba markiert drei Tonhöhen mit Akzenten: hoch, tief und unmarkiert mittel, wobei auch der mittlere Ton bedeutungsunterscheidend ist. So bedeutet Ọwọ́ „Hand“, ọ̀wọ̀ „Respekt“ und owó „Geld“. Die ersten beiden teilen Konsonanten und Vokale und unterscheiden sich nur im Ton.","Töne tragen auch Grammatik: Das Pronomen o bedeutet auf einer Tonhöhe „du“, auf einer anderen „er“ oder „sie“. Die Tonhöhe bestimmt also die Satzrolle."]},{"heading":"Schrift und tägliche Herausforderungen","paragraphs":["Geschrieben wird Yoruba mit Unterpunkten für e, o und s sowie Tonzeichen. Auf Tastaturen ohne Diakritika müssen Leser die Bedeutung aus dem Kontext erschließen – ein häufiges Problem in Chats und sozialen Medien.","Yoruba ist eine der drei Nationalsprachen Nigerias und wird in Schulen im Südwesten unterrichtet, doch in der Oberstufe dominiert Englisch. Die Tonrealisierung variiert in schneller Sprache und zwischen regionalen Varietäten, was das Verständnis für Lernende erschwert."]}],"en":[{"heading":"Pitch makes meaning","paragraphs":["Yoruba marks three pitch levels with acute and grave accents, and the unmarked mid tone is just as contrastive as the others. For example, Ọwọ́ means hand, ọ̀wọ̀ means respect, and owó means money. The first two share consonants and vowels and differ only in tone.","Tone also does grammar: the pronoun written o means you on one pitch and he or she on another, so pitch carries sentence roles."]},{"heading":"Writing and daily challenges","paragraphs":["Yoruba is written with sub-dots for e, o and s plus tone marks, so keyboards without diacritics force readers to infer from context. This is common in text messages and social media.","It is one of Nigeria's three national languages and is taught in southwest schools, though English dominates upper secondary. Tone realisation shifts in fast speech and differs between Yoruba varieties, adding complexity for learners."]}]},"context":{"countries":["NG"],"region":"Southwest Nigeria (Lagos, Oyo, Osun)","continent":"africa","languages":["yo","en"],"period":"contemporary"},"tags":["languages","Southwest Nigeria (Lagos, Oyo, Osun)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Yoruba language","de":"Yoruba language","en":"Yoruba language"},"url":"https://en.wikipedia.org/wiki/Yoruba_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Tone (linguistics)","de":"Tone (linguistics)","en":"Tone (linguistics)"},"url":"https://en.wikipedia.org/wiki/Tone_(linguistics)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في إحدى محطات الراديو في لاغوس، يكتب مذيع الكلمات o-w-o على لوحة بيضاء ويسأل المستمعين عن الكلمة التي سمعوها؛ فقط علامات النغمة والحركات توضح ما إذا كانت الجملة تتعلق بيد أو احترام أو مال.","de":"Ein Radiomoderator in Lagos schreibt die Buchstaben o-w-o an die Tafel und fragt die Hörer, welches Wort sie gehört haben; nur Ton- und Vokalzeichen verraten, ob es um Hand, Respekt oder Geld geht.","en":"A Lagos radio presenter writes the letters o-w-o on a whiteboard and asks listeners which word they heard; only the tone and vowel marks tell them whether the sentence concerns a hand, respect or money."},"misunderstanding":{"ar":"غالبًا ما يُفترض أن النغمة مجرد تلوين صوتي، لكنها في اليوروبا عنصر أساسي لتحديد المعنى والوظيفة النحوية.","de":"Oft wird angenommen, Töne seien nur Klangfärbung, doch im Yoruba sind sie entscheidend für Bedeutung und Grammatik.","en":"People often assume tone is just intonation, but in Yoruba it is essential for meaning and grammar."},"comparison":{"ar":"على عكس اللغات التي تعتمد على ترتيب الكلمات أو الصرف لتحديد الأدوار، تعتمد اليوروبا بشكل كبير على النغمة، مما يجعلها سمة بارزة في التواصل اليومي.","de":"Anders als Sprachen, die Wortstellung oder Flexion nutzen, verlässt sich Yoruba stark auf Töne – eine Besonderheit im Alltag.","en":"Unlike languages that rely on word order or inflection, Yoruba depends heavily on tone, a distinctive feature of everyday communication."},"expression":{"original":"Ọwọ́","language":"Yorùbá (Yoruba)","gloss":{"ar":"يد (مقابل ọ̀wọ̀ احترام، owó مال)","de":"Hand (vs. ọ̀wọ̀ Respekt, owó Geld)","en":"hand (vs. ọ̀wọ̀ respect, owó money)"},"usage":{"ar":"تُستخدم للإشارة إلى اليد، وتختلف عن كلمتي الاحترام والمال فقط في النغمة.","de":"Bezeichnet die Hand und unterscheidet sich nur durch den Ton von den Wörtern für Respekt und Geld.","en":"Refers to the hand and differs only in tone from the words for respect and money."},"transliteration":"ọwọ́"}},{"id":"lng-004","version":2,"slug":"nnoo-the-igbo-welcome-that-is-followed-by-a-kola-nut-not-a-question","contentType":"scene","category":"communication","title":{"ar":"ننو: ترحيب الإيغبو الذي تتبعه كولا لا سؤال","de":"Nnọọ: die Igbo-Begrüßung, auf die eine Kolanuss folgt","en":"Nnọọ: the Igbo welcome followed by kola, not questions"},"deck":{"ar":"في جنوب شرق نيجيريا يبدأ استقبال الضيف بكلمة ترحيب وجوزة كولا، لا بسؤال عن سبب الزيارة.","de":"Im Südosten Nigerias beginnt Gastfreundschaft mit einem Willkommen und einer Kolanuss – nicht mit der Frage nach dem Grund des Besuchs.","en":"In southeast Nigeria, hospitality starts with a welcome and a kola nut, not with asking a visitor why they came."},"teaser":{"ar":"كيف يغيّر تقديم الكولا مجرى الحديث في بيوت الإيغبو، ولماذا يُقرأ الرفض كرفض للبيت لا للجوزة؟","de":"Warum die Kolanuss vor jedem Gespräch geteilt wird und weshalb ihre Ablehnung wie eine Ablehnung des Hauses wirken kann.","en":"Why a kola nut is offered and shared before any business is discussed, and why refusing it can feel like refusing the household."},"readingMinutes":1,"sections":{"ar":[{"heading":"الترحيب قبل السؤال","paragraphs":["كلمة ننو هي التحية المعتادة في جنوب شرق نيجيريا، وتُوسَّع إلى «ننو نولو» أي مرحبًا في البيت، ويُجاب عنها بـ«دالو» أي شكرًا. لكن الضيف لا يُسأل عن غرضه فورًا: تُقدَّم الكولا والماء أولًا، وتُبارَك الجوزة وتُقسَّم قبل أن يُفتح أي حديث عمل.","للكولا مفرداتها الخاصة في التقديم والرفض، ورفضها قد يُفهم كرفض للبيت لا للجوزة نفسها. ولهذا يحرص المضيف على عرضها بطريقة لا تُحرج الزائر."]},{"heading":"تحيات تتبع النهار واللهجات","paragraphs":["تتغير التحيات مع ساعات اليوم: «أوتوتو أوما» صباح الخير، و«إهيهيي أوما» بعد الظهر، و«مغبيدي أوما» مساءً. وهي صيغ يتعلمها الناس في البيت والمدرسة معًا.","للإيغبو لهجات كثيرة، فتختلف كلمات الترحيب بين أونيتشا ونسوكا وأويري، والإيغبو المعيارية إلى حد كبير بناء مدرسي. ويختلف الاستقبال أيضًا بين الأجيال والمدن: بعض الأسر تستبدل الكولا بدعاء ومشروبات باردة، ومضيفون أصغر قد يتجاوزون الطقس كليًا."]},{"heading":"لماذا يهم هذا","paragraphs":["الترحيب هنا ليس مجاملة عابرة بل ترتيب للعلاقة: من يجلس، ومن يبدأ الكلام، ومتى يُسمح بالسؤال. من يفهم هذا الترتيب يجد الباب مفتوحًا أسرع."]}],"de":[{"heading":"Willkommen vor der Frage","paragraphs":["Nnọọ ist die übliche Begrüßung im Südosten Nigerias, oft erweitert zu Nnọọ n'ụlọ, willkommen im Haus, und mit Daalụ, danke, beantwortet. Doch Gäste werden nicht sofort nach ihrem Anliegen gefragt: Zuerst kommen Kolanuss und Wasser, die Nuss wird dargebracht, gesegnet und geteilt, bevor über Geschäfte gesprochen wird.","Die Kola, ọjị, hat ein eigenes Vokabular des Anbietens und Ablehnens. Wer sie zurückweist, kann so verstanden werden, als lehne er den Haushalt ab und nicht die Nuss."]},{"heading":"Grußformeln nach Tageszeit und Dialekt","paragraphs":["Die Grüße folgen dem Tag: Ụtụtụ ọma am Morgen, Ehihie ọma am Nachmittag, Mgbede ọma am Abend. Man lernt sie zu Hause und in der Schule.","Igbo hat viele Dialekte, daher unterscheiden sich Willkommensworte zwischen Onitsha, Nsukka und Owerri; Standard-Igbo ist weitgehend eine Schulkonstruktion. Auch zwischen Generationen und Städten variiert der Empfang: Manche Familien ersetzen die Kola durch ein Gebet und Erfrischungsgetränke, jüngere Gastgeber lassen das Ritual ganz weg."]},{"heading":"Warum das zählt","paragraphs":["Die Begrüßung ordnet die Beziehung: wer sitzt, wer zuerst spricht und wann eine Frage erlaubt ist. Wer diese Ordnung kennt, ist schneller wirklich angekommen."]}],"en":[{"heading":"Welcome before the question","paragraphs":["Nnọọ is the standard welcome in southeast Nigeria, often extended to Nnọọ n'ụlọ, welcome into the house, and answered Daalụ, thank you. Guests are not asked their business straight away: kola nut and water come first, the nut is presented, blessed and shared before any discussion begins.","Kola, ọjị, has its own vocabulary of offering and refusal. Turning it down can read as rejecting the household rather than the nut, so hosts present it carefully."]},{"heading":"Greetings that follow the day and the dialect","paragraphs":["Greetings change with the day: Ụtụtụ ọma in the morning, Ehihie ọma in the afternoon, Mgbede ọma in the evening. People learn them at home and at school.","Igbo has many dialects, so welcome words differ between Onitsha, Nsukka and Owerri, and standard Igbo is largely a school construction. Reception also varies by generation and city: some families substitute a prayer and soft drinks, and younger hosts may skip the ritual entirely."]},{"heading":"Why this matters","paragraphs":["A welcome here arranges the relationship: who sits, who speaks first and when a question is allowed. Knowing the order is what actually gets a visitor through the door."]}]},"context":{"countries":["NG"],"region":"Southeast Nigeria (Enugu, Onitsha, Owerri)","continent":"africa","languages":["ig","en"],"period":"contemporary"},"tags":["communication","Southeast Nigeria (Enugu, Onitsha, Owerri)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Igbo language","de":"Igbo language","en":"Igbo language"},"url":"https://en.wikipedia.org/wiki/Igbo_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Igbo culture","de":"Igbo culture","en":"Igbo culture"},"url":"https://en.wikipedia.org/wiki/Igbo_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زائر لبيت في أويري يُناول جوزة كولا قبل أن يُسأل عن سبب مجيئه؛ وإلى أن تُكسر الجوزة وتُقسَّم يبقى الحديث في العائلة والصحة والطريق.","de":"Ein Besucher in einem Haus in Owerri erhält eine Kolanuss, bevor er gefragt wird, warum er kam; bis die Nuss gebrochen und geteilt ist, bleibt das Gespräch bei Familie, Gesundheit und der Reise.","en":"A visitor to an Owerri home is handed a kola nut before being asked why they came; until the nut is broken and shared, the conversation stays on family, health and the journey."},"misunderstanding":{"ar":"الزائر الغريب قد يظن أن تقديم الكولا مجرد ضيافة شكلية، أو أن رفضها أدب، بينما هي في نظر المضيف جواب عن السؤال الذي لم يُطرح بعد.","de":"Fremde halten die Kola oft für reine Höflichkeitsform oder die Ablehnung für gutes Benehmen – für Gastgeber ist sie die Antwort auf die noch ungestellte Frage.","en":"Outsiders may treat the kola as mere politeness, or refusal as good manners, when the host reads it as an answer to the question not yet asked."},"comparison":{"ar":"في كثير من الثقافات يُستقبل الضيف بسؤال مباشر عن حاجته؛ أما هنا فيُستقبل بشيء يُؤكل ويُشارَك أولًا، فيصبح السؤال لاحقًا جزءًا من العلاقة لا شرطًا لها.","de":"In vielen Kulturen wird der Gast direkt nach seinem Anliegen gefragt; hier wird zuerst etwas geteilt und gegessen, sodass die Frage später Teil der Beziehung ist statt ihrer Voraussetzung.","en":"Many cultures greet a guest by asking directly what they need; here something is shared and eaten first, so the question later becomes part of the relationship rather than its precondition."},"expression":{"original":"Nnọọ","language":"Igbo","gloss":{"ar":"مرحبًا","de":"willkommen","en":"welcome"},"usage":{"ar":"تُقال عند استقبال الضيف، وتُوسَّع إلى «ننو نولو» عند دعوته إلى الدخول، ويُجاب عنها بـ«دالو».","de":"Zur Begrüßung von Gästen, erweitert zu Nnọọ n'ụlọ beim Hereinkommen; Antwort ist Daalụ, danke.","en":"Said when receiving a guest, extended to Nnọọ n'ụlọ when inviting them inside, and answered with Daalụ, thank you."},"transliteration":"nnọọ"}},{"id":"lng-005","version":2,"slug":"shikamoo-the-swahili-greeting-that-lowers-the-younger-speaker","contentType":"note","category":"communication","title":{"ar":"شيكامو: تحية سواحيلية تُنزل المتحدث الأصغر","de":"Shikamoo: der Swahili-Gruß, der Jüngere tiefer stellt","en":"Shikamoo: the Swahili greeting that lowers the younger speaker"},"deck":{"ar":"تحية شيكامو تُستخدم مع كبار السن، ويرد عليها بكلمة مرحبا. تعلم الأطفال في تنزانيا استخدامها قبل التحدث مع أي شخص أكبر سنًا.","de":"Shikamoo wird an Ältere gerichtet, die erwartete Antwort ist Marahaba. In Tansania lernen Kinder den Gruß früh genug, um ihn vor jedem älteren Menschen zu verwenden.","en":"Shikamoo is addressed to elders, and the expected reply is Marahaba. Tanzanian children learn it early enough to use it before speaking to any older person."},"teaser":{"ar":"شيكامو، التي تعني حرفيًا 'أمسك قدميك'، هي تحية تُظهر الاحترام للكبار، ويُتوقع الرد عليها بـ 'مرحبا'. تعرف كيف تُستخدم في الحياة اليومية.","de":"Shikamoo, wörtlich 'Ich halte deine Füße', ist ein respektvoller Gruß an Ältere. Die erwartete Antwort ist Marahaba. So wird er im Alltag verwendet.","en":"Shikamoo, literally 'I hold your feet', is a respectful greeting to elders. The expected reply is Marahaba. Here's how it works in everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"تحية تُعلن الفارق العمري","paragraphs":["شيكامو، التي تعني حرفيًا 'أمسك قدميك'، تُوجه إلى كبار السن والرؤساء، والرد المتوقع هو 'مرحبا'. يتعلمها الأطفال في تنزانيا مبكرًا بما يكفي لاستخدامها قبل التحدث مع أي شخص أكبر سنًا، بما في ذلك المعلمون وأصحاب المتاجر.","العمر وليس المنصب هو ما يثيرها عادة: الأخ الأكبر أو عامل النظافة يتلقى شيكامو، بينما يتلقى الند 'هباري' أو 'مامبو'. مامبو التي يُرد عليها بـ 'بوا' هي التبادل غير الرسمي بين الشباب؛ والرد بـ 'بوا' على شيكامو سيكون خطأ واضحًا في المستوى اللغوي."]},{"heading":"سلاسل التحيات والسياق","paragraphs":["غالبًا ما تأتي التحيات في سلاسل: 'هوجامبو؟' (هل أنت بخير) يتبعها 'سيجامبو' (أنا بخير) ثم أخبار عن العائلة. في غرفة موظفي دار السلام، يُحيي خريج جديد عامل النظافة الأكبر سنًا بـ شيكامو قبل تحية الزملاء بـ مامبو؛ فيرد عامل النظافة بـ مرحبا، ويحدد التبادل بهدوء من هو الأصغر.","يختلف الاستخدام إقليميًا وجيليًا: فهو أقوى على الساحل وفي تنزانيا منه في المناطق الداخلية من كينيا، حيث قد تحل 'هباري' أو 'سازا' محلها؛ وفي المدن، قد يختصر الشباب الشكل أو يلعبون به."]}],"de":[{"heading":"Ein Gruß, der den Altersunterschied markiert","paragraphs":["Shikamoo, wörtlich 'Ich halte deine Füße', wird an Ältere und Vorgesetzte gerichtet, und die erwartete Antwort ist Marahaba. Der Gruß wird in Tansania so früh gelehrt, dass Kinder ihn verwenden, bevor sie mit irgendeiner älteren Person sprechen, einschließlich Lehrern und Ladenbesitzern.","Das Alter und nicht der Rang löst ihn meist aus: Ein älteres Geschwister oder eine Reinigungskraft erhält Shikamoo, während ein Gleichaltriger Habari oder Mambo erhält. Mambo, beantwortet mit Poa, ist der informelle Jugendaustausch; Poa auf Shikamoo zu antworten, wäre ein klarer Registerfehler."]},{"heading":"Grußketten und Kontext","paragraphs":["Begrüßungen kommen oft in Ketten: Hujambo? (geht es dir gut), gefolgt von Sijambo (mir geht es gut) und dann Neuigkeiten über die Familie. In einem Lehrerzimmer in Daressalam begrüßt ein frisch Graduierter die älteste Reinigungskraft mit Shikamoo, bevor er Kollegen mit Mambo begrüßt; die Reinigungskraft antwortet mit Marahaba, und der Austausch klärt still, wer der Jüngere ist.","Die Verwendung variiert regional und generationell: Sie ist an der Küste und in Tansania stärker als im Landesinneren Kenias, wo Habari oder Sasa an ihre Stelle treten können; junge Stadtbewohner verkürzen oder spielen manchmal mit der Form."]}],"en":[{"heading":"A greeting that marks the age gap","paragraphs":["Shikamoo, literally 'I hold your feet', is addressed to elders and superiors, and the expected reply is Marahaba. The greeting is taught early enough that Tanzanian children use it before speaking to any older person, including teachers and shopkeepers.","Age rather than rank usually triggers it: an older sibling or a cleaner receives shikamoo, while a peer receives habari or mambo. Mambo answered with Poa is the informal youth exchange; answering Poa to shikamoo would be a clear register error."]},{"heading":"Greeting chains and context","paragraphs":["Greetings often come in chains: Hujambo? (are you well) followed by Sijambo (I am well) and then news about the family. In a Dar es Salaam staffroom a new graduate greets the oldest cleaner with shikamoo before greeting colleagues with mambo; the cleaner answers marahaba and the exchange quietly settles who is junior.","Usage varies regionally and generationally: it is stronger on the coast and in Tanzania than in inland Kenya, where habari or sasa may replace it; young urban speakers sometimes shorten or play with the form."]}]},"context":{"countries":["TZ","KE"],"region":"Swahili coast (Dar es Salaam, Zanzibar, Mombasa)","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["communication","Swahili coast (Dar es Salaam, Zanzibar, Mombasa)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Swahili","de":"Swahili","en":"Swahili"},"url":"https://en.wikipedia.org/wiki/Swahili","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Swahili culture","de":"Swahili culture","en":"Swahili culture"},"url":"https://en.wikipedia.org/wiki/Swahili_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في غرفة موظفي دار السلام، يُحيي خريج جديد عامل النظافة الأكبر سنًا بـ شيكامو قبل تحية الزملاء بـ مامبو؛ فيرد عامل النظافة بـ مرحبا، ويحدد التبادل بهدوء من هو الأصغر.","de":"In einem Lehrerzimmer in Daressalam begrüßt ein frisch Graduierter die älteste Reinigungskraft mit Shikamoo, bevor er Kollegen mit Mambo begrüßt; die Reinigungskraft antwortet mit Marahaba, und der Austausch klärt still, wer der Jüngere ist.","en":"In a Dar es Salaam staffroom a new graduate greets the oldest cleaner with shikamoo before greeting colleagues with mambo; the cleaner answers marahaba and the exchange quietly settles who is junior."},"misunderstanding":{"ar":"الرد بـ 'بوا' على شيكامو خطأ واضح في المستوى اللغوي، لأن 'بوا' هي رد غير رسمي على 'مامبو' بين الشباب.","de":"Poa auf Shikamoo zu antworten, wäre ein klarer Registerfehler, da Poa die informelle Antwort auf Mambo unter Jugendlichen ist.","en":"Answering Poa to shikamoo would be a clear register error, since Poa is the informal reply to mambo among peers."},"comparison":{"ar":"شيكامو تُوجه عادةً لمن هو أكبر سنًا، بينما 'هباري' أو 'مامبو' تُوجه إلى الند. العمر وليس المنصب هو ما يثيرها عادة.","de":"Shikamoo wird normalerweise an Ältere gerichtet, während Habari oder Mambo an Gleichaltrige gehen. Das Alter und nicht der Rang löst ihn meist aus.","en":"Shikamoo is usually addressed to someone older, while habari or mambo goes to a peer. Age rather than rank usually triggers it."},"expression":{"original":"Shikamoo","language":"Kiswahili (Swahili)","gloss":{"ar":"أمسك قدميك (تحية احترام لكبير السن)","de":"Ich halte deine Füße (respektvoller Gruß an einen Älteren)","en":"I hold your feet (respectful greeting to an elder)"},"usage":{"ar":"تُستخدم عند تحية كبار السن والرؤساء، ويُرد عليها بـ 'مرحبا'.","de":"Wird beim Grüßen von Älteren und Vorgesetzten verwendet; die erwartete Antwort ist Marahaba.","en":"Used when greeting elders and superiors; the expected reply is Marahaba."},"transliteration":"shikamoo"}},{"id":"lng-006","version":2,"slug":"harambee-kenya-s-word-for-pulling-a-project-together-in-one-afternoon","contentType":"note","category":"languages","title":{"ar":"هارامبي: كلمة كينيا لجمع المشروع في ظهيرة واحدة","de":"Harambee: Kenias Wort für ein Projekt an einem Nachmittag","en":"Harambee: Kenya's word for pulling a project together"},"deck":{"ar":"في اجتماعات التبرع الكينية، يتعهد الجيران بالمال بصوت عالٍ واحداً تلو الآخر، ويصبح التعهد ديناً اجتماعياً يُحصَّل بعد سنوات.","de":"Bei kenianischen Spendentreffen sagen Nachbarn laut der Reihe nach Geld zu, und eine Zusage wird zur sozialen Schuld, die Jahre später eingefordert werden kann.","en":"At Kenyan fundraising meetings neighbours pledge money aloud, one by one, and a pledge becomes a social debt that may be collected years later."},"teaser":{"ar":"كلمة واحدة تجمع الجيران في ظهيرة واحدة لدفع رسوم مدرسة أو تكاليف جنازة، وتحمل في طياتها تضامناً وضغطاً اجتماعياً في آن.","de":"Ein Wort bringt Nachbarn an einem Nachmittag zusammen, um Schulgeld oder eine Beerdigung zu bezahlen – und trägt zugleich Solidarität und sozialen Druck in sich.","en":"One word gathers neighbours in a single afternoon to pay school fees or a funeral bill, carrying both solidarity and social pressure."},"readingMinutes":1,"sections":{"ar":[{"heading":"تعهد بصوت عالٍ أمام الجيران","paragraphs":["كلمة «هارامبي» تعني «لنسحب معاً»، وهي اسم الاجتماع الذي يتعهد فيه الجيران بالمال بصوت عالٍ، واحداً تلو الآخر، لرسوم مدرسة أو جنازة أو خزان ماء.","التعهدات علنية ويسجلها مجلس محلي، والتعهد دين اجتماعي قد يُحصَّل بعد سنوات. وفي بعض المناطق تُخفَّض قيمة التعهدات، وفي جيل الشباب في المدن يصبح الحضور أقل انتظاماً."]},{"heading":"تضامن يبني وميزان يضغط","paragraphs":["بأموال هارامبي بُنيت حصة كبيرة من المدارس الثانوية والمعاهد التقنية في كينيا، وما زالت هذه الاجتماعات تدفع فواتير المستشفى لأهل الحي نفسه.","لكن المؤسسة تُنتقد لأنها تضغط على الأسر الفقيرة، ولأنها تحوّل الحظوة السياسية إلى تبرع ظاهر.","وتختلف حجما وانفتاحا وضغطا اجتماعيا بين منطقة وأخرى وبين طبقة وأخرى؛ بعض الكينيين يتجنبونها، وفي المدن تحل محلها غالباً جمعيات الكنيسة أو المسجد."]}],"de":[{"heading":"Laut zugesagt vor den Nachbarn","paragraphs":["Harambee, „lasst uns zusammenziehen“, heißt das Treffen, bei dem Nachbarn laut und einer nach dem anderen Geld zusagen – für Schulgeld, eine Beerdigung oder einen Wassertank.","Die Zusagen sind öffentlich und werden von einem Komitee festgehalten; eine Zusage ist eine soziale Schuld, die Jahre später eingefordert werden kann. Je nach Region fallen die Beträge kleiner aus, und in der Stadt nehmen jüngere Leute seltener teil."]},{"heading":"Solidarität, die baut, und eine Waage, die drückt","paragraphs":["Mit Harambee-Geld wurde ein großer Teil der kenianischen Sekundarschulen und technischen Institute gebaut, und noch heute bezahlen Harambees Krankenhausrechnungen für Menschen im selben Wohnviertel.","Kritisiert wird die Einrichtung dafür, arme Haushalte unter Druck zu setzen und politische Gunst in eine sichtbare Spende zu verwandeln.","Größe, Offenheit und sozialer Druck unterscheiden sich nach Region und Klasse; manche Kenianer meiden Harambees, und in Städten ersetzen oft Kollekten der Kirche oder Moschee das Treffen."]}],"en":[{"heading":"Pledging aloud in front of neighbours","paragraphs":["Harambee, “let us pull together,” names the fundraising meeting where neighbours pledge money aloud, one by one, for school fees, a funeral or a water tank.","Pledges are public and recorded by a committee, and a pledge is a social debt that may be collected years later. Amounts and openness shift with region and generation; in cities younger people attend less regularly."]},{"heading":"Solidarity that builds and a scale that presses","paragraphs":["Harambee money built a large share of Kenya's secondary schools and technical institutes, and harambees still pay hospital bills for people in the same ward.","The institution is criticised for pressuring poor households and for turning political favour into a visible donation.","Size, openness and social pressure vary by region and class; some Kenyans avoid harambees, and church or mosque collections often replace them in cities."]}]},"context":{"countries":["KE"],"region":"Nationwide, strongest in central and western Kenya","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["languages","Nationwide, strongest in central and western Kenya"],"sources":[{"organization":"Wikipedia","title":{"ar":"Harambee","de":"Harambee","en":"Harambee"},"url":"https://en.wikipedia.org/wiki/Harambee","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Swahili","de":"Swahili","en":"Swahili"},"url":"https://en.wikipedia.org/wiki/Swahili","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في هارامبي في نيروبي لجنازة زميل، يقرأ مقدم الحفل ميزانية الأسرة ثم ينادي المتبرعين بأسمائهم؛ يتعهد موظف صغير بأجر أسبوع كي لا يُرى غائباً عن الجماعة.","de":"Bei einem Harambee in Nairobi für die Beerdigung eines Kollegen liest der Moderator das Budget der Familie vor und ruft dann die Spender beim Namen auf; ein junger Angestellter sagt ein Wochengehalt zu, statt als abwesend zu gelten.","en":"At a Nairobi harambee for a colleague's funeral the MC reads the family's budget, then calls donors by name; a junior clerk pledges a week's salary rather than be seen absent from the community."},"misunderstanding":{"ar":"يُفهم الاسم أحياناً على أنه جمع تبرعات حرّ لا يُلزم أحداً، لكن التعهد العلني في الواقع ارتباط اجتماعي يُتذكَّر ويُطالَب به.","de":"Manchmal gilt der Name als freiwillige Spendensammlung ohne Verpflichtung, doch die öffentliche Zusage ist tatsächlich eine Bindung, an die man sich erinnert.","en":"The word is sometimes taken as a free collection that obliges nobody, but a public pledge is in fact a tie that is remembered and later called in."},"comparison":{"ar":"يشبه في وظيفته صناديق المساعدة في قرى كثيرة، لكن ما يميزه أن العطاء يُعلن بالاسم ويُسجَّل أمام الجميع.","de":"Die Funktion ähnelt Nachbarschaftskassen in vielen Dörfern, doch hier wird die Gabe namentlich vor allen angekündigt und festgehalten.","en":"It works like village mutual-aid funds in many places, yet here the gift is announced by name and written down in front of everyone."},"expression":{"original":"Harambee","language":"Kiswahili (Swahili)","gloss":{"ar":"لنسحب معاً","de":"lasst uns zusammenziehen","en":"let us pull together"},"usage":{"ar":"شعار وطني واسم لاجتماع التبرع العلني","de":"Nationales Motto und Name des öffentlichen Spendentreffens","en":"National motto and name of the public fundraising meeting"},"transliteration":"harambee"}}];

export default { version: 2, items };
